'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import {
    Calendar,
    Users,
    Activity,
    AlertCircle,
    TrendingUp,
    Clock,
    ClipboardCheck,
    History,
    ArrowRight,
    LayoutDashboard
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ResponsiveContainer,
    PieChart,
    Pie,
    Cell,
    BarChart,
    Bar,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip as RechartsTooltip
} from 'recharts';

import { attendanceService } from '@/lib/services/attendance';
import { sessionsService, AttendanceSession } from '@/lib/services/sessions';
import { Loader2 } from 'lucide-react';

export default function AbsensiDashboard() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    // Real Data State
    const [stats, setStats] = useState({
        totalStudents: 0,
        presentToday: 0,
        sickPermissionToday: 0,
        alphaToday: 0
    });
    const [presenceMeter, setPresenceMeter] = useState(100);
    const [sessionAlpha, setSessionAlpha] = useState<any[]>([]);
    const [activeSession, setActiveSession] = useState<AttendanceSession | null>(null);

    const fetchData = useCallback(async () => {
        try {
            const [s, meter, alpha, currentSession] = await Promise.all([
                attendanceService.getStats(),
                attendanceService.getPresenceMeter(),
                attendanceService.getSessionAlpha(),
                sessionsService.getCurrentSession()
            ]);

            setStats(s);
            setPresenceMeter(meter);
            setSessionAlpha(alpha);
            setActiveSession(currentSession);
            setIsLoading(false);
        } catch (err) {
            console.error('Error fetching attendance data:', err);
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_absensi' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router, fetchData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50">
                <Loader2 className="w-8 h-8 text-cyan-600 animate-spin" />
            </div>
        );
    }

    if (!user) return null;

    const GAUGE_DATA = [
        { name: 'Hadir', value: presenceMeter },
        { name: 'Absen', value: 100 - presenceMeter },
    ];

    const COLORS = ['#0891b2', '#e5e7eb']; // Cyan-600 and Gray

    return (
        <div className="min-h-screen bg-gray-50 flex flex-col">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64 flex-1">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8 space-y-8">
                    {/* Header */}
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                        <div>
                            <h1 className="text-3xl font-black text-gray-800 tracking-tight flex items-center gap-3">
                                <LayoutDashboard className="w-8 h-8 text-cyan-600" />
                                Analytics Dashboard
                            </h1>
                            <p className="text-gray-500 font-medium">Monitoring kedisiplinan dan tingkat kehadiran santri.</p>
                        </div>
                        <div className="flex items-center gap-3 bg-white px-5 py-2.5 rounded-2xl border border-gray-100 shadow-sm">
                            <Calendar className="w-5 h-5 text-cyan-600" />
                            <span className="font-bold text-gray-700">
                                {new Date().toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'short', year: 'numeric' })}
                            </span>
                        </div>
                    </div>

                    {/* Top Stats: 4 Cards */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                        {[
                            { label: 'Total Santri', value: stats.totalStudents.toString(), icon: Users, color: 'blue' },
                            { label: 'Santri Hadir', value: stats.presentToday.toString(), icon: Activity, color: 'emerald' },
                            { label: 'Sakit / Izin', value: stats.sickPermissionToday.toString(), icon: AlertCircle, color: 'amber' },
                            { label: 'Alpha Hari Ini', value: stats.alphaToday.toString(), icon: TrendingUp, color: 'red' },
                        ].map((stat, i) => (
                            <div key={i} className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm hover:shadow-md transition-all">
                                <div className={`p-3 bg-${stat.color}-50 text-${stat.color}-600 rounded-2xl w-fit mb-4`}>
                                    <stat.icon className="w-6 h-6" />
                                </div>
                                <h3 className="text-3xl font-black text-gray-800 mb-1">{stat.value}</h3>
                                <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">{stat.label}</p>
                            </div>
                        ))}
                    </div>

                    {/* Middle Charts */}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                        {/* Gauge Chart (Left) */}
                        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex flex-col">
                            <div className="mb-6">
                                <h3 className="text-lg font-bold text-gray-800">Meteran Kehadiran</h3>
                                <p className="text-sm text-gray-500">Tingkat kehadiran santri pada sesi aktif.</p>
                            </div>
                            <div className="relative h-[250px] w-full mt-auto">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={GAUGE_DATA}
                                            cx="50%"
                                            cy="75%"
                                            startAngle={180}
                                            endAngle={0}
                                            innerRadius={80}
                                            outerRadius={100}
                                            paddingAngle={5}
                                            dataKey="value"
                                            stroke="none"
                                        >
                                            {GAUGE_DATA.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                            ))}
                                        </Pie>
                                    </PieChart>
                                </ResponsiveContainer>
                                {/* Absolute Label Overlay */}
                                <div className="absolute inset-0 flex items-end justify-center pb-10 pointer-events-none">
                                    <div className="text-center">
                                        <p className="text-5xl font-black text-gray-800 leading-none">{presenceMeter}%</p>
                                        <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mt-1">Hadir</p>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Bar Chart (Right) */}
                        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex flex-col">
                            <div className="mb-6">
                                <h3 className="text-lg font-bold text-gray-800">Ketidakhadiran per Sesi</h3>
                                <p className="text-sm text-gray-500">Jumlah santri yang tidak hadir tanpa keterangan.</p>
                            </div>
                            <div className="h-[250px] w-full mt-auto">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={sessionAlpha} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                                        <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" vertical={false} />
                                        <XAxis
                                            dataKey="name"
                                            axisLine={false}
                                            tickLine={false}
                                            tick={{ fontSize: 12, fill: '#9ca3af', fontWeight: 600 }}
                                        />
                                        <YAxis
                                            axisLine={false}
                                            tickLine={false}
                                            tick={{ fontSize: 12, fill: '#9ca3af' }}
                                        />
                                        <RechartsTooltip
                                            cursor={{ fill: '#fef2f2' }}
                                            contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                                        />
                                        <Bar dataKey="alpha" fill="#0891b2" radius={[6, 6, 0, 0]} barSize={40} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </div>

                    {/* Bottom Section */}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                        {/* Card 1: Sesi Aktif */}
                        <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-6 group hover:border-cyan-200 transition-all">
                            <div className="w-16 h-16 bg-cyan-50 text-cyan-600 rounded-2xl flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform">
                                <Clock className="w-8 h-8" />
                            </div>
                            <div className="flex-1">
                                <div className="flex items-center gap-2 mb-1">
                                    <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Sesi Saat Ini</p>
                                    {activeSession ? (
                                        <span className="px-2 py-0.5 bg-emerald-100 text-emerald-700 text-[10px] font-black rounded-full uppercase animate-pulse">Berlangsung</span>
                                    ) : (
                                        <span className="px-2 py-0.5 bg-gray-100 text-gray-500 text-[10px] font-black rounded-full uppercase">Tidak Aktif</span>
                                    )}
                                </div>
                                <h4 className="text-2xl font-black text-gray-800">
                                    {activeSession ? activeSession.name : 'Tidak Ada Sesi Aktif'}
                                </h4>
                                <div className="flex items-center gap-2 text-gray-500 font-medium">
                                    <Clock className="w-4 h-4" />
                                    <span>
                                        {activeSession
                                            ? `${activeSession.start_time?.slice(0, 5)} - ${activeSession.end_time?.slice(0, 5) || '?'}`
                                            : '-- : --'}
                                    </span>
                                </div>
                            </div>
                        </div>

                        {/* Card 2: Aksi Cepat */}
                        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm">
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 h-full">
                                <button
                                    onClick={() => router.push('/dashboard/absensi/input')}
                                    className="flex items-center justify-between p-4 bg-gray-900 text-white rounded-2xl hover:bg-gray-800 transition-all group lg:min-h-[100px]"
                                >
                                    <div className="flex flex-col items-start">
                                        <ClipboardCheck className="w-6 h-6 text-cyan-400 mb-2 group-hover:scale-110 transition-transform" />
                                        <span className="font-bold text-sm">Input Absensi</span>
                                    </div>
                                    <ArrowRight className="w-5 h-5 text-gray-500 group-hover:translate-x-1 transition-transform" />
                                </button>
                                <button
                                    onClick={() => router.push('/dashboard/absensi/rekap')}
                                    className="flex items-center justify-between p-4 bg-white border border-gray-200 text-gray-700 rounded-2xl hover:bg-gray-50 transition-all group lg:min-h-[100px]"
                                >
                                    <div className="flex flex-col items-start">
                                        <History className="w-6 h-6 text-cyan-600 mb-2 group-hover:scale-110 transition-transform" />
                                        <span className="font-bold text-sm">Lihat Rekap</span>
                                    </div>
                                    <ArrowRight className="w-5 h-5 text-gray-300 group-hover:translate-x-1 transition-transform" />
                                </button>
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import {
    getCurrentUser,
    clearSession,
    User,
} from '@/lib/auth';
import {
    Calendar,
    Search,
    Filter,
    Download,
    MoreVertical,
    XCircle,
    Clock,
    UserCheck,
    Users
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';

// ============================================
// Types
// ============================================

import { attendanceService } from '@/lib/services/attendance';
import { Loader2 } from 'lucide-react';

const STATUS_BADGE: Record<string, { label: string; class: string }> = {
    hadir: { label: 'Hadir', class: 'bg-emerald-100 text-emerald-700' },
    sakit: { label: 'Sakit', class: 'bg-amber-100 text-amber-700' },
    izin: { label: 'Izin', class: 'bg-blue-100 text-blue-700' },
    alpha: { label: 'Alpha', class: 'bg-red-100 text-red-700' },
    telat: { label: 'Telat', class: 'bg-purple-100 text-purple-700' }, // Added Telat
};

// ... (inside component)

// Safe class access

export default function AbsensiRekapPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
    const [rekapData, setRekapData] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const fetchRekap = useCallback(async () => {
        try {
            setIsLoading(true);
            const data = await attendanceService.getRekap({
                date: selectedDate,
                search: searchTerm
            });
            setRekapData(data);
        } catch (error) {
            console.error('Error fetching rekap:', error);
        } finally {
            setIsLoading(false);
        }
    }, [selectedDate, searchTerm]);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_absensi' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchRekap();
    }, [router, fetchRekap]);

    useEffect(() => {
        fetchRekap();
    }, [fetchRekap]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (!user) return null;

    const stats = {
        hadir: rekapData.filter(d => d.status === 'hadir').length,
        sakit: rekapData.filter(d => d.status === 'sakit').length,
        izin: rekapData.filter(d => d.status === 'izin').length,
        alpha: rekapData.filter(d => d.status === 'alpha').length,
    };

    return (
        <div className="min-h-screen bg-gray-50">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
                        <div>
                            <h1 className="text-2xl font-bold text-gray-800">Rekapitulasi Absensi</h1>
                            <p className="text-gray-500">Riwayat presensi santri per hari dan per kelas.</p>
                        </div>
                        <div className="flex items-center gap-3">
                            <button className="flex items-center gap-2 px-4 py-2.5 bg-white text-gray-700 border border-gray-200 rounded-xl font-bold hover:bg-gray-50 transition-all shadow-sm">
                                <Download className="w-5 h-5 text-gray-400" />
                                Export Excel
                            </button>
                        </div>
                    </div>

                    {/* Quick Overview */}
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                        {[
                            { label: 'Hadir', value: stats.hadir, color: 'emerald', icon: UserCheck },
                            { label: 'Sakit', value: stats.sakit, color: 'amber', icon: Clock },
                            { label: 'Izin', value: stats.izin, color: 'blue', icon: Calendar },
                            { label: 'Alpha', value: stats.alpha, color: 'red', icon: XCircle },
                        ].map((stat) => (
                            <div key={stat.label} className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
                                <div className="flex items-center justify-between mb-2">
                                    <div className={`p-2 bg-${stat.color}-50 text-${stat.color}-600 rounded-lg`}>
                                        <stat.icon className="w-4 h-4" />
                                    </div>
                                    <span className="text-xs font-bold text-emerald-500">Filtered</span>
                                </div>
                                <p className="text-xl font-black text-gray-800">{stat.value}</p>
                                <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">{stat.label}</p>
                            </div>
                        ))}
                    </div>

                    {/* Filters & Search */}
                    <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm mb-6">
                        <div className="flex flex-col lg:flex-row lg:items-center gap-4">
                            <div className="flex-1 relative">
                                <Search className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                                <input
                                    type="text"
                                    placeholder="Cari nama santri atau kelas..."
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-cyan-500/20 focus:border-cyan-500 font-medium"
                                />
                            </div>
                            <div className="flex items-center gap-3">
                                <div className="relative">
                                    <input
                                        type="date"
                                        value={selectedDate}
                                        onChange={(e) => setSelectedDate(e.target.value)}
                                        className="pl-4 pr-10 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-cyan-500/20 focus:border-cyan-500 font-medium"
                                    />
                                    <Calendar className="w-5 h-5 text-gray-400 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />
                                </div>
                                <button className="p-3 bg-gray-50 border border-gray-200 rounded-xl hover:bg-gray-100 text-gray-500">
                                    <Filter className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* DataTable */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead>
                                    <tr className="bg-gray-50/50 border-b border-gray-100 text-left">
                                        <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Santri</th>
                                        <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Kelas</th>
                                        <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Sesi</th>
                                        <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Status</th>
                                        <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Waktu Aben</th>
                                        <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest text-center">Aksi</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100 relative min-h-[200px]">
                                    {isLoading && (
                                        <tr>
                                            <td colSpan={6} className="p-0">
                                                <div className="w-full flex justify-center py-10 bg-white/50 backdrop-blur-[1px] absolute inset-0 z-10">
                                                    <Loader2 className="w-8 h-8 text-cyan-600 animate-spin" />
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                    {rekapData.map((item) => (
                                        <tr key={item.id} className="hover:bg-gray-50/50 transition-colors">
                                            <td className="px-6 py-4">
                                                <div className="flex items-center gap-3">
                                                    <div className="w-8 h-8 bg-cyan-100 text-cyan-700 rounded-full flex items-center justify-center font-bold text-xs">
                                                        {item.studentName.charAt(0)}
                                                    </div>
                                                    <p className="font-bold text-gray-800">{item.studentName}</p>
                                                </div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <span className="px-2 py-1 bg-gray-100 text-gray-600 rounded-lg text-xs font-bold">{item.studentClass}</span>
                                            </td>
                                            <td className="px-6 py-4 text-sm font-medium text-gray-600">{item.session}</td>
                                            <td className="px-6 py-4">
                                                <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider ${(STATUS_BADGE[item.status] || { class: 'bg-gray-100 text-gray-700' }).class}`}>
                                                    {(STATUS_BADGE[item.status] || { label: item.status, class: 'bg-gray-100 text-gray-700' }).label}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4 text-sm text-gray-400">{item.date}</td>
                                            <td className="px-6 py-4 text-center">
                                                <button className="p-1 hover:bg-gray-100 rounded-lg">
                                                    <MoreVertical className="w-4 h-4 text-gray-400" />
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                    {rekapData.length === 0 && !isLoading && (
                                        <tr>
                                            <td colSpan={6} className="py-12 text-center">
                                                <Users className="w-12 h-12 text-gray-200 mx-auto mb-3" />
                                                <p className="text-gray-400 font-medium">Tidak ada data absensi untuk pencarian ini.</p>
                                            </td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

