'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import {
    getCurrentUser,
    clearSession,
    User,
    UserRole,
    ROLE_NAMES,
    ROLE_COLORS
} from '@/lib/auth';
import {
    ChartCard,
    UserDistributionChart,
    LoginTrafficChart
} from '@/components/charts';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    Users,
    AlertTriangle,
    X,
    Loader2,
    Key,
    Mail,
    CheckCircle2,
    Shield,
    Plus,
    BookOpen,
    Activity,
    XCircle,
    Search,
    Edit,
    Trash2
} from 'lucide-react';

import { usersService } from '@/lib/services/users';
import { studentsService } from '@/lib/services/students';
import { teachersService } from '@/lib/services/teachers';
import { kesantrianService } from '@/lib/services/kesantrian';
import { dormitoriesService } from '@/lib/services/dormitories';
import { Profile } from '@/types/database.types';
import { pesantrenService, Pesantren } from '@/lib/services/pesantren';


// ============================================
// Types
// ============================================

interface SystemHealth {
    name: string;
    status: 'healthy' | 'warning' | 'error';
    value: string;
    icon: React.ElementType;
}

const ROLE_OPTIONS = [
    { value: 'admin_keuangan', label: 'Admin Keuangan' },
    { value: 'admin_akademik', label: 'Admin Akademik' },
    { value: 'kesantrian', label: 'Bagian Kesantrian' },
    { value: 'admin_absensi', label: 'Admin Absensi' },
    { value: 'wali_kelas', label: 'Wali Kelas' },
    { value: 'ustadz', label: 'Ustadz' },
    { value: 'wali_santri', label: 'Wali Santri' },
    { value: 'santri', label: 'Santri' },
];

export default function AdminDashboard() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterRole, setFilterRole] = useState('all');
    const [showUserModal, setShowUserModal] = useState(false);

    // Real Data State
    const [users, setUsers] = useState<any[]>([]);
    const [pesantrens, setPesantrens] = useState<Pesantren[]>([]);
    const [stats, setStats] = useState({
        totalUsers: 0,
        activeUsers: 0,
        totalPesantren: 0,
        systemHealth: 'Optimal',
    });
    const [systemHealth, setSystemHealth] = useState<SystemHealth[]>([]);
    const [userDistribution, setUserDistribution] = useState<any[]>([]);
    const [loginTraffic, setLoginTraffic] = useState<any[]>([]);
    const [pesantrenGrowth, setPesantrenGrowth] = useState<any[]>([]);

    // Form state
    const [userForm, setUserForm] = useState({
        name: '',
        email: '',
        role: '' as UserRole,
        password: '',
        pesantrenId: '',
        sendInvite: true,
    });

    // UI state
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [showSuccess, setShowSuccess] = useState(false);

    const [editingUser, setEditingUser] = useState<any>(null);

    const fetchDashboardData = useCallback(async () => {
        try {
            const safeFetch = async <T, D>(promise: Promise<T>, defaultValue: D): Promise<T | D> => {
                try {
                    return await promise;
                } catch (e) {
                    console.error('Service call failed:', e);
                    return defaultValue;
                }
            };

            const [
                allUsers,
                userStats,
                allPesantren,
                health,
                loginTrafficData,
                growthData
            ] = await Promise.all([
                safeFetch(usersService.getAll(), []),
                safeFetch(usersService.getStats(), { total: 0, active: 0, byRole: {} }),
                safeFetch(pesantrenService.getAll(), []),
                safeFetch(usersService.getSystemHealth(), []),
                safeFetch(pesantrenService.getLoginTraffic(), []),
                safeFetch(pesantrenService.getGrowthStats(), [])
            ]);

            setUsers(allUsers as any[]);
            setPesantrens(allPesantren as Pesantren[]);
            setStats({
                totalUsers: (userStats as { total: number }).total,
                activeUsers: (userStats as { active: number }).active,
                totalPesantren: (allPesantren as Pesantren[]).length,
                systemHealth: 'Optimal'
            });
            setSystemHealth(health as SystemHealth[]);
            setLoginTraffic(loginTrafficData as any[]);
            setPesantrenGrowth(growthData as any[]);

            const distribution = [
                { name: 'SaaS Admin', value: (allUsers as any[]).filter((u: any) => u.role === 'super_admin').length, color: '#8b5cf6' },
                { name: 'Unit Staff', value: (allUsers as any[]).filter((u: any) => u.role !== 'super_admin' && u.role !== 'santri' && u.role !== 'wali_santri').length, color: '#3b82f6' },
                { name: 'Santri/Wali', value: (allUsers as any[]).filter((u: any) => u.role === 'santri' || u.role === 'wali_santri').length, color: '#10b981' },
            ];
            setUserDistribution(distribution.filter(d => d.value > 0));

            setIsLoading(false);
        } catch (error) {
            console.error('Critical dashboard error:', error);
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'super_admin') {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchDashboardData();

        const unsubscribe = usersService.subscribeToChanges(() => fetchDashboardData());
        return () => {
            if (typeof unsubscribe === 'function') unsubscribe();
        };
    }, [router, fetchDashboardData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleSaveUser = async () => {
        setIsSaving(true);
        try {
            if (editingUser) {
                await usersService.update(editingUser.id, {
                    name: userForm.name,
                    email: userForm.email
                });
                alert('User berhasil diperbarui!');
            } else {
                await usersService.create(
                    userForm.email,
                    userForm.password,
                    userForm.name,
                    userForm.role,
                    '',
                    (userForm as any).pesantrenId
                );
            }
            setIsSaving(false);
            setShowUserModal(false);
            setEditingUser(null);
            setShowSuccess(true);
            setUserForm({ name: '', email: '', role: '' as UserRole, password: '', pesantrenId: '', sendInvite: true });
            setTimeout(() => setShowSuccess(false), 3000);
            fetchDashboardData();
        } catch (err: any) {
            alert('Error: ' + err.message);
            setIsSaving(false);
        }
    };

    const handleEditUser = (u: any) => {
        setEditingUser(u);
        setUserForm({
            name: u.name,
            email: u.email,
            role: u.role,
            password: '',
            pesantrenId: u.pesantren_id || '',
            sendInvite: false
        });
        setShowUserModal(true);
    };

    const handleToggleStatus = async (id: string) => {
        try {
            await usersService.toggleActive(id);
            fetchDashboardData();
        } catch (err: any) {
            alert('Gagal mengubah status: ' + err.message);
        }
    };

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-purple-600 animate-spin" />
                    <div className="text-gray-400 font-medium">Menghubungkan ke database...</div>
                </div>
            </div>
        );
    }

    // Filter users
    const filteredUsers = users.filter(u => {
        const matchSearch = u.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            u.email.toLowerCase().includes(searchQuery.toLowerCase());
        const matchRole = filterRole === 'all' || u.role === filterRole;
        return matchSearch && matchRole;
    });

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Success Toast */}
            {showSuccess && (
                <div className="fixed top-4 right-4 z-[60] bg-emerald-500 text-white px-6 py-4 rounded-xl shadow-lg flex items-center gap-3 animate-slide-up">
                    <CheckCircle2 className="w-6 h-6" />
                    <span className="font-medium">User berhasil ditambahkan!</span>
                </div>
            )}

            {/* Add User Modal */}
            {showUserModal && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-50 flex items-center justify-center p-4 transition-all duration-300">
                    <div className="bg-white dark:bg-neutral-900 rounded-3xl w-full max-w-lg shadow-2xl border border-gray-100 dark:border-white/10 overflow-hidden flex flex-col transition-all scale-100">
                        <div className="p-6 border-b border-gray-100 dark:border-white/5 flex items-center justify-between shrink-0">
                            <div>
                                <h3 className="text-lg font-bold text-gray-800 dark:text-white">
                                    {editingUser ? 'Edit User' : 'Tambah User Baru'}
                                </h3>
                                <p className="text-sm text-gray-500 dark:text-gray-400">
                                    {editingUser ? 'Perbarui informasi profil user' : 'Buat akun untuk staff atau santri baru'}
                                </p>
                            </div>
                            <button
                                onClick={() => {
                                    setShowUserModal(false);
                                    setEditingUser(null);
                                }}
                                className="p-2 hover:bg-gray-100 dark:hover:bg-white/5 rounded-lg transition-colors"
                            >
                                <X className="w-5 h-5 text-gray-400" />
                            </button>
                        </div>
                        <div className="p-6 space-y-5 overflow-y-auto max-h-[70vh]">
                            {/* Name */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Nama Lengkap</label>
                                <input
                                    type="text"
                                    value={userForm.name}
                                    onChange={(e) => setUserForm({ ...userForm, name: e.target.value })}
                                    placeholder="Masukkan nama lengkap"
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 focus:border-purple-500 dark:text-white transition-all"
                                />
                            </div>

                            {/* Email */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Email</label>
                                <div className="relative">
                                    <Mail className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                    <input
                                        type="email"
                                        value={userForm.email}
                                        onChange={(e) => setUserForm({ ...userForm, email: e.target.value })}
                                        placeholder="email@pesantren.com"
                                        className="w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 focus:border-purple-500 dark:text-white transition-all"
                                    />
                                </div>
                            </div>

                            {/* Role */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Role</label>
                                <select
                                    value={userForm.role}
                                    onChange={(e) => setUserForm({ ...userForm, role: e.target.value as UserRole })}
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-neutral-800 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 focus:border-purple-500 dark:text-white transition-all appearance-none"
                                >
                                    <option value="">-- Pilih Role --</option>
                                    {ROLE_OPTIONS.map(role => (
                                        <option key={role.value} value={role.value}>{role.label}</option>
                                    ))}
                                </select>
                            </div>

                            {/* Password */}
                            {!editingUser && (
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Password</label>
                                    <div className="relative">
                                        <Key className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                        <input
                                            type="password"
                                            value={userForm.password}
                                            onChange={(e) => setUserForm({ ...userForm, password: e.target.value })}
                                            placeholder="Minimal 8 karakter"
                                            className="w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 focus:border-purple-500 dark:text-white transition-all"
                                        />
                                    </div>
                                </div>
                            )}

                            {/* Send Invite */}
                            <label className="flex items-center gap-3 cursor-pointer group">
                                <div className="relative flex items-center">
                                    <input
                                        type="checkbox"
                                        checked={userForm.sendInvite}
                                        onChange={(e) => setUserForm({ ...userForm, sendInvite: e.target.checked })}
                                        className="w-5 h-5 rounded border-gray-300 dark:border-white/10 text-purple-600 focus:ring-purple-500 bg-gray-50 dark:bg-black/20"
                                    />
                                </div>
                                <span className="text-sm text-gray-700 dark:text-gray-300 font-medium group-hover:text-purple-600 transition-colors">Kirim undangan via email</span>
                            </label>
                        </div>
                        <div className="p-6 border-t border-gray-100 dark:border-white/5 flex gap-3 bg-gray-50 dark:bg-neutral-900/50">
                            <button
                                onClick={() => {
                                    setShowUserModal(false);
                                    setEditingUser(null);
                                }}
                                className="flex-1 py-3 border border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-300 font-medium rounded-xl hover:bg-gray-100 dark:hover:bg-white/5 transition-all"
                            >
                                Batal
                            </button>
                            <button
                                onClick={handleSaveUser}
                                disabled={isSaving}
                                className="flex-1 py-3 bg-purple-600 hover:bg-purple-700 text-white font-semibold rounded-xl transition-all flex items-center justify-center gap-2 disabled:opacity-50 shadow-lg shadow-purple-500/20 active:scale-95"
                            >
                                {isSaving ? (
                                    <>
                                        <Loader2 className="w-5 h-5 animate-spin" />
                                        Menyimpan...
                                    </>
                                ) : (
                                    editingUser ? 'Simpan Perubahan' : 'Buat Akun'
                                )}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Welcome Banner */}
                    <div className="bg-gradient-to-r from-purple-500 to-indigo-600 rounded-2xl p-6 lg:p-8 text-white mb-8">
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <div className="flex items-center gap-3 mb-2">
                                    <Shield className="w-8 h-8" />
                                    <h2 className="text-2xl font-bold">Super Admin Dashboard</h2>
                                </div>
                                <p className="text-purple-100">
                                    Kelola pengguna, konfigurasi sistem, dan pantau aktivitas.
                                </p>
                            </div>
                            <button
                                onClick={() => setShowUserModal(true)}
                                className="flex items-center gap-2 px-5 py-3 bg-white/20 hover:bg-white/30 rounded-xl font-medium transition-colors"
                            >
                                <Plus className="w-5 h-5" />
                                Tambah User Baru
                            </button>
                        </div>
                    </div>

                    {/* Stats Grid */}
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                        <div className="bg-white rounded-2xl p-5 border border-gray-100 shadow-sm">
                            <div className="w-10 h-10 bg-purple-100 rounded-xl flex items-center justify-center mb-3">
                                <Users className="w-5 h-5 text-purple-600" />
                            </div>
                            <p className="text-2xl font-bold text-gray-800">{stats.totalUsers}</p>
                            <p className="text-sm text-gray-500">Users (Global)</p>
                        </div>
                        <div className="bg-white rounded-2xl p-5 border border-gray-100 shadow-sm">
                            <div className="w-10 h-10 bg-emerald-100 rounded-xl flex items-center justify-center mb-3">
                                <CheckCircle2 className="w-5 h-5 text-emerald-600" />
                            </div>
                            <p className="text-2xl font-bold text-gray-800">{stats.activeUsers}</p>
                            <p className="text-sm text-gray-500">Active Sessions</p>
                        </div>
                        <div className="bg-white rounded-2xl p-5 border border-gray-100 shadow-sm">
                            <div className="w-10 h-10 bg-blue-100 rounded-xl flex items-center justify-center mb-3">
                                <BookOpen className="w-5 h-5 text-blue-600" />
                            </div>
                            <p className="text-2xl font-bold text-gray-800">{stats.totalPesantren}</p>
                            <p className="text-sm text-gray-500">Total Pesantren</p>
                        </div>
                        <div className="bg-white rounded-2xl p-5 border border-gray-100 shadow-sm">
                            <div className="w-10 h-10 bg-amber-100 rounded-xl flex items-center justify-center mb-3">
                                <Activity className="w-5 h-5 text-amber-600" />
                            </div>
                            <p className="text-2xl font-bold text-gray-800">{stats.systemHealth}</p>
                            <p className="text-sm text-gray-500">SaaS Health</p>
                        </div>
                    </div>

                    {/* Data Visualization Charts */}
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
                        <ChartCard
                            title="Distribusi Pengguna"
                            subtitle="Berdasarkan kategori role"
                        >
                            <UserDistributionChart data={userDistribution} height={280} />
                        </ChartCard>

                        <ChartCard
                            title="Traffic Login"
                            subtitle="7 hari terakhir"
                        >
                            <LoginTrafficChart data={loginTraffic} color="#8b5cf6" height={280} />
                        </ChartCard>

                        <ChartCard
                            title="Pertumbuhan Pesantren"
                            subtitle="Unit yang baru bergabung"
                        >
                            <LoginTrafficChart data={pesantrenGrowth} color="#10b981" height={280} />
                        </ChartCard>
                    </div>

                    {/* System Health */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6 mb-8">
                        <h3 className="font-semibold text-gray-800 mb-4 flex items-center gap-2">
                            <Activity className="w-5 h-5 text-purple-600" />
                            System Health Status
                        </h3>
                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
                            {systemHealth.map(health => (
                                <div
                                    key={health.name}
                                    className={`p-4 rounded-xl border ${health.status === 'healthy' ? 'bg-emerald-50 border-emerald-200' :
                                        health.status === 'warning' ? 'bg-amber-50 border-amber-200' :
                                            'bg-red-50 border-red-200'
                                        }`}
                                >
                                    <div className="flex items-center gap-2 mb-2">
                                        {health.status === 'healthy' ? (
                                            <CheckCircle2 className="w-4 h-4 text-emerald-600" />
                                        ) : health.status === 'warning' ? (
                                            <AlertTriangle className="w-4 h-4 text-amber-600" />
                                        ) : (
                                            <XCircle className="w-4 h-4 text-red-600" />
                                        )}
                                    </div>
                                    <p className="text-sm font-medium text-gray-800">{health.name}</p>
                                    <p className={`text-sm ${health.status === 'healthy' ? 'text-emerald-600' :
                                        health.status === 'warning' ? 'text-amber-600' :
                                            'text-red-600'
                                        }`}>{health.value}</p>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* User Management Table */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                        <div className="p-5 border-b border-gray-100">
                            <div className="flex flex-col md:flex-row md:items-center gap-4">
                                <h3 className="font-semibold text-gray-800">User Management</h3>
                                <div className="flex gap-3 md:ml-auto">
                                    <div className="relative flex-1 md:w-64">
                                        <Search className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                        <input
                                            type="text"
                                            placeholder="Cari user..."
                                            value={searchQuery}
                                            onChange={(e) => setSearchQuery(e.target.value)}
                                            className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500/30 focus:border-purple-500"
                                        />
                                    </div>
                                    <select
                                        value={filterRole}
                                        onChange={(e) => setFilterRole(e.target.value)}
                                        className="px-3 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500/30 focus:border-purple-500"
                                    >
                                        <option value="all">Semua Role</option>
                                        {ROLE_OPTIONS.map(role => (
                                            <option key={role.value} value={role.value}>{role.label}</option>
                                        ))}
                                    </select>
                                </div>
                            </div>
                        </div>

                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-gray-50 border-b border-gray-100">
                                    <tr>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">User</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Role</th>
                                        <th className="text-center p-4 text-sm font-semibold text-gray-600">Status</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Terdaftar</th>
                                        <th className="text-center p-4 text-sm font-semibold text-gray-600">Aksi</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100">
                                    {filteredUsers.map(u => {
                                        const roleColor = ROLE_COLORS[u.role as keyof typeof ROLE_COLORS] || ROLE_COLORS.ustadz;
                                        return (
                                            <tr key={u.id} className="hover:bg-white/[0.02] transition-colors group">
                                                <td className="p-4">
                                                    <div className="flex items-center gap-3">
                                                        <div className={`w-10 h-10 rounded-full flex items-center justify-center ${roleColor.bg}`}>
                                                            <span className={`font-medium ${roleColor.text}`}>{u.name.charAt(0)}</span>
                                                        </div>
                                                        <div>
                                                            <p className="font-medium text-gray-800">{u.name}</p>
                                                            <p className="text-sm text-gray-500">{u.email}</p>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td className="p-4">
                                                    <span className={`px-3 py-1 rounded-full text-xs font-medium ${roleColor.bg} ${roleColor.text}`}>
                                                        {ROLE_NAMES[u.role as keyof typeof ROLE_NAMES] || u.role}
                                                    </span>
                                                </td>
                                                <td className="p-4 text-center">
                                                    <button
                                                        onClick={() => handleToggleStatus(u.id)}
                                                        className={`px-3 py-1 rounded-full text-xs font-bold transition-all ${u.is_active
                                                            ? 'bg-emerald-100 text-emerald-700 hover:bg-rose-100 hover:text-rose-700'
                                                            : 'bg-gray-100 text-gray-600 hover:bg-emerald-100 hover:text-emerald-700'
                                                            }`}
                                                    >
                                                        {u.is_active ? 'Active' : 'Inactive'}
                                                    </button>
                                                </td>
                                                <td className="p-4 text-gray-600 text-sm">
                                                    {u.last_login
                                                        ? new Date(u.last_login).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' ' + new Date(u.last_login).toLocaleDateString('id-ID', { day: 'numeric', month: 'short' })
                                                        : '-'}
                                                </td>
                                                <td className="p-4">
                                                    <div className="flex items-center justify-center gap-2">
                                                        <button
                                                            onClick={() => handleEditUser(u)}
                                                            disabled={u.role === 'super_admin'}
                                                            className={`p-2 rounded-lg transition-colors ${u.role === 'super_admin' ? 'text-gray-300 cursor-not-allowed' : 'hover:bg-purple-50 text-purple-600'}`}
                                                        >
                                                            <Edit className="w-4 h-4" />
                                                        </button>
                                                        <button
                                                            onClick={async () => {
                                                                if (u.role === 'super_admin') return;
                                                                if (confirm(`Hapus user ${u.name}?`)) {
                                                                    await usersService.delete(u.id);
                                                                    fetchDashboardData();
                                                                }
                                                            }}
                                                            disabled={u.role === 'super_admin'}
                                                            className={`p-2 rounded-lg transition-colors ${u.role === 'super_admin' ? 'text-gray-300 cursor-not-allowed' : 'hover:bg-red-50 text-red-600'}`}
                                                        >
                                                            <Trash2 className="w-4 h-4" />
                                                        </button>
                                                    </div>
                                                </td>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>

                        <div className="p-4 border-t border-gray-100 flex items-center justify-between">
                            <p className="text-sm text-gray-500">
                                Menampilkan {filteredUsers.length} dari {users.length} users
                            </p>
                            <div className="flex items-center gap-2">
                                <button className="px-3 py-1.5 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50">
                                    Sebelumnya
                                </button>
                                <button className="px-3 py-1.5 bg-purple-600 text-white rounded-lg text-sm">
                                    1
                                </button>
                                <button className="px-3 py-1.5 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50">
                                    Selanjutnya
                                </button>
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, User, clearSession } from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    Plus,
    Search,
    Users,
    MapPin,
    Phone,
    Edit,
    Trash2,
    Building2,
    Loader2,
    X,
    CheckCircle2
} from 'lucide-react';
import { pesantrenService, Pesantren } from '@/lib/services/pesantren';

export default function PesantrenManagement() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [pesantrens, setPesantrens] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');

    // Modal state
    const [showModal, setShowModal] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [editingPesantren, setEditingPesantren] = useState<Pesantren | null>(null);
    const [showSuccess, setShowSuccess] = useState(false);
    const [formData, setFormData] = useState({
        name: '',
        address: '',
        phone: ''
    });

    const fetchPesantrens = useCallback(async () => {
        setIsLoading(true);
        try {
            const data = await pesantrenService.getDetailedAll();
            setPesantrens(data);
        } catch (error) {
            console.error('Failed to fetch pesantren:', error);
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'super_admin') {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchPesantrens();
    }, [router, fetchPesantrens]);

    const handleSave = async () => {
        if (!formData.name) {
            alert('Nama Pesantren wajib diisi');
            return;
        }

        setIsSaving(true);
        try {
            if (editingPesantren) {
                await pesantrenService.update(editingPesantren.id, formData);
            } else {
                await pesantrenService.create(formData);
            }
            setShowModal(false);
            setEditingPesantren(null);
            setFormData({ name: '', address: '', phone: '' });
            setShowSuccess(true);
            setTimeout(() => setShowSuccess(false), 3000);
            fetchPesantrens();
        } catch (error: any) {
            alert('Gagal menyimpan: ' + error.message);
        } finally {
            setIsSaving(false);
        }
    };

    const handleDelete = async (id: string, name: string) => {
        if (confirm(`Hapus unit pesantren "${name}"? Semua data terkait unit ini akan terisolasi.`)) {
            try {
                await pesantrenService.delete(id);
                fetchPesantrens();
            } catch (error: any) {
                alert('Gagal menghapus: ' + error.message);
            }
        }
    };

    const filteredPesantrens = pesantrens.filter(p =>
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.address?.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading && pesantrens.length === 0) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-black">
                <Loader2 className="w-10 h-10 text-purple-600 animate-spin" />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-black">
            {/* Success Toast */}
            {showSuccess && (
                <div className="fixed top-4 right-4 z-[60] bg-emerald-500 text-white px-6 py-4 rounded-xl shadow-lg flex items-center gap-3 animate-slide-up">
                    <CheckCircle2 className="w-6 h-6" />
                    <span className="font-medium">Data Pesantren berhasil diperbarui!</span>
                </div>
            )}

            {/* Management Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
                    <div className="bg-white dark:bg-neutral-900 rounded-2xl w-full max-w-lg shadow-2xl border border-gray-100 dark:border-neutral-800">
                        <div className="p-6 border-b border-gray-100 dark:border-neutral-800 flex items-center justify-between">
                            <h3 className="text-xl font-bold dark:text-white">
                                {editingPesantren ? 'Edit Pesantren' : 'Tambah Pesantren Baru'}
                            </h3>
                            <button onClick={() => setShowModal(false)} className="p-2 hover:bg-gray-100 dark:hover:bg-neutral-800 rounded-lg">
                                <X className="w-5 h-5 text-gray-400" />
                            </button>
                        </div>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Nama Pesantren</label>
                                <div className="relative">
                                    <Building2 className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                    <input
                                        type="text"
                                        value={formData.name}
                                        onChange={e => setFormData({ ...formData, name: e.target.value })}
                                        className="w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-neutral-800 border border-gray-200 dark:border-neutral-700 rounded-xl focus:ring-2 focus:ring-purple-500/30 outline-none dark:text-white"
                                        placeholder="Misal: Pesantren Al-Hidayah"
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Alamat</label>
                                <div className="relative">
                                    <MapPin className="w-5 h-5 text-gray-400 absolute left-3 top-3" />
                                    <textarea
                                        rows={3}
                                        value={formData.address}
                                        onChange={e => setFormData({ ...formData, address: e.target.value })}
                                        className="w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-neutral-800 border border-gray-200 dark:border-neutral-700 rounded-xl focus:ring-2 focus:ring-purple-500/30 outline-none dark:text-white"
                                        placeholder="Alamat lengkap unit"
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Nomor Telepon</label>
                                <div className="relative">
                                    <Phone className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                    <input
                                        type="text"
                                        value={formData.phone}
                                        onChange={e => setFormData({ ...formData, phone: e.target.value })}
                                        className="w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-neutral-800 border border-gray-200 dark:border-neutral-700 rounded-xl focus:ring-2 focus:ring-purple-500/30 outline-none dark:text-white"
                                        placeholder="0812..."
                                    />
                                </div>
                            </div>
                        </div>
                        <div className="p-6 border-t border-gray-100 dark:border-neutral-800 flex gap-3">
                            <button
                                onClick={() => setShowModal(false)}
                                className="flex-1 py-3 text-gray-600 dark:text-gray-400 font-medium hover:bg-gray-100 dark:hover:bg-neutral-800 rounded-xl"
                            >
                                Batal
                            </button>
                            <button
                                onClick={handleSave}
                                disabled={isSaving}
                                className="flex-1 py-3 bg-purple-600 hover:bg-purple-700 text-white font-medium rounded-xl disabled:opacity-50 flex items-center justify-center gap-2"
                            >
                                {isSaving && <Loader2 className="w-5 h-5 animate-spin" />}
                                {editingPesantren ? 'Simpan Perubahan' : 'Daftarkan Pesantren'}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <Sidebar
                user={user!}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user!} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
