'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Plus,
    Search,
    User as UserIcon,
    Mail,
    Phone,
    CheckCircle2,
    XCircle,
    Edit,
    Trash2
} from 'lucide-react';

import { teachersService, TeacherWithProfile } from '@/lib/services/teachers';
import { Loader2 } from 'lucide-react';
import TeacherModal from '@/components/admin/TeacherModal';

export default function DataGuruPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [teachers, setTeachers] = useState<TeacherWithProfile[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Modal state
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedTeacher, setSelectedTeacher] = useState<TeacherWithProfile | null>(null);

    const fetchTeachers = async () => {
        try {
            setIsLoading(true);
            const data = await teachersService.getAll();
            setTeachers(data);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching teachers:', error);
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_akademik' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchTeachers();
    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleOpenAddModal = () => {
        setSelectedTeacher(null);
        setIsModalOpen(true);
    };

    const handleOpenEditModal = (teacher: any) => {
        setSelectedTeacher(teacher);
        setIsModalOpen(true);
    };

    const handleSubmitTeacher = async (data: any) => {
        try {
            if (selectedTeacher) {
                // When updating, only send fields that exist in teachers table
                const updateData = {
                    name: data.name,
                    nip: data.nip || null,
                    gender: data.gender,
                    specialization: data.specialization || null,
                    phone: data.phone || null,
                    address: data.address || null,
                    is_active: data.is_active ?? true
                };
                await teachersService.update(selectedTeacher.id, updateData);
            } else {
                // Create new - RPC will handle user creation
                const result = await teachersService.create(data);

                // Show generated credentials if available
                if (result && result.email && result.password) {
                    setTimeout(() => {
                        alert(`✅ Guru berhasil ditambahkan!\n\n📧 Email: ${result.email}\n🔑 Password: ${result.password}\n\nSimpan informasi ini untuk login guru.`);
                    }, 500);
                }
            }
            fetchTeachers();
        } catch (error) {
            console.error('Error saving teacher:', error);
            throw error;
        }
    };

    const handleDeleteTeacher = async (id: string) => {
        if (confirm('Apakah Anda yakin ingin menghapus data guru ini?')) {
            try {
                await teachersService.delete(id);
                fetchTeachers();
            } catch (error) {
                alert('Gagal menghapus data guru. Pastikan tidak ada data terkait (jadwal, dsb) yang masih menggunakan guru ini.');
            }
        }
    };

    const handleToggleStatus = async (id: string, currentStatus: boolean) => {
        try {
            await teachersService.update(id, { is_active: !currentStatus });
            fetchTeachers();
        } catch (error) {
            alert('Gagal mengubah status guru');
        }
    };

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-blue-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
                    <span>Loading Data Guru...</span>
                </div>
            </div>
        );
    }

    const filteredTeachers = teachers.filter(t =>
        t.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        (t.nip && t.nip.includes(searchQuery))
    );

    return (
        <div className="min-h-screen bg-[#050505] flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Header */}
                    <div className="mb-10">
                        <Link
                            href="/dashboard/akademik"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-white mb-6 transition-colors group"
                        >
                            <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                            <div>
                                <h1 className="text-3xl font-black text-white tracking-tight flex items-center gap-3">
                                    <span className="w-2 h-8 bg-blue-600 rounded-full block"></span>
                                    Data Guru & Pengajar
                                </h1>
                                <p className="text-gray-400 mt-1">
                                    Kelola profil and tugas mengajar asatidz/asatidzah
                                </p>
                            </div>
                            <button
                                onClick={handleOpenAddModal}
                                className="flex items-center gap-2 px-6 py-3.5 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-bold transition-all shadow-lg shadow-blue-500/20 active:scale-95"
                            >
                                <Plus className="w-5 h-5" />
                                Tambah Guru Baru
                            </button>
                        </div>
                    </div>

                    <TeacherModal
                        isOpen={isModalOpen}
                        onClose={() => setIsModalOpen(false)}
                        onSubmit={handleSubmitTeacher}
                        teacherData={selectedTeacher}
                    />

                    {/* Filter / Search */}
                    <div className="flex flex-col lg:flex-row gap-6 mb-8">
                        <div className="flex-1 relative">
                            <Search className="w-6 h-6 text-gray-600 absolute left-4 top-1/2 -translate-y-1/2" />
                            <input
                                type="text"
                                placeholder="Cari NIP atau nama guru..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="w-full pl-12 pr-6 py-4 bg-neutral-900/40 border border-white/5 rounded-[1.5rem] text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all backdrop-blur-sm"
                            />
                        </div>
                        <div className="flex items-center gap-4 bg-neutral-900/40 border border-white/5 rounded-[1.5rem] px-6 py-4 backdrop-blur-sm">
                            <p className="text-[10px] font-black text-gray-600 uppercase tracking-widest leading-none">Total Pengajar</p>
                            <span className="text-xl font-black text-blue-500 leading-none">{teachers.length}</span>
                        </div>
                    </div>

                    {/* Teachers Grid */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {filteredTeachers.map((t) => (
                            <div
                                key={t.id}
                                className="group relative bg-neutral-900/60 border border-white/5 rounded-[2.5rem] overflow-hidden transition-all duration-300 hover:shadow-2xl hover:border-white/10 hover:-translate-y-1"
                            >
                                <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-tr from-white/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"></div>

                                <div className="p-7">
                                    <div className="flex items-start justify-between mb-6">
                                        <div className="flex items-center gap-4">
                                            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl shadow-lg border transition-all duration-500 group-hover:scale-110 group-hover:rotate-3 ${t.gender === 'L'
                                                ? 'bg-blue-500/10 border-blue-500/20 text-blue-400'
                                                : 'bg-pink-500/10 border-pink-500/20 text-pink-400'
                                                }`}>
                                                {t.name.charAt(0)}
                                            </div>
                                            <div className="min-w-0">
                                                <h3 className="text-lg font-black text-white tracking-tight truncate leading-tight group-hover:text-blue-400 transition-colors uppercase">
                                                    {t.name}
                                                </h3>
                                                <p className="text-xs font-black text-gray-500 uppercase tracking-widest mt-1">NIP: {t.nip || '—'}</p>
                                            </div>
                                        </div>
                                        <button
                                            onClick={() => handleToggleStatus(t.id, t.is_active)}
                                            className={`p-1.5 rounded-lg transition-all ${t.is_active
                                                ? 'text-emerald-500 bg-emerald-500/10'
                                                : 'text-rose-500 bg-rose-500/10'
                                                }`}
                                        >
                                            {t.is_active ? <CheckCircle2 className="w-5 h-5" /> : <XCircle className="w-5 h-5" />}
                                        </button>
                                    </div>

                                    <div className="space-y-4">
                                        <div className="bg-black/30 border border-white/5 rounded-2xl p-4">
                                            <p className="text-[10px] font-black text-gray-600 uppercase tracking-widest mb-1">Mata Pelajaran</p>
                                            <p className="text-sm font-bold text-gray-300">{t.specialization || 'Guru Umum'}</p>
                                        </div>

                                        <div className="flex items-center gap-3 bg-black/10 p-2 rounded-2xl">
                                            <div className="flex-1 flex flex-col items-center py-2 border-r border-white/5">
                                                <span className="text-[8px] font-black text-gray-600 uppercase tracking-widest">Gender</span>
                                                <span className="text-[10px] font-bold text-gray-400 uppercase mt-0.5">{t.gender === 'L' ? 'Laki-laki' : 'Perempuan'}</span>
                                            </div>
                                            <div className="flex-1 flex flex-col items-center py-2">
                                                <span className="text-[8px] font-black text-gray-600 uppercase tracking-widest">Status</span>
                                                <span className={`text-[10px] font-bold uppercase mt-0.5 ${t.is_active ? 'text-emerald-500' : 'text-rose-500'}`}>
                                                    {t.is_active ? 'Aktif' : 'Nonaktif'}
                                                </span>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="mt-8 pt-6 border-t border-white/5 flex items-center justify-between">
                                        <div className="flex gap-2">
                                            <div className="w-8 h-8 rounded-lg bg-neutral-800 flex items-center justify-center text-gray-500 hover:text-white transition-colors cursor-pointer border border-white/5">
                                                <Mail className="w-4 h-4" />
                                            </div>
                                            <div className="w-8 h-8 rounded-lg bg-neutral-800 flex items-center justify-center text-gray-500 hover:text-white transition-colors cursor-pointer border border-white/5">
                                                <Phone className="w-4 h-4" />
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <button
                                                onClick={() => handleOpenEditModal(t)}
                                                className="p-2.5 bg-neutral-800 hover:bg-blue-600 text-gray-500 hover:text-white rounded-xl border border-white/5 transition-all"
                                            >
                                                <Edit className="w-4 h-4" />
                                            </button>
                                            <button
                                                onClick={() => handleDeleteTeacher(t.id)}
                                                className="p-2.5 bg-neutral-800 hover:bg-rose-600 text-gray-500 hover:text-white rounded-xl border border-white/5 transition-all"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    {filteredTeachers.length === 0 && (
                        <div className="flex flex-col items-center justify-center py-24 bg-neutral-900/40 border border-white/5 rounded-[3rem]">
                            <div className="w-20 h-20 bg-neutral-800 rounded-2xl flex items-center justify-center mb-6 border border-white/5 shadow-inner">
                                <UserIcon className="w-10 h-10 text-gray-600" />
                            </div>
                            <h3 className="text-xl font-black text-white mb-2">Guru tidak ditemukan</h3>
                            <p className="text-gray-500 max-w-xs text-center">
                                Coba kata kunci pencarian NIP atau nama yang berbeda.
                            </p>
                        </div>
                    )}
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Users,
    BookOpen,
    Plus,
    Search,
    Loader2,
    Trash2,
    GraduationCap,
    ChevronDown
} from 'lucide-react';
import { classesService, ClassWithRelations } from '@/lib/services/classes';
import { teachersService } from '@/lib/services/teachers';
import { subjectsService } from '@/lib/services/subjects';
import { teachingAssignmentsService, TeachingAssignment } from '@/lib/services/teaching-assignments';

interface Teacher {
    id: string;
    name: string;
}

interface Subject {
    id: string;
    name: string;
    code: string;
}

export default function PenugasanMengajarPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    const [classes, setClasses] = useState<ClassWithRelations[]>([]);
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [subjects, setSubjects] = useState<Subject[]>([]);
    const [assignments, setAssignments] = useState<TeachingAssignment[]>([]);

    // Form state
    const [showForm, setShowForm] = useState(false);
    const [formData, setFormData] = useState({
        teacher_id: '',
        subject_id: '',
        class_id: '',
        hours_per_week: 2
    });
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [filterTeacher, setFilterTeacher] = useState<string>('all');

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || !['super_admin', 'admin_akademik'].includes(currentUser.role)) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router]);

    const fetchData = async () => {
        try {
            setIsLoading(true);
            const [classesData, teachersData, subjectsData, assignmentsData] = await Promise.all([
                classesService.getAll(),
                teachersService.getAll(),
                subjectsService.getAll(),
                teachingAssignmentsService.getAll()
            ]);
            setClasses(classesData);
            setTeachers(teachersData as unknown as Teacher[]);
            setSubjects(subjectsData as unknown as Subject[]);
            setAssignments(assignmentsData);
        } catch (error) {
            console.error('Error fetching data:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);

        try {
            await teachingAssignmentsService.create(formData);
            setShowForm(false);
            setFormData({ teacher_id: '', subject_id: '', class_id: '', hours_per_week: 2 });
            fetchData();
        } catch (error: any) {
            console.error('Error creating assignment:', error);
            if (error.message?.includes('duplicate')) {
                alert('Penugasan ini sudah ada');
            } else {
                alert('Gagal menambahkan penugasan');
            }
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Yakin hapus penugasan ini?')) return;
        try {
            await teachingAssignmentsService.delete(id);
            fetchData();
        } catch (error) {
            console.error('Error deleting:', error);
            alert('Gagal menghapus');
        }
    };

    const filteredAssignments = filterTeacher === 'all'
        ? assignments
        : assignments.filter(a => a.teacher_id === filterTeacher);

    // Calculate teacher workload
    const getTeacherWorkload = (teacherId: string) => {
        return assignments
            .filter(a => a.teacher_id === teacherId)
            .reduce((sum, a) => sum + (a.hours_per_week || 0), 0);
    };

    if (!user) return null;

    return (
        <div className="min-h-screen bg-black flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader
                    user={user}
                    onMenuClick={() => setSidebarOpen(true)}
                />

                <main className="p-4 lg:p-6">
                    {/* Back Button */}
                    <Link
                        href="/dashboard/akademik/guru"
                        className="inline-flex items-center gap-2 text-gray-400 hover:text-white mb-6 transition-colors"
                    >
                        <ArrowLeft className="w-4 h-4" />
                        Kembali ke Data Guru
                    </Link>

                    {/* Header */}
                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
                        <div>
                            <h1 className="text-2xl font-bold text-white">Penugasan Mengajar</h1>
                            <p className="text-gray-400">Atur guru pengajar untuk setiap mata pelajaran dan kelas</p>
                        </div>
                        <button
                            onClick={() => setShowForm(true)}
                            className="flex items-center gap-2 px-4 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-medium transition-colors"
                        >
                            <Plus className="w-5 h-5" />
                            Tambah Penugasan
                        </button>
                    </div>

                    {/* Filter */}
                    <div className="mb-6 flex items-center gap-4">
                        <div className="relative">
                            <select
                                value={filterTeacher}
                                onChange={(e) => setFilterTeacher(e.target.value)}
                                className="pl-4 pr-10 py-2.5 bg-gray-800/50 border border-gray-700/50 rounded-xl text-white appearance-none focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
                            >
                                <option value="all">Semua Guru</option>
                                {teachers.map(t => (
                                    <option key={t.id} value={t.id}>{t.name}</option>
                                ))}
                            </select>
                            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                        </div>
                    </div>

                    {/* Content */}
                    {isLoading ? (
                        <div className="flex items-center justify-center py-20">
                            <Loader2 className="w-8 h-8 text-emerald-500 animate-spin" />
                        </div>
                    ) : filteredAssignments.length === 0 ? (
                        <div className="bg-gray-800/50 rounded-2xl border border-gray-700/50 p-12 text-center">
                            <BookOpen className="w-16 h-16 text-gray-600 mx-auto mb-4" />
                            <h3 className="text-lg font-medium text-white mb-2">Belum Ada Penugasan</h3>
                            <p className="text-gray-400 mb-6">Tambahkan penugasan mengajar untuk guru</p>
                        </div>
                    ) : (
                        <div className="bg-gray-800/50 rounded-2xl border border-gray-700/50 overflow-hidden">
                            <table className="w-full">
                                <thead>
                                    <tr className="border-b border-gray-700/50">
                                        <th className="text-left p-4 text-gray-400 font-medium">Guru</th>
                                        <th className="text-left p-4 text-gray-400 font-medium">Mata Pelajaran</th>
                                        <th className="text-left p-4 text-gray-400 font-medium">Kelas</th>
                                        <th className="text-left p-4 text-gray-400 font-medium">Jam/Minggu</th>
                                        <th className="text-left p-4 text-gray-400 font-medium">Aksi</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {filteredAssignments.map((assignment) => (
                                        <tr key={assignment.id} className="border-b border-gray-700/30 hover:bg-gray-700/20">
                                            <td className="p-4">
                                                <div className="flex items-center gap-3">
                                                    <div className="w-8 h-8 bg-violet-500/20 rounded-lg flex items-center justify-center">
                                                        <GraduationCap className="w-4 h-4 text-violet-400" />
                                                    </div>
                                                    <span className="text-white">{assignment.teacher?.name || '-'}</span>
                                                </div>
                                            </td>
                                            <td className="p-4 text-gray-300">
                                                {assignment.subject?.name || '-'}
                                            </td>
                                            <td className="p-4 text-gray-300">
                                                {assignment.class?.name || '-'}
                                            </td>
                                            <td className="p-4 text-gray-300">
                                                {assignment.hours_per_week} jam
                                            </td>
                                            <td className="p-4">
                                                <button
                                                    onClick={() => handleDelete(assignment.id)}
                                                    className="p-2 hover:bg-red-500/20 text-gray-400 hover:text-red-400 rounded-lg transition-colors"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}

                    {/* Workload Summary */}
                    {!isLoading && (
                        <div className="mt-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                            {teachers.slice(0, 8).map(teacher => {
                                const workload = getTeacherWorkload(teacher.id);
                                return (
                                    <div key={teacher.id} className="bg-gray-800/50 rounded-xl border border-gray-700/50 p-4">
                                        <p className="text-sm text-gray-400 mb-1">{teacher.name}</p>
                                        <p className="text-2xl font-bold text-white">{workload} <span className="text-sm font-normal text-gray-500">jam/minggu</span></p>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </main>
            </div>

            {/* Add Modal */}
            {showForm && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
                    <div className="bg-gray-800 rounded-2xl w-full max-w-md shadow-2xl border border-gray-700">
                        <div className="p-6 border-b border-gray-700">
                            <h3 className="text-lg font-bold text-white">Tambah Penugasan Mengajar</h3>
                        </div>

                        <form onSubmit={handleSubmit} className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-300 mb-1.5">Guru</label>
                                <select
                                    value={formData.teacher_id}
                                    onChange={(e) => setFormData({ ...formData, teacher_id: e.target.value })}
                                    required
                                    className="w-full px-4 py-3 bg-gray-700/50 border border-gray-600 rounded-xl text-white focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
                                >
                                    <option value="">Pilih Guru...</option>
                                    {teachers.map(t => (
                                        <option key={t.id} value={t.id}>{t.name}</option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-300 mb-1.5">Mata Pelajaran</label>
                                <select
                                    value={formData.subject_id}
                                    onChange={(e) => setFormData({ ...formData, subject_id: e.target.value })}
                                    required
                                    className="w-full px-4 py-3 bg-gray-700/50 border border-gray-600 rounded-xl text-white focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
                                >
                                    <option value="">Pilih Mata Pelajaran...</option>
                                    {subjects.map(s => (
                                        <option key={s.id} value={s.id}>{s.name}</option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-300 mb-1.5">Kelas</label>
                                <select
                                    value={formData.class_id}
                                    onChange={(e) => setFormData({ ...formData, class_id: e.target.value })}
                                    required
                                    className="w-full px-4 py-3 bg-gray-700/50 border border-gray-600 rounded-xl text-white focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
                                >
                                    <option value="">Pilih Kelas...</option>
                                    {classes.map(c => (
                                        <option key={c.id} value={c.id}>{c.name}</option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-300 mb-1.5">Jam per Minggu</label>
                                <input
                                    type="number"
                                    min="1"
                                    max="10"
                                    value={formData.hours_per_week}
                                    onChange={(e) => setFormData({ ...formData, hours_per_week: parseInt(e.target.value) })}
                                    className="w-full px-4 py-3 bg-gray-700/50 border border-gray-600 rounded-xl text-white focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
                                />
                            </div>

                            <div className="flex gap-3 pt-4">
                                <button
                                    type="button"
                                    onClick={() => setShowForm(false)}
                                    disabled={isSubmitting}
                                    className="flex-1 py-3 border border-gray-600 text-gray-300 font-medium rounded-xl hover:bg-gray-700/50 transition-colors disabled:opacity-50"
                                >
                                    Batal
                                </button>
                                <button
                                    type="submit"
                                    disabled={isSubmitting}
                                    className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl transition-colors flex items-center justify-center gap-2 disabled:opacity-70"
                                >
                                    {isSubmitting ? (
                                        <>
                                            <Loader2 className="w-5 h-5 animate-spin" />
                                            Menyimpan...
                                        </>
                                    ) : (
                                        'Simpan'
                                    )}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import {
    Plus,
    Search,
    Edit,
    Trash2,
    CheckCircle2,
    XCircle,
    BookOpen,
    Loader2,
    RotateCcw,
    AlertTriangle
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { hafalanTypesService, HafalanType } from '@/lib/services/hafalan-types';
import HafalanTypeModal from '@/components/hafalan/HafalanTypeModal';

const CATEGORY_CONFIG = {
    quran: { label: 'Al-Qur\'an', color: 'blue', icon: '📖' },
    doa: { label: 'Doa', color: 'green', icon: '🤲' },
    mufrodat: { label: 'Mufrodat', color: 'purple', icon: '📝' },
    hadits: { label: 'Hadits', color: 'amber', icon: '📜' },
    nadhom: { label: 'Nadhom', color: 'pink', icon: '✍️' },
    other: { label: 'Lainnya', color: 'gray', icon: '📚' }
};

export default function HafalanTypesPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);

    // Data state
    const [hafalanTypes, setHafalanTypes] = useState<HafalanType[]>([]);
    const [filteredTypes, setFilteredTypes] = useState<HafalanType[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Filter state
    const [searchQuery, setSearchQuery] = useState('');
    const [categoryFilter, setCategoryFilter] = useState<string>('all');
    const [statusFilter, setStatusFilter] = useState<string>('all');

    // Modal state
    const [showModal, setShowModal] = useState(false);
    const [editData, setEditData] = useState<HafalanType | null>(null);

    // Stats
    const [stats, setStats] = useState({
        total: 0,
        active: 0,
        inactive: 0,
        by_category: {} as Record<string, number>
    });

    const fetchHafalanTypes = async () => {
        try {
            setIsLoading(true);
            const [types, statistics] = await Promise.all([
                hafalanTypesService.getAllIncludingInactive(),
                hafalanTypesService.getStatistics()
            ]);
            setHafalanTypes(types);
            setStats(statistics);
        } catch (error) {
            console.error('Error fetching hafalan types:', error);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'admin_akademik') {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchHafalanTypes();
    }, [router]);

    const applyFilters = () => {
        let filtered = [...hafalanTypes];

        // Search filter
        if (searchQuery) {
            filtered = filtered.filter(type =>
                type.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                type.description.toLowerCase().includes(searchQuery.toLowerCase())
            );
        }

        // Category filter
        if (categoryFilter !== 'all') {
            filtered = filtered.filter(type => type.category === categoryFilter);
        }

        // Status filter
        if (statusFilter === 'active') {
            filtered = filtered.filter(type => type.is_active);
        } else if (statusFilter === 'inactive') {
            filtered = filtered.filter(type => !type.is_active);
        }

        setFilteredTypes(filtered);
    };

    useEffect(() => {
        applyFilters();
    }, [hafalanTypes, searchQuery, categoryFilter, statusFilter]);

    const handleSave = async (data: Omit<HafalanType, 'id' | 'created_at' | 'updated_at'>) => {
        try {
            if (editData) {
                await hafalanTypesService.update(editData.id, data);
            } else {
                await hafalanTypesService.create(data);
            }
            await fetchHafalanTypes();
            setShowModal(false);
            setEditData(null);
        } catch (error: unknown) {
            throw error;
        }
    };

    const handleEdit = (type: HafalanType) => {
        setEditData(type);
        setShowModal(true);
    };

    const handleDelete = async (type: HafalanType) => {
        if (!confirm(`Yakin ingin menonaktifkan "${type.name}"?`)) return;

        try {
            await hafalanTypesService.delete(type.id);
            await fetchHafalanTypes();
        } catch (error: any) {
            alert(error.message || 'Gagal menghapus hafalan type');
        }
    };

    const handleReactivate = async (type: HafalanType) => {
        try {
            await hafalanTypesService.reactivate(type.id);
            await fetchHafalanTypes();
        } catch (error: any) {
            alert(error.message || 'Gagal mengaktifkan kembali hafalan type');
        }
    };

    const handleHardDelete = async (type: HafalanType) => {
        // Double confirmation for hard delete
        const firstConfirm = confirm(
            `PERINGATAN!\n\nAnda akan MENGHAPUS PERMANEN "${type.name}" dari database.\n\nData yang sudah dihapus TIDAK BISA dikembalikan!\n\nLanjutkan?`
        );

        if (!firstConfirm) return;

        const secondConfirm = confirm(
            `KONFIRMASI TERAKHIR!\n\nYakin ingin menghapus "${type.name}" PERMANEN?\n\nTindakan ini TIDAK BISA dibatalkan!`
        );

        if (!secondConfirm) return;

        try {
            await hafalanTypesService.hardDelete(type.id);
            await fetchHafalanTypes();
            alert('Hafalan type berhasil dihapus permanen dari database');
        } catch (error: any) {
            alert('ERROR: ' + (error.message || 'Gagal menghapus hafalan type'));
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (!user) return null;

    return (
        <div className="min-h-screen bg-black flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Header */}
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
                        <div>
                            <h1 className="text-2xl font-bold text-white tracking-tight">
                                Master Hafalan Types
                            </h1>
                            <p className="text-gray-400">Kelola jenis-jenis hafalan yang tersedia di pesantren</p>
                        </div>
                        <button
                            onClick={() => {
                                setEditData(null);
                                setShowModal(true);
                            }}
                            className="flex items-center gap-2 px-6 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl transition-all shadow-lg shadow-emerald-900/20"
                        >
                            <Plus className="w-5 h-5" />
                            Tambah Hafalan Type
                        </button>
                    </div>

                    {/* Stats Cards */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                        {[
                            { label: 'Total Types', value: stats.total, icon: BookOpen, color: 'text-violet-400', bg: 'bg-violet-400/10' },
                            { label: 'Aktif', value: stats.active, icon: CheckCircle2, color: 'text-emerald-400', bg: 'bg-emerald-400/10' },
                            { label: 'Nonaktif', value: stats.inactive, icon: XCircle, color: 'text-rose-400', bg: 'bg-rose-400/10' },
                            { label: 'Kategori', value: Object.keys(stats.by_category).length, icon: Calendar, color: 'text-amber-400', bg: 'bg-amber-400/10' }
                        ].map((stat, i) => (
                            <div key={i} className="bg-gray-800/50 p-5 rounded-2xl border border-gray-700/50 backdrop-blur-sm">
                                <div className="flex items-center justify-between mb-3">
                                    <p className="text-sm font-medium text-gray-400">{stat.label}</p>
                                    <div className={`p-2 rounded-xl ${stat.bg}`}>
                                        <stat.icon className={`w-5 h-5 ${stat.color}`} />
                                    </div>
                                </div>
                                <p className="text-3xl font-bold text-white">{stat.value}</p>
                            </div>
                        ))}
                    </div>

                    {/* Filters */}
                    <div className="bg-gray-800/50 p-5 rounded-2xl border border-gray-700/50 mb-6 backdrop-blur-sm">
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            {/* Search */}
                            <div className="relative">
                                <Search className="w-5 h-5 text-gray-500 absolute left-4 top-1/2 -translate-y-1/2" />
                                <input
                                    type="text"
                                    placeholder="Cari nama hafalan..."
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    className="w-full pl-12 pr-4 py-3 bg-gray-900/50 border border-gray-700/50 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/50 text-white placeholder-gray-500"
                                />
                            </div>

                            {/* Category Filter */}
                            <select
                                value={categoryFilter}
                                onChange={(e) => setCategoryFilter(e.target.value)}
                                className="px-4 py-3 bg-gray-900/50 border border-gray-700/50 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/50 text-white"
                            >
                                <option value="all">Semua Kategori</option>
                                {Object.entries(CATEGORY_CONFIG).map(([key, config]) => (
                                    <option key={key} value={key} className="bg-gray-900">{config.icon} {config.label}</option>
                                ))}
                            </select>

                            {/* Status Filter */}
                            <select
                                value={statusFilter}
                                onChange={(e) => setStatusFilter(e.target.value)}
                                className="px-4 py-3 bg-gray-900/50 border border-gray-700/50 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/50 text-white"
                            >
                                <option value="all">Semua Status</option>
                                <option value="active" className="bg-gray-900">Aktif</option>
                                <option value="inactive" className="bg-gray-900">Nonaktif</option>
                            </select>
                        </div>
                    </div>

                    {/* Hafalan Types List */}
                    <div className="space-y-4">
                        {isLoading ? (
                            <div className="bg-gray-800/50 p-12 rounded-2xl border border-gray-700/50 text-center">
                                <Loader2 className="w-8 h-8 text-emerald-500 animate-spin mx-auto mb-3" />
                                <p className="text-gray-400">Memuat data...</p>
                            </div>
                        ) : filteredTypes.length === 0 ? (
                            <div className="bg-gray-800/50 p-12 rounded-2xl border border-gray-700/50 text-center">
                                <p className="text-gray-500 italic">Tidak ada data hafalan type</p>
                            </div>
                        ) : (
                            filteredTypes.map((type) => {
                                const config = CATEGORY_CONFIG[type.category as keyof typeof CATEGORY_CONFIG];
                                return (
                                    <div
                                        key={type.id}
                                        className="group bg-gray-800/30 p-6 rounded-2xl border border-gray-700/30 hover:bg-gray-800/50 hover:border-gray-700/50 transition-all backdrop-blur-sm"
                                    >
                                        <div className="flex items-start justify-between">
                                            <div className="flex-1">
                                                <div className="flex items-center gap-4 mb-2">
                                                    <div className="text-3xl w-12 h-12 bg-gray-900/50 rounded-xl flex items-center justify-center border border-gray-700/50">
                                                        {config.icon}
                                                    </div>
                                                    <div>
                                                        <h3 className="text-lg font-bold text-white">{type.name}</h3>
                                                        <div className="flex flex-wrap items-center gap-2 mt-1">
                                                            <span className={`px-2 py-0.5 rounded-lg text-xs font-bold bg-${config.color}-500/10 text-${config.color}-400 border border-${config.color}-500/20`}>
                                                                {config.label}
                                                            </span>
                                                            <span className="text-sm text-gray-500">
                                                                {type.total_units} {type.unit_name}
                                                            </span>
                                                            {type.is_active ? (
                                                                <span className="px-2 py-0.5 rounded-lg text-xs font-bold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                                                                    Aktif
                                                                </span>
                                                            ) : (
                                                                <span className="px-2 py-0.5 rounded-lg text-xs font-bold bg-rose-500/10 text-rose-400 border border-rose-500/20">
                                                                    Nonaktif
                                                                </span>
                                                            )}
                                                        </div>
                                                    </div>
                                                </div>
                                                {type.description && (
                                                    <p className="text-sm text-gray-400 mt-2 ml-16 max-w-2xl">{type.description}</p>
                                                )}
                                            </div>

                                            <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button
                                                    onClick={() => handleEdit(type)}
                                                    className="p-2.5 bg-violet-500/10 hover:bg-violet-500/20 text-violet-400 rounded-xl transition-all border border-violet-500/20"
                                                    title="Edit"
                                                >
                                                    <Edit className="w-4 h-4" />
                                                </button>
                                                {type.is_active ? (
                                                    <button
                                                        onClick={() => handleDelete(type)}
                                                        className="p-2.5 bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 rounded-xl transition-all border border-rose-500/20"
                                                        title="Nonaktifkan"
                                                    >
                                                        <Trash2 className="w-4 h-4" />
                                                    </button>
                                                ) : (
                                                    <>
                                                        <button
                                                            onClick={() => handleReactivate(type)}
                                                            className="p-2.5 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 rounded-xl transition-all border border-emerald-500/20"
                                                            title="Aktifkan Kembali"
                                                        >
                                                            <RotateCcw className="w-4 h-4" />
                                                        </button>
                                                        <button
                                                            onClick={() => handleHardDelete(type)}
                                                            className="p-2.5 bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 rounded-xl transition-all border border-rose-500/20"
                                                            title="Hapus Permanen"
                                                        >
                                                            <AlertTriangle className="w-4 h-4" />
                                                        </button>
                                                    </>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                );
                            })
                        )}
                    </div>
                </main>
            </div>

            {/* Modal */}
            <HafalanTypeModal
                isOpen={showModal}
                onClose={() => {
                    setShowModal(false);
                    setEditData(null);
                }}
                onSave={handleSave}
                editData={editData}
            />
        </div>
    );
}

