'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    CalendarDays,
    Clock,
    BookOpen,
    Download
} from 'lucide-react';

import { schedulesService, ScheduleWithRelations } from '@/lib/services/academic';
import { classesService } from '@/lib/services/classes';
import { Loader2, Plus, Edit, Trash2 } from 'lucide-react';
import ScheduleModal from '@/components/admin/ScheduleModal';

const DAYS = ['Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const DAY_MAP: Record<string, number> = {
    'Senin': 1,
    'Selasa': 2,
    'Rabu': 3,
    'Kamis': 4,
    'Jumat': 5,
    'Sabtu': 6
};

export default function JadwalPelajaranPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [selectedClass, setSelectedClass] = useState<string | null>(null);
    const [classes, setClasses] = useState<any[]>([]);
    const [schedules, setSchedules] = useState<ScheduleWithRelations[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Modal state
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedSchedule, setSelectedSchedule] = useState<any>(null);

    const fetchClasses = async () => {
        try {
            const data = await classesService.getAll();
            setClasses(data);
            if (data.length > 0) {
                setSelectedClass(data[0].id);
            } else {
                setIsLoading(false);
            }
        } catch (error) {
            console.error('Error fetching classes:', error);
            setIsLoading(false);
        }
    };

    const fetchSchedules = async (classId: string) => {
        try {
            setIsLoading(true);
            const data = await schedulesService.getByClass(classId);
            setSchedules(data);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching schedules:', error);
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_akademik' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchClasses();
    }, [router]);

    useEffect(() => {
        if (selectedClass) {
            fetchSchedules(selectedClass);
        }
    }, [selectedClass]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleOpenAddModal = () => {
        setSelectedSchedule(null);
        setIsModalOpen(true);
    };

    const handleOpenEditModal = (schedule: any) => {
        setSelectedSchedule(schedule);
        setIsModalOpen(true);
    };

    const handleSubmitSchedule = async (data: any) => {
        try {
            if (selectedSchedule) {
                await schedulesService.update(selectedSchedule.id, data);
            } else {
                await schedulesService.create(data);
            }
            if (selectedClass) fetchSchedules(selectedClass);
        } catch (error) {
            console.error('Error saving schedule:', error);
            throw error;
        }
    };

    const handleDeleteSchedule = async (id: string) => {
        if (confirm('Apakah Anda yakin ingin menghapus jadwal ini?')) {
            try {
                await schedulesService.delete(id);
                if (selectedClass) fetchSchedules(selectedClass);
            } catch (error) {
                alert('Gagal menghapus jadwal');
            }
        }
    };

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-blue-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
                    <span>Loading Jadwal...</span>
                </div>
            </div>
        );
    }

    const getDaySchedules = (dayName: string) => {
        const dayOfWeek = DAY_MAP[dayName];
        return schedules.filter(s => s.day_of_week === dayOfWeek);
    };

    return (
        <div className="min-h-screen bg-[#050505] flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Header */}
                    <div className="mb-10">
                        <Link
                            href="/dashboard/akademik"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-white mb-6 transition-colors group"
                        >
                            <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                            <div>
                                <h1 className="text-3xl font-black text-white tracking-tight flex items-center gap-3">
                                    <span className="w-2 h-8 bg-blue-600 rounded-full block"></span>
                                    Jadwal Pelajaran
                                </h1>
                                <p className="text-gray-400 mt-1">
                                    Kelola jadwal harian santri per kelas
                                </p>
                            </div>
                            <div className="flex items-center gap-3">
                                <button className="flex items-center gap-2 px-6 py-3.5 bg-neutral-900 border border-white/5 rounded-2xl text-gray-400 hover:text-white transition-all active:scale-95">
                                    <Download className="w-5 h-5" />
                                    Download PDF
                                </button>
                                <button
                                    onClick={handleOpenAddModal}
                                    className="flex items-center gap-2 px-6 py-3.5 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-bold transition-all shadow-lg shadow-blue-500/20 active:scale-95"
                                >
                                    <Plus className="w-5 h-5" />
                                    Tambah Jadwal
                                </button>
                            </div>
                        </div>
                    </div>

                    <ScheduleModal
                        isOpen={isModalOpen}
                        onClose={() => setIsModalOpen(false)}
                        onSubmit={handleSubmitSchedule}
                        scheduleData={selectedSchedule}
                        defaultClassId={selectedClass || undefined}
                    />

                    {/* Filter Class */}
                    <div className="bg-neutral-900/40 border border-white/5 rounded-[2.5rem] p-8 mb-10 backdrop-blur-sm">
                        <div className="flex flex-col gap-4">
                            <div className="flex items-center gap-3">
                                <div className="w-1.5 h-4 bg-blue-500 rounded-full"></div>
                                <span className="text-xs font-black text-white uppercase tracking-[0.2em]">Pilih Kelas Aktif</span>
                            </div>
                            <div className="flex flex-wrap gap-3">
                                {classes.map(cls => (
                                    <button
                                        key={cls.id}
                                        onClick={() => setSelectedClass(cls.id)}
                                        className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all border ${selectedClass === cls.id
                                            ? 'bg-blue-600 border-blue-500 text-white shadow-lg shadow-blue-500/20'
                                            : 'bg-black/40 border-white/5 text-gray-500 hover:border-white/20 hover:text-gray-300'
                                            }`}
                                    >
                                        Kelas {cls.name}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Schedule Grid */}
                    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                        {DAYS.map(day => {
                            const daySchedules = getDaySchedules(day);
                            return (
                                <div key={day} className="group relative bg-neutral-900/60 border border-white/5 rounded-[2.5rem] overflow-hidden transition-all duration-300 hover:shadow-2xl hover:border-white/10 flex flex-col min-h-[400px]">
                                    {/* Glass Reflection */}
                                    <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-tr from-white/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"></div>

                                    <div className="bg-black/40 px-8 py-6 border-b border-white/5 flex items-center justify-between">
                                        <h3 className="font-black text-white flex items-center gap-3 text-lg tracking-tight">
                                            <div className="w-10 h-10 bg-blue-600/10 rounded-xl flex items-center justify-center border border-blue-500/20 shadow-inner">
                                                <CalendarDays className="w-5 h-5 text-blue-500" />
                                            </div>
                                            {day}
                                        </h3>
                                        <span className="text-[10px] font-black text-gray-600 uppercase tracking-widest bg-black/40 px-3 py-1.5 rounded-lg border border-white/5">{daySchedules.length} Sesi</span>
                                    </div>
                                    <div className="p-8 flex-1 space-y-6 relative">
                                        {daySchedules.map((item) => (
                                            <div key={item.id} className="relative pl-6 border-l-2 border-blue-600/30 py-1 hover:bg-white/5 transition-all rounded-r-[1.5rem] group/item">
                                                <div className="flex items-center justify-between mb-2">
                                                    <div className="flex items-center gap-2 text-[10px] font-black text-blue-400 bg-blue-500/10 px-3 py-1 rounded-full border border-blue-500/10 shadow-inner uppercase tracking-wider">
                                                        <Clock className="w-3.5 h-3.5" />
                                                        {item.start_time.substring(0, 5)} — {item.end_time.substring(0, 5)}
                                                    </div>
                                                    <div className="flex items-center gap-1.5 opacity-0 group-hover/item:opacity-100 transition-all">
                                                        <button
                                                            onClick={() => handleOpenEditModal(item)}
                                                            className="p-2.5 bg-neutral-800 hover:bg-blue-600 text-gray-500 hover:text-white rounded-xl border border-white/5"
                                                        >
                                                            <Edit className="w-3.5 h-3.5" />
                                                        </button>
                                                        <button
                                                            onClick={() => handleDeleteSchedule(item.id)}
                                                            className="p-2.5 bg-neutral-800 hover:bg-rose-600 text-gray-500 hover:text-white rounded-xl border border-white/5"
                                                        >
                                                            <Trash2 className="w-3.5 h-3.5" />
                                                        </button>
                                                    </div>
                                                </div>
                                                <h4 className="font-black text-gray-200 text-lg tracking-tight group-hover/item:text-blue-400 transition-colors uppercase">{item.subject?.name}</h4>
                                                <div className="flex items-center gap-2 mt-2 text-xs font-bold text-gray-500">
                                                    <div className="w-6 h-6 rounded-full bg-neutral-800 flex items-center justify-center text-[8px] border border-white/5">
                                                        {item.teacher?.name ? item.teacher.name.split(' ').map((n: string) => n[0]).slice(0, 2).join('') : '??'}
                                                    </div>
                                                    {item.teacher?.name || 'Belum ditugaskan'}
                                                </div>
                                            </div>
                                        ))}
                                        {daySchedules.length === 0 && (
                                            <div className="h-full flex flex-col items-center justify-center py-10 opacity-40">
                                                <div className="w-16 h-16 bg-neutral-800 rounded-2xl flex items-center justify-center mb-4 border border-white/5">
                                                    <BookOpen className="w-8 h-8 text-gray-600" />
                                                </div>
                                                <p className="text-sm font-bold text-gray-600 uppercase tracking-widest">Tiada Jadwal</p>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Users,
    Search,
    Loader2,
    UserPlus,
    UserMinus,
    GraduationCap,
    ChevronRight,
    Filter
} from 'lucide-react';
import { classesService, ClassWithRelations } from '@/lib/services/classes';
import { studentsService } from '@/lib/services/students';

interface Student {
    id: string;
    name: string;
    nis: string;
    class_id: string | null;
    gender: 'L' | 'P';
}

export default function AnggotaKelasPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [classes, setClasses] = useState<ClassWithRelations[]>([]);
    const [students, setStudents] = useState<Student[]>([]);
    const [selectedClass, setSelectedClass] = useState<string | null>(null);
    const [searchQuery, setSearchQuery] = useState('');

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || !['super_admin', 'admin_akademik'].includes(currentUser.role)) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router]);

    const fetchData = async () => {
        try {
            setIsLoading(true);
            const [classesData, studentsData] = await Promise.all([
                classesService.getAll(),
                studentsService.getAll()
            ]);
            setClasses(classesData);
            setStudents(studentsData as unknown as Student[]);
            if (classesData.length > 0) {
                setSelectedClass(classesData[0].id);
            }
        } catch (error) {
            console.error('Error fetching data:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const getClassName = (classId: string | null) => {
        if (!classId) return 'Belum ada kelas';
        const cls = classes.find(c => c.id === classId);
        return cls?.name || 'Unknown';
    };

    const studentsInClass = students.filter(s => s.class_id === selectedClass);
    const studentsWithoutClass = students.filter(s => !s.class_id);

    const filteredStudents = studentsInClass.filter(
        s => s.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            s.nis.includes(searchQuery)
    );

    const selectedClassData = classes.find(c => c.id === selectedClass);

    if (!user) return null;

    return (
        <div className="min-h-screen bg-black flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader
                    user={user}
                    onMenuClick={() => setSidebarOpen(true)}
                />

                <main className="p-4 lg:p-6">
                    {/* Back Button */}
                    <Link
                        href="/dashboard/akademik/kelas"
                        className="inline-flex items-center gap-2 text-gray-400 hover:text-white mb-6 transition-colors"
                    >
                        <ArrowLeft className="w-4 h-4" />
                        Kembali ke Manajemen Kelas
                    </Link>

                    {/* Header */}
                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
                        <div>
                            <h1 className="text-2xl font-bold text-white">Anggota Kelas</h1>
                            <p className="text-gray-400">Kelola daftar santri per kelas</p>
                        </div>
                    </div>

                    {isLoading ? (
                        <div className="flex items-center justify-center py-20">
                            <Loader2 className="w-8 h-8 text-emerald-500 animate-spin" />
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                            {/* Class List Sidebar */}
                            <div className="lg:col-span-1 bg-gray-800/50 rounded-2xl border border-gray-700/50 p-4 h-fit">
                                <h3 className="font-semibold text-white mb-4">Pilih Kelas</h3>
                                <div className="space-y-2">
                                    {classes.map(cls => {
                                        const count = students.filter(s => s.class_id === cls.id).length;
                                        return (
                                            <button
                                                key={cls.id}
                                                onClick={() => setSelectedClass(cls.id)}
                                                className={`w-full flex items-center justify-between p-3 rounded-xl transition-all ${selectedClass === cls.id
                                                    ? 'bg-emerald-500/20 border border-emerald-500/50 text-emerald-400'
                                                    : 'bg-gray-700/30 hover:bg-gray-700/50 text-gray-300 border border-transparent'
                                                    }`}
                                            >
                                                <div className="flex items-center gap-3">
                                                    <GraduationCap className="w-4 h-4" />
                                                    <span>{cls.name}</span>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <span className="text-xs bg-gray-600/50 px-2 py-0.5 rounded-full">
                                                        {count}
                                                    </span>
                                                    <ChevronRight className="w-4 h-4" />
                                                </div>
                                            </button>
                                        );
                                    })}

                                    {/* Unassigned Students */}
                                    <button
                                        onClick={() => setSelectedClass(null)}
                                        className={`w-full flex items-center justify-between p-3 rounded-xl transition-all ${selectedClass === null
                                            ? 'bg-orange-500/20 border border-orange-500/50 text-orange-400'
                                            : 'bg-gray-700/30 hover:bg-gray-700/50 text-gray-300 border border-transparent'
                                            }`}
                                    >
                                        <div className="flex items-center gap-3">
                                            <UserMinus className="w-4 h-4" />
                                            <span>Belum Terdaftar</span>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <span className="text-xs bg-orange-600/30 px-2 py-0.5 rounded-full">
                                                {studentsWithoutClass.length}
                                            </span>
                                            <ChevronRight className="w-4 h-4" />
                                        </div>
                                    </button>
                                </div>
                            </div>

                            {/* Students List */}
                            <div className="lg:col-span-3 bg-gray-800/50 rounded-2xl border border-gray-700/50 overflow-hidden">
                                {/* Header */}
                                <div className="p-4 border-b border-gray-700/50 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                                    <div>
                                        <h3 className="font-semibold text-white">
                                            {selectedClass === null
                                                ? 'Santri Belum Terdaftar di Kelas'
                                                : `Anggota ${selectedClassData?.name || 'Kelas'}`}
                                        </h3>
                                        <p className="text-sm text-gray-400">
                                            {selectedClass === null
                                                ? `${studentsWithoutClass.length} santri`
                                                : `${studentsInClass.length} santri`}
                                        </p>
                                    </div>

                                    {/* Search */}
                                    <div className="relative">
                                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                        <input
                                            type="text"
                                            value={searchQuery}
                                            onChange={(e) => setSearchQuery(e.target.value)}
                                            placeholder="Cari nama/NIS..."
                                            className="pl-9 pr-4 py-2 bg-gray-700/50 border border-gray-600 rounded-lg text-white text-sm placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
                                        />
                                    </div>
                                </div>

                                {/* Table */}
                                {(selectedClass === null ? studentsWithoutClass : filteredStudents).length === 0 ? (
                                    <div className="p-12 text-center">
                                        <Users className="w-12 h-12 text-gray-600 mx-auto mb-4" />
                                        <p className="text-gray-400">Tidak ada santri di kelas ini</p>
                                    </div>
                                ) : (
                                    <table className="w-full">
                                        <thead>
                                            <tr className="border-b border-gray-700/50">
                                                <th className="text-left p-4 text-gray-400 font-medium">NIS</th>
                                                <th className="text-left p-4 text-gray-400 font-medium">Nama</th>
                                                <th className="text-left p-4 text-gray-400 font-medium">JK</th>
                                                {selectedClass === null && (
                                                    <th className="text-left p-4 text-gray-400 font-medium">Aksi</th>
                                                )}
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {(selectedClass === null ? studentsWithoutClass : filteredStudents).map((student) => (
                                                <tr key={student.id} className="border-b border-gray-700/30 hover:bg-gray-700/20">
                                                    <td className="p-4 text-gray-300 font-mono text-sm">{student.nis}</td>
                                                    <td className="p-4 text-white">{student.name}</td>
                                                    <td className="p-4">
                                                        <span className={`px-2 py-1 rounded text-xs font-medium ${student.gender === 'L'
                                                            ? 'bg-blue-500/20 text-blue-400'
                                                            : 'bg-pink-500/20 text-pink-400'
                                                            }`}>
                                                            {student.gender === 'L' ? 'Laki-laki' : 'Perempuan'}
                                                        </span>
                                                    </td>
                                                    {selectedClass === null && (
                                                        <td className="p-4">
                                                            <button className="px-3 py-1.5 bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-400 rounded-lg text-sm font-medium transition-colors flex items-center gap-1">
                                                                <UserPlus className="w-4 h-4" />
                                                                Masukkan ke Kelas
                                                            </button>
                                                        </td>
                                                    )}
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                )}
                            </div>
                        </div>
                    )}
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Plus,
    Search,
    Edit,
    Trash2,
    CheckCircle2,
    GraduationCap,
    X
} from 'lucide-react';

import { classesService, ClassWithRelations } from '@/lib/services/classes';
import { Loader2 } from 'lucide-react';
import ClassModal from '@/components/admin/ClassModal';

export default function ManajemenKelasPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterLevel, setFilterLevel] = useState('Semua');
    const [classes, setClasses] = useState<ClassWithRelations[]>([]);
    const [studentCounts, setStudentCounts] = useState<Record<string, number>>({});
    const [isLoading, setIsLoading] = useState(true);

    // Modal state
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedClass, setSelectedClass] = useState<ClassWithRelations | null>(null);

    // Promote State
    const [isPromoteModalOpen, setIsPromoteModalOpen] = useState(false);
    const [promoteFrom, setPromoteFrom] = useState('');
    const [promoteTo, setPromoteTo] = useState('');
    const [isPromoting, setIsPromoting] = useState(false);

    const fetchData = async () => {
        try {
            setIsLoading(true);
            const [classesData, counts] = await Promise.all([
                classesService.getAll(),
                classesService.getStudentCounts()
            ]);
            setClasses(classesData);
            setStudentCounts(counts);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching classes:', error);
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_akademik' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleOpenAddModal = () => {
        setSelectedClass(null);
        setIsModalOpen(true);
    };

    const handleOpenEditModal = (cls: ClassWithRelations) => {
        setSelectedClass(cls);
        setIsModalOpen(true);
    };

    const handleSubmitClass = async (data: any) => {
        try {
            if (selectedClass) {
                await classesService.update(selectedClass.id, data);
            } else {
                await classesService.create(data);
            }
            fetchData();
        } catch (error) {
            console.error('Error saving class:', error);
            throw error;
        }
    };

    const handlePromote = async () => {
        if (!promoteFrom || !promoteTo) {
            alert('Mohon pilih kelas asal dan tujuan!');
            return;
        }
        if (promoteFrom === promoteTo) {
            alert('Kelas asal dan tujuan tidak boleh sama!');
            return;
        }

        if (!confirm('Anda yakin ingin memindahkan SELURUH siswa dari kelas asal ke kelas tujuan? Tindakan ini tidak dapat dibatalkan dengan mudah.')) return;

        setIsPromoting(true);
        try {
            const res = await classesService.promoteStudents(promoteFrom, promoteTo);
            alert(`Berhasil memindahkan ${res.moved_count} siswa!`);
            setIsPromoteModalOpen(false);
            setPromoteFrom('');
            setPromoteTo('');
            fetchData();
        } catch (error) {
            console.error(error);
            alert('Gagal melakukan kenaikan kelas.');
        } finally {
            setIsPromoting(false);
        }
    };

    const handleDeleteClass = async (id: string) => {
        if (confirm('Apakah Anda yakin ingin menghapus kelas ini? Semua data terkait (jadwal, dsb) mungkin akan hilang.')) {
            try {
                await classesService.delete(id);
                fetchData();
            } catch (error) {
                alert('Gagal menghapus kelas. Pastikan tidak ada data santri yang terhubung.');
            }
        }
    };

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-blue-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
                    <span>Loading Data Kelas...</span>
                </div>
            </div>
        );
    }

    const filteredClasses = classes.filter(cls => {
        const matchesSearch = cls.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            (cls.homeroom_teacher?.name.toLowerCase().includes(searchQuery.toLowerCase()));

        const isTsanawiyah = cls.grade_level >= 7 && cls.grade_level <= 9;
        const isAliyah = cls.grade_level >= 10 && cls.grade_level <= 12;

        const matchesLevel = filterLevel === 'Semua' ||
            (filterLevel === 'Tsanawiyah' && isTsanawiyah) ||
            (filterLevel === 'Aliyah' && isAliyah);

        return matchesSearch && matchesLevel;
    });

    return (
        <div className="min-h-screen bg-[#050505] flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Header */}
                    <div className="mb-10">
                        <Link
                            href="/dashboard/akademik"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-white mb-6 transition-colors group"
                        >
                            <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                            <div>
                                <h1 className="text-3xl font-black text-white tracking-tight flex items-center gap-3">
                                    <span className="w-2 h-8 bg-blue-600 rounded-full block"></span>
                                    Data Kelas & Rombel
                                </h1>
                                <p className="text-gray-400 mt-1">
                                    Kelola rombongan belajar dan penugasan wali kelas
                                </p>
                            </div>
                            <div className="flex flex-wrap gap-3">
                                <button
                                    onClick={() => setIsPromoteModalOpen(true)}
                                    className="flex items-center gap-2 px-6 py-3.5 bg-indigo-600/10 hover:bg-indigo-600 text-indigo-400 hover:text-white border border-indigo-500/20 rounded-2xl font-bold transition-all shadow-lg active:scale-95"
                                >
                                    <GraduationCap className="w-5 h-5" />
                                    Kenaikan Kelas
                                </button>
                                <button
                                    onClick={handleOpenAddModal}
                                    className="flex items-center gap-2 px-6 py-3.5 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-bold transition-all shadow-lg shadow-blue-500/20 active:scale-95"
                                >
                                    <Plus className="w-5 h-5" />
                                    Tambah Kelas
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Promote Modal */}
                    {isPromoteModalOpen && (
                        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
                            <div className="bg-neutral-900 w-full max-w-lg rounded-[2.5rem] shadow-2xl border border-white/10 overflow-hidden animate-in zoom-in-95 duration-300 p-8">
                                <div className="flex justify-between items-center mb-6">
                                    <h2 className="text-xl font-black text-white flex items-center gap-3">
                                        <GraduationCap className="w-6 h-6 text-indigo-500" />
                                        Batch Kenaikan Kelas
                                    </h2>
                                    <button
                                        onClick={() => setIsPromoteModalOpen(false)}
                                        className="p-2 hover:bg-white/5 rounded-full transition-colors"
                                    >
                                        <X className="w-5 h-5 text-gray-500" />
                                    </button>
                                </div>
                                <div className="p-4 bg-indigo-500/5 border border-indigo-500/20 rounded-2xl mb-8">
                                    <p className="text-sm text-indigo-300 font-medium leading-relaxed">
                                        Pindahkan seluruh siswa secara massal. Pastikan kapasitas kelas tujuan mencukupi sebelum memproses.
                                    </p>
                                </div>

                                <div className="space-y-6">
                                    <div className="space-y-2">
                                        <label className="block text-xs font-black text-gray-500 uppercase tracking-widest ml-1">Dari Kelas (Sumber)</label>
                                        <select
                                            value={promoteFrom}
                                            onChange={(e) => setPromoteFrom(e.target.value)}
                                            className="w-full px-5 py-4 bg-black/40 border border-white/5 rounded-2xl text-white font-bold appearance-none focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all"
                                        >
                                            <option value="" className="bg-neutral-900">-- Pilih Kelas Asal --</option>
                                            {classes.map(c => (
                                                <option key={c.id} value={c.id} className="bg-neutral-900">{c.name} (Santri: {studentCounts[c.id] || 0})</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="flex justify-center relative -my-4 z-10">
                                        <div className="w-10 h-10 bg-indigo-600 rounded-full flex items-center justify-center shadow-lg border-4 border-neutral-900">
                                            <ArrowLeft className="w-5 h-5 rotate-[-90deg] text-white" />
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="block text-xs font-black text-gray-500 uppercase tracking-widest ml-1">Ke Kelas (Tujuan)</label>
                                        <select
                                            value={promoteTo}
                                            onChange={(e) => setPromoteTo(e.target.value)}
                                            className="w-full px-5 py-4 bg-black/40 border border-white/5 rounded-2xl text-white font-bold appearance-none focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all"
                                        >
                                            <option value="" className="bg-neutral-900">-- Pilih Kelas Tujuan --</option>
                                            {classes.map(c => (
                                                <option key={c.id} value={c.id} className="bg-neutral-900">{c.name} (Kapasitas: {c.capacity})</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>

                                <div className="pt-8 flex gap-4">
                                    <button
                                        onClick={() => setIsPromoteModalOpen(false)}
                                        className="flex-1 py-4 bg-neutral-800 hover:bg-neutral-700 text-gray-400 font-bold rounded-2xl transition-all"
                                    >
                                        Batal
                                    </button>
                                    <button
                                        onClick={handlePromote}
                                        disabled={isPromoting}
                                        className="flex-[2] py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-indigo-500/20 active:scale-95 transition-all disabled:opacity-50"
                                    >
                                        {isPromoting ? <Loader2 className="animate-spin" /> : <CheckCircle2 className="w-5 h-5" />}
                                        Proses Kenaikan
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Modal */}
                    <ClassModal
                        isOpen={isModalOpen}
                        onClose={() => setIsModalOpen(false)}
                        onSubmit={handleSubmitClass}
                        classData={selectedClass}
                    />

                    {/* Filters & Stats */}
                    <div className="flex flex-col lg:flex-row gap-6 mb-8">
                        <div className="flex-1 relative">
                            <Search className="w-6 h-6 text-gray-600 absolute left-4 top-1/2 -translate-y-1/2" />
                            <input
                                type="text"
                                placeholder="Cari nama kelas atau wali kelas..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="w-full pl-12 pr-6 py-4 bg-neutral-900/40 border border-white/5 rounded-[1.5rem] text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all backdrop-blur-sm"
                            />
                        </div>
                        <div className="flex gap-4">
                            <div className="bg-neutral-900/40 border border-white/5 rounded-[1.5rem] p-1 flex items-center backdrop-blur-sm">
                                {['Semua', 'Tsanawiyah', 'Aliyah'].map((level) => (
                                    <button
                                        key={level}
                                        onClick={() => setFilterLevel(level)}
                                        className={`px-6 py-2.5 rounded-2xl text-sm font-bold transition-all ${filterLevel === level
                                            ? 'bg-blue-600 text-white shadow-lg'
                                            : 'text-gray-500 hover:text-white'
                                            }`}
                                    >
                                        {level}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Classes Grid - Better for 3D UI than just a table */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {filteredClasses.map((cls) => {
                            const isTsanawiyah = cls.grade_level >= 7 && cls.grade_level <= 9;
                            const currentTotal = studentCounts[cls.id] || 0;
                            const capacity = cls.capacity || 30;
                            const fillPercent = Math.min((currentTotal / capacity) * 100, 100);

                            return (
                                <div
                                    key={cls.id}
                                    className="group relative bg-neutral-900/60 border border-white/5 rounded-[2.5rem] overflow-hidden transition-all duration-300 hover:shadow-[0_20px_50px_rgba(37,99,235,0.1)] hover:-translate-y-1"
                                >
                                    {/* 3D Glass Effect Overlay */}
                                    <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-tr from-white/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"></div>

                                    <div className="p-7">
                                        <div className="flex items-start justify-between mb-6">
                                            <div className="flex items-center gap-4">
                                                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl shadow-lg border transition-transform group-hover:scale-110 duration-500 ${isTsanawiyah
                                                    ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400'
                                                    : 'bg-purple-500/10 border-purple-500/20 text-purple-400'
                                                    }`}>
                                                    {cls.grade_level}
                                                </div>
                                                <div>
                                                    <h3 className="text-xl font-black text-white tracking-tight">{cls.name}</h3>
                                                    <div className="flex items-center gap-2 mt-0.5">
                                                        <span className={`text-[10px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md ${isTsanawiyah ? 'bg-emerald-500/20 text-emerald-400' : 'bg-purple-500/20 text-purple-400'
                                                            }`}>
                                                            {isTsanawiyah ? 'Tsanawiyah' : 'Aliyah'}
                                                        </span>
                                                        <span className="w-1 h-1 bg-gray-700 rounded-full"></span>
                                                        <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">
                                                            TA {cls.academic_year?.name || '2025/2026'}
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-1.5 opacity-0 group-hover:opacity-100 transition-all">
                                                <button
                                                    onClick={() => handleOpenEditModal(cls)}
                                                    className="p-2.5 bg-neutral-800 hover:bg-blue-600 text-gray-400 hover:text-white rounded-xl border border-white/5 transition-all active:scale-95"
                                                >
                                                    <Edit className="w-4 h-4" />
                                                </button>
                                                <button
                                                    onClick={() => handleDeleteClass(cls.id)}
                                                    className="p-2.5 bg-neutral-800 hover:bg-rose-600 text-gray-400 hover:text-white rounded-xl border border-white/5 transition-all active:scale-95"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            </div>
                                        </div>

                                        <div className="space-y-5">
                                            {/* Homeroom Teacher */}
                                            <div className="bg-black/40 border border-white/5 rounded-2xl p-4 flex items-center gap-3">
                                                <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center font-black text-white text-[10px] shadow-lg border border-white/10 shrink-0">
                                                    {cls.homeroom_teacher?.name ? cls.homeroom_teacher.name.split(' ').map(n => n[0]).slice(0, 2).join('') : '??'}
                                                </div>
                                                <div className="min-w-0">
                                                    <p className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Wali Kelas</p>
                                                    <p className="text-sm font-bold text-gray-300 truncate">
                                                        {cls.homeroom_teacher?.name || 'Belum ditugaskan'}
                                                    </p>
                                                </div>
                                            </div>

                                            {/* Capacity Progress */}
                                            <div className="space-y-2 px-1">
                                                <div className="flex justify-between items-end">
                                                    <p className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Kapasitas Kelas</p>
                                                    <p className="text-sm font-black text-white">
                                                        {currentTotal}
                                                        <span className="text-gray-600 font-bold ml-1">/ {capacity}</span>
                                                    </p>
                                                </div>
                                                <div className="h-2 bg-black/60 rounded-full overflow-hidden p-0.5 border border-white/5">
                                                    <div
                                                        className={`h-full rounded-full transition-all duration-1000 ${currentTotal >= capacity ? 'bg-rose-500' : currentTotal >= capacity * 0.8 ? 'bg-amber-500' : 'bg-blue-500'
                                                            }`}
                                                        style={{ width: `${fillPercent}%` }}
                                                    />
                                                </div>
                                            </div>
                                        </div>

                                        <div className="mt-6 pt-5 border-t border-white/5 flex items-center justify-between">
                                            <div className="flex items-center gap-1.5 text-emerald-400">
                                                <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.8)]"></div>
                                                <span className="text-[10px] font-black uppercase tracking-widest">Status Aktif</span>
                                            </div>
                                            <Link
                                                href={`/dashboard/akademik/kelas/anggota?id=${cls.id}`}
                                                className="text-[10px] font-black text-blue-500 uppercase tracking-widest hover:text-blue-400 transition-colors"
                                            >
                                                Lihat Santri →
                                            </Link>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>

                    {filteredClasses.length === 0 && (
                        <div className="flex flex-col items-center justify-center py-20 bg-neutral-900/40 border border-white/5 rounded-[2.5rem]">
                            <div className="w-20 h-20 bg-neutral-800 rounded-2xl flex items-center justify-center mb-6 border border-white/5 shadow-inner">
                                <Search className="w-10 h-10 text-gray-600" />
                            </div>
                            <h3 className="text-xl font-bold text-white mb-2">Data tidak ditemukan</h3>
                            <p className="text-gray-500 max-w-xs text-center">
                                Coba kata kunci pencarian lain atau pilih filter jenjang yang berbeda.
                            </p>
                        </div>
                    )}
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Users,
    UserCheck,
    Search,
    Loader2,
    Save,
    X,
    ChevronDown,
    GraduationCap
} from 'lucide-react';
import { classesService, ClassWithRelations } from '@/lib/services/classes';
import { teachersService } from '@/lib/services/teachers';

interface Teacher {
    id: string;
    name: string;
    user_id?: string | null;
}

export default function WaliKelasPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [classes, setClasses] = useState<ClassWithRelations[]>([]);
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [isSaving, setIsSaving] = useState<string | null>(null);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || !['super_admin', 'admin_akademik'].includes(currentUser.role)) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router]);

    const fetchData = async () => {
        try {
            setIsLoading(true);
            const [classesData, teachersData] = await Promise.all([
                classesService.getAll(),
                teachersService.getAll()
            ]);
            setClasses(classesData);
            setTeachers(teachersData);
        } catch (error) {
            console.error('Error fetching data:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleAssignWali = async (classId: string, teacherId: string | null) => {
        setIsSaving(classId);
        try {
            await classesService.update(classId, { homeroom_teacher_id: teacherId });
            // Update local state
            setClasses(prev => prev.map(c =>
                c.id === classId ? { ...c, homeroom_teacher_id: teacherId } : c
            ));
        } catch (error) {
            console.error('Error assigning homeroom teacher:', error);
            alert('Gagal menyimpan wali kelas');
        } finally {
            setIsSaving(null);
        }
    };

    const filteredClasses = classes.filter(c =>
        c.name.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const getTeacherName = (teacherId: string | null | undefined) => {
        if (!teacherId) return null;
        const teacher = teachers.find(t => t.id === teacherId);
        return teacher?.name || null;
    };

    // Check if teacher is already assigned to another class
    const isTeacherAssigned = (teacherId: string, excludeClassId: string) => {
        return classes.some(c => c.homeroom_teacher_id === teacherId && c.id !== excludeClassId);
    };

    if (!user) return null;

    return (
        <div className="min-h-screen bg-black flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader
                    user={user}
                    onMenuClick={() => setSidebarOpen(true)}
                />

                <main className="p-4 lg:p-6">
                    {/* Back Button */}
                    <Link
                        href="/dashboard/akademik/kelas"
                        className="inline-flex items-center gap-2 text-gray-400 hover:text-white mb-6 transition-colors"
                    >
                        <ArrowLeft className="w-4 h-4" />
                        Kembali ke Manajemen Kelas
                    </Link>

                    {/* Header */}
                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
                        <div>
                            <h1 className="text-2xl font-bold text-white">Penugasan Wali Kelas</h1>
                            <p className="text-gray-400">Tentukan guru yang menjadi wali untuk setiap kelas</p>
                        </div>
                    </div>

                    {/* Search */}
                    <div className="relative mb-6 max-w-md">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                        <input
                            type="text"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            placeholder="Cari kelas..."
                            className="w-full pl-10 pr-4 py-3 bg-gray-800/50 border border-gray-700/50 rounded-xl text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
                        />
                    </div>

                    {/* Content */}
                    {isLoading ? (
                        <div className="flex items-center justify-center py-20">
                            <Loader2 className="w-8 h-8 text-emerald-500 animate-spin" />
                        </div>
                    ) : filteredClasses.length === 0 ? (
                        <div className="bg-gray-800/50 rounded-2xl border border-gray-700/50 p-12 text-center">
                            <GraduationCap className="w-16 h-16 text-gray-600 mx-auto mb-4" />
                            <h3 className="text-lg font-medium text-white mb-2">Belum Ada Kelas</h3>
                            <p className="text-gray-400">Tambahkan kelas terlebih dahulu di menu Manajemen Kelas</p>
                        </div>
                    ) : (
                        <div className="bg-gray-800/50 rounded-2xl border border-gray-700/50 overflow-hidden">
                            <table className="w-full">
                                <thead>
                                    <tr className="border-b border-gray-700/50">
                                        <th className="text-left p-4 text-gray-400 font-medium">Kelas</th>
                                        <th className="text-left p-4 text-gray-400 font-medium">Tingkat</th>
                                        <th className="text-left p-4 text-gray-400 font-medium">Wali Kelas</th>
                                        <th className="text-left p-4 text-gray-400 font-medium w-80">Pilih Guru</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {filteredClasses.map((cls) => (
                                        <tr key={cls.id} className="border-b border-gray-700/30 hover:bg-gray-700/20">
                                            <td className="p-4">
                                                <div className="flex items-center gap-3">
                                                    <div className="w-10 h-10 bg-emerald-500/20 rounded-lg flex items-center justify-center">
                                                        <Users className="w-5 h-5 text-emerald-400" />
                                                    </div>
                                                    <span className="font-medium text-white">{cls.name}</span>
                                                </div>
                                            </td>
                                            <td className="p-4 text-gray-400">
                                                Kelas {cls.grade_level}
                                            </td>
                                            <td className="p-4">
                                                {getTeacherName(cls.homeroom_teacher_id) ? (
                                                    <span className="px-3 py-1 bg-emerald-500/20 text-emerald-400 rounded-full text-sm font-medium">
                                                        {getTeacherName(cls.homeroom_teacher_id)}
                                                    </span>
                                                ) : (
                                                    <span className="text-gray-500 italic">Belum ditentukan</span>
                                                )}
                                            </td>
                                            <td className="p-4">
                                                <div className="flex items-center gap-2">
                                                    <div className="relative flex-1">
                                                        <select
                                                            value={cls.homeroom_teacher_id || ''}
                                                            onChange={(e) => handleAssignWali(cls.id, e.target.value || null)}
                                                            disabled={isSaving === cls.id}
                                                            className="w-full px-3 py-2 bg-gray-700/50 border border-gray-600 rounded-lg text-white appearance-none focus:outline-none focus:ring-2 focus:ring-emerald-500/50 disabled:opacity-50"
                                                        >
                                                            <option value="">-- Pilih Guru --</option>
                                                            {teachers.map((teacher) => (
                                                                <option
                                                                    key={teacher.id}
                                                                    value={teacher.id}
                                                                    disabled={isTeacherAssigned(teacher.id, cls.id)}
                                                                >
                                                                    {teacher.name} {isTeacherAssigned(teacher.id, cls.id) ? '(Sudah jadi Wali Kelas)' : ''}
                                                                </option>
                                                            ))}
                                                        </select>
                                                        <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                                                    </div>
                                                    {isSaving === cls.id && (
                                                        <Loader2 className="w-5 h-5 text-emerald-500 animate-spin" />
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}

                    {/* Info */}
                    <div className="mt-6 p-4 bg-blue-500/10 border border-blue-500/30 rounded-xl">
                        <div className="flex items-start gap-3">
                            <UserCheck className="w-5 h-5 text-blue-400 mt-0.5" />
                            <div>
                                <h4 className="font-medium text-blue-300">Catatan Penting</h4>
                                <p className="text-sm text-blue-300/80 mt-1">
                                    Satu guru hanya dapat menjadi wali kelas untuk satu kelas saja.
                                    Guru yang sudah ditugaskan akan ditandai dan tidak dapat dipilih untuk kelas lain.
                                </p>
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

