'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Plus,
    Search,
    FileSpreadsheet,
    Edit,
    Trash2
} from 'lucide-react';

import { subjectsService } from '@/lib/services/academic';
import { Subject } from '@/types/database.types';
import { Loader2 } from 'lucide-react';
import SubjectModal from '@/components/admin/SubjectModal';

export default function MataPelajaranPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedCategory, setSelectedCategory] = useState('Semua');
    const [subjects, setSubjects] = useState<Subject[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Modal state
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedSubject, setSelectedSubject] = useState<Subject | null>(null);

    const fetchSubjects = async () => {
        try {
            setIsLoading(true);
            const data = await subjectsService.getAll(false); // Show all including inactive for admin
            setSubjects(data);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching subjects:', error);
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_akademik' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchSubjects();
    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleOpenAddModal = () => {
        setSelectedSubject(null);
        setIsModalOpen(true);
    };

    const handleOpenEditModal = (subject: any) => {
        setSelectedSubject(subject);
        setIsModalOpen(true);
    };

    const handleSubmitSubject = async (data: any) => {
        try {
            if (selectedSubject) {
                await subjectsService.update(selectedSubject.id, data);
            } else {
                // Add pesantren_id from current user
                const dataWithPesantren = {
                    ...data,
                    pesantren_id: user?.pesantrenId || null
                };
                console.log('Submitting subject data:', dataWithPesantren);
                await subjectsService.create(dataWithPesantren);
            }
            fetchSubjects();
        } catch (error) {
            console.error('Error saving subject:', error);
            throw error;
        }
    };

    const handleDeleteSubject = async (id: string) => {
        if (confirm('Apakah Anda yakin ingin MENGHAPUS PERMANEN mata pelajaran ini?\n\nPeringatan: Data yang sudah dihapus tidak bisa dikembalikan!')) {
            try {
                await subjectsService.delete(id);
                fetchSubjects();
                alert('Mata pelajaran berhasil dihapus!');
            } catch (error: any) {
                console.error('Delete error:', error);
                if (error.message?.includes('violates foreign key')) {
                    alert('Gagal menghapus!\n\nMata pelajaran ini masih digunakan di jadwal atau nilai siswa.\n\nHapus data terkait terlebih dahulu, atau nonaktifkan saja melalui Edit.');
                } else {
                    alert('Gagal menghapus mata pelajaran:\n' + (error.message || 'Unknown error'));
                }
            }
        }
    };

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-blue-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
                    <span>Loading Mata Pelajaran...</span>
                </div>
            </div>
        );
    }

    const filteredSubjects = subjects.filter(s => {
        const matchesSearch = s.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            s.code.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesCategory = selectedCategory === 'Semua' || s.category === selectedCategory;
        return matchesSearch && matchesCategory;
    });

    return (
        <div className="min-h-screen bg-[#050505] flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Header */}
                    <div className="mb-10">
                        <Link
                            href="/dashboard/akademik"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-white mb-6 transition-colors group"
                        >
                            <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                            <div>
                                <h1 className="text-3xl font-black text-white tracking-tight flex items-center gap-3">
                                    <span className="w-2 h-8 bg-blue-600 rounded-full block"></span>
                                    Mata Pelajaran
                                </h1>
                                <p className="text-gray-400 mt-1">
                                    Daftar kurikulum mata pelajaran Diniyah dan Umum
                                </p>
                            </div>
                            <button
                                onClick={handleOpenAddModal}
                                className="flex items-center gap-2 px-6 py-3.5 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-bold transition-all shadow-lg shadow-blue-500/20 active:scale-95"
                            >
                                <Plus className="w-5 h-5" />
                                Tambah Mapel
                            </button>
                        </div>
                    </div>

                    <SubjectModal
                        isOpen={isModalOpen}
                        onClose={() => setIsModalOpen(false)}
                        onSubmit={handleSubmitSubject}
                        subjectData={selectedSubject}
                    />

                    {/* Stats & Filters */}
                    <div className="flex flex-col lg:flex-row gap-6 mb-8">
                        <div className="flex-1 relative">
                            <Search className="w-6 h-6 text-gray-600 absolute left-4 top-1/2 -translate-y-1/2" />
                            <input
                                type="text"
                                placeholder="Cari nama atau kode mapel..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="w-full pl-12 pr-6 py-4 bg-neutral-900/40 border border-white/5 rounded-[1.5rem] text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all backdrop-blur-sm"
                            />
                        </div>
                        <div className="flex items-center gap-4">
                            <div className="bg-neutral-900/40 border border-white/5 rounded-[1.5rem] p-1.5 flex items-center backdrop-blur-sm">
                                {['Semua', 'Diniyah', 'Umum'].map((cat) => (
                                    <button
                                        key={cat}
                                        onClick={() => setSelectedCategory(cat)}
                                        className={`px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${selectedCategory === cat
                                            ? 'bg-blue-600 text-white shadow-lg'
                                            : 'text-gray-500 hover:text-white'
                                            }`}
                                    >
                                        {cat}
                                    </button>
                                ))}
                            </div>
                            <button className="p-4 bg-neutral-900 border border-white/5 rounded-2xl text-gray-500 hover:text-white transition-all active:scale-90 shadow-lg">
                                <FileSpreadsheet className="w-5 h-5" />
                            </button>
                        </div>
                    </div>

                    {/* Grid Layout for premium feel instead of plain table */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {filteredSubjects.map((s) => (
                            <div
                                key={s.id}
                                className="group relative bg-neutral-900/60 border border-white/5 rounded-[2.5rem] overflow-hidden transition-all duration-300 hover:shadow-2xl hover:border-white/10 hover:-translate-y-1"
                            >
                                <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-tr from-white/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"></div>

                                <div className="p-7">
                                    <div className="flex items-start justify-between mb-6">
                                        <div className="flex items-center gap-4">
                                            <div className="w-12 h-12 bg-black/40 border border-white/5 rounded-2xl flex items-center justify-center font-black text-xs text-blue-500 shadow-inner group-hover:scale-110 transition-transform duration-500">
                                                {s.code}
                                            </div>
                                            <div>
                                                <h3 className="font-black text-white tracking-tight group-hover:text-blue-400 transition-colors uppercase leading-tight">{s.name}</h3>
                                                <span className={`inline-block mt-1 text-[8px] font-black uppercase tracking-[0.2em] px-2 py-0.5 rounded ${s.category === 'Diniyah' ? 'bg-emerald-500/10 text-emerald-500' : 'bg-blue-500/10 text-blue-500'
                                                    }`}>
                                                    {s.category || 'Umum'}
                                                </span>
                                            </div>
                                        </div>
                                        <div className="flex gap-1.5 opacity-0 group-hover:opacity-100 transition-all">
                                            <button
                                                onClick={() => handleOpenEditModal(s)}
                                                className="p-2.5 bg-neutral-800 hover:bg-blue-600 text-gray-500 hover:text-white rounded-xl border border-white/5 transition-all active:scale-95"
                                            >
                                                <Edit className="w-4 h-4" />
                                            </button>
                                            <button
                                                onClick={() => handleDeleteSubject(s.id)}
                                                className="p-2.5 bg-neutral-800 hover:bg-rose-600 text-gray-500 hover:text-white rounded-xl border border-white/5 transition-all active:scale-95"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="bg-black/30 border border-white/5 rounded-2xl p-4 flex flex-col items-center">
                                            <span className="text-[8px] font-black text-gray-600 uppercase tracking-widest mb-1">Durasi</span>
                                            <span className="text-sm font-black text-white">{s.credit_hours || 2} <span className="text-[10px] text-gray-500 ml-1">JP</span></span>
                                        </div>
                                        <div className="bg-black/30 border border-white/5 rounded-2xl p-4 flex flex-col items-center">
                                            <span className="text-[8px] font-black text-gray-600 uppercase tracking-widest mb-1">KKM</span>
                                            <span className="text-sm font-black text-white">75</span>
                                        </div>
                                    </div>

                                    {!(s as any).is_active && (
                                        <div className="mt-6 flex items-center justify-center gap-2 bg-rose-500/10 border border-rose-500/20 py-2 rounded-xl">
                                            <div className="w-1.5 h-1.5 bg-rose-500 rounded-full"></div>
                                            <span className="text-[10px] font-black text-rose-500 uppercase tracking-widest">Non-Aktif</span>
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>

                    {filteredSubjects.length === 0 && (
                        <div className="flex flex-col items-center justify-center py-24 bg-neutral-900/40 border border-white/5 rounded-[3rem]">
                            <div className="w-20 h-20 bg-neutral-800 rounded-2xl flex items-center justify-center mb-6 border border-white/5">
                                <Search className="w-10 h-10 text-gray-600" />
                            </div>
                            <h3 className="text-xl font-black text-white mb-2">Mapel tidak ditemukan</h3>
                            <p className="text-gray-500 max-w-xs text-center">
                                Coba kata kunci nama atau kode mata pelajaran yang berbeda.
                            </p>
                        </div>
                    )}
                </main>
            </div>
        </div>
    );
}

