'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import {
    GraduationCap,
    Users,
    CalendarDays,
    BookMarked,
    Clock,
    ArrowUpRight,
    TrendingUp
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ChartCard,
    ClassDensityChart,
    GenderRatioChart,
    TeacherLoadChart
} from '@/components/charts';

import { studentsService } from '@/lib/services/students';
import { teachersService } from '@/lib/services/teachers';
import { classesService } from '@/lib/services/classes';
import { Loader2 } from 'lucide-react';

export default function AkademikDashboard() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    // Real Data State
    const [stats, setStats] = useState({
        totalStudents: 0,
        totalTeachers: 0,
        totalClasses: 0,
        totalHours: 0
    });
    const [classDensity, setClassDensity] = useState<any[]>([]);
    const [genderRatio, setGenderRatio] = useState<any[]>([]);
    const [teacherLoad, setTeacherLoad] = useState<any[]>([]);

    const fetchData = useCallback(async () => {
        try {
            const [
                studentStats,
                teachers,
                classes,
                density,
                ratio,
                load
            ] = await Promise.all([
                studentsService.getStats(),
                teachersService.getAll(),
                classesService.getAll(),
                classesService.getDensity(),
                studentsService.getGenderRatio(),
                teachersService.getLoad()
            ]);

            setStats({
                totalStudents: studentStats.total,
                totalTeachers: teachers.length,
                totalClasses: classes.length,
                totalHours: load.reduce((acc, curr) => acc + (curr.hours || 0), 0)
            });

            setClassDensity(density);
            setGenderRatio(ratio);
            setTeacherLoad(load);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching akademik data:', error);
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_akademik' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router, fetchData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading || !user) {
        return (
