                                        ) : (
                                            <div className="w-28 h-28 border-2 border-dashed border-white/10 rounded-[2rem] flex flex-col items-center justify-center bg-black/40 gap-2 overflow-hidden relative shrink-0">
                                                {isUploading ? (
