                            >
                                {/* 3D Glass Reflection Overlay */}
                                <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-tr from-white/5 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"></div>

                                <div className="p-7">
                                    <div className="flex items-start justify-between mb-6">
                                        <div className="flex items-center gap-4">
                                            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl shadow-lg border transition-all duration-500 group-hover:scale-110 group-hover:rotate-3 ${s.gender === 'L'
                                                ? 'bg-blue-500/10 border-blue-500/20 text-blue-400'
                                                : 'bg-pink-500/10 border-pink-500/20 text-pink-400'
                                                }`}>
                                                {s.name.charAt(0)}
                                            </div>
                                            <div className="min-w-0">
                                                <h3 className="text-lg font-black text-white tracking-tight truncate leading-tight group-hover:text-blue-400 transition-colors">
