'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import {
    Home,
    Plus,
    Users,
    Search,
    ChevronRight,
    Bed,
    Building2,
    CheckCircle2,
    ArrowLeft,
    Loader2,
    Edit,
    Trash2
} from 'lucide-react';

import { dormitoriesService, DormitoryWithRelations } from '@/lib/services/dormitories';
import DormModal from '@/components/admin/DormModal';

export default function DataAsramaPage() {
    const [searchQuery, setSearchQuery] = useState('');
    const [dorms, setDorms] = useState<DormitoryWithRelations[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Modal state
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedDorm, setSelectedDorm] = useState<any>(null);

    useEffect(() => {
        fetchDorms();
    }, []);

    const fetchDorms = async () => {
        try {
            setIsLoading(true);
            const data = await dormitoriesService.getAll();
            setDorms(data);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching dorms:', error);
            setIsLoading(false);
        }
    };

    const handleOpenAddModal = () => {
        setSelectedDorm(null);
        setIsModalOpen(true);
    };

    const handleOpenEditModal = (dorm: any) => {
        setSelectedDorm(dorm);
        setIsModalOpen(true);
    };

    const handleSubmitDorm = async (data: any) => {
        try {
            if (selectedDorm) {
                await dormitoriesService.update(selectedDorm.id, data);
            } else {
                await dormitoriesService.create(data);
            }
            fetchDorms();
        } catch (error) {
            console.error('Error saving dorm:', error);
            throw error;
        }
    };

    const handleDeleteDorm = async (id: string) => {
        if (confirm('Apakah Anda yakin ingin menghapus data asrama ini? Pastikan tidak ada santri yang terdaftar di kamar ini.')) {
            try {
                await dormitoriesService.delete(id);
                fetchDorms();
            } catch (error) {
                alert('Gagal menghapus data asrama. Mungkin masih ada santri yang terhubung.');
            }
        }
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-96">
                <Loader2 className="w-10 h-10 text-orange-600 animate-spin" />
            </div>
        );
    }

    const filteredDorms = dorms.filter(d =>
        d.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        (d.supervisor?.name.toLowerCase().includes(searchQuery.toLowerCase()))
    );

    const totalCapacity = dorms.reduce((acc, d) => acc + (d.capacity || 0), 0);
    const totalOccupied = dorms.reduce((acc, d) => acc + (d.current_occupancy || 0), 0);
    const totalBuildings = Array.from(new Set(dorms.map(d => d.name.split(' ')[0]))).length || 0;

    return (
        <div>
            {/* Header */}
            <div className="mb-8">
                <Link
                    href="/dashboard/kesantrian"
                    className="inline-flex items-center gap-2 text-sm text-gray-400 hover:text-gray-600 mb-2 transition-colors font-medium"
                >
                    <ArrowLeft className="w-4 h-4" />
                    Kembali ke Dashboard
                </Link>
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div>
                        <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-3">
                            <Home className="w-8 h-8 text-orange-600" />
                            Data Asrama & Kamar
                        </h1>
                        <p className="text-gray-500 text-sm mt-1">
                            Manajemen hunian santri dan penanggung jawab gedung
                        </p>
                    </div>
                    <button
                        onClick={handleOpenAddModal}
                        className="flex items-center gap-2 px-5 py-3 bg-orange-600 hover:bg-orange-700 text-white font-bold rounded-2xl transition-all shadow-md active:scale-95"
                    >
                        <Plus className="w-5 h-5" />
                        Tambah Gedung/Kamar
                    </button>
                </div>
            </div>

            <DormModal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                onSubmit={handleSubmitDorm}
                dormData={selectedDorm}
            />

            {/* Stats Row */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                <div className="bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm flex items-center gap-5">
                    <div className="w-14 h-14 bg-orange-50 rounded-2xl flex items-center justify-center text-orange-600">
                        <Building2 className="w-7 h-7" />
                    </div>
                    <div>
                        <h4 className="text-2xl font-extrabold text-gray-800">{totalBuildings}</h4>
                        <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Gedung</p>
                    </div>
                </div>
                <div className="bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm flex items-center gap-5">
                    <div className="w-14 h-14 bg-blue-50 rounded-2xl flex items-center justify-center text-blue-600">
                        <Bed className="w-7 h-7" />
                    </div>
                    <div>
                        <h4 className="text-2xl font-extrabold text-gray-800">{dorms.length}</h4>
                        <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Total Kamar</p>
                    </div>
                </div>
                <div className="bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm flex items-center gap-5">
                    <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-emerald-600">
                        <Users className="w-7 h-7" />
                    </div>
                    <div>
                        <h4 className="text-2xl font-extrabold text-gray-800">{totalOccupied}/{totalCapacity}</h4>
                        <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Okupansi Santri</p>
                    </div>
                </div>
            </div>

            {/* Search / Filter */}
            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 mb-8">
                <div className="relative">
                    <Search className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                    <input
                        type="text"
                        placeholder="Cari gedung, nomor kamar, atau nama musyrif..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-12 pr-4 py-3.5 bg-gray-50 border border-transparent rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500/20 focus:bg-white focus:border-orange-500 transition-all font-medium text-gray-700"
                    />
                </div>
            </div>

            {/* Dorm Cards Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {filteredDorms.map((dorm) => {
                    const isFull = (dorm.current_occupancy || 0) >= (dorm.capacity || 1);
                    return (
                        <div key={dorm.id} className="bg-white rounded-[2rem] border border-gray-100 shadow-sm overflow-hidden group hover:shadow-xl hover:shadow-orange-900/5 transition-all duration-300">
                            <div className="p-6 border-b border-gray-50 bg-gray-50/30">
                                <div className="flex items-center justify-between mb-1">
                                    <span className={`px-2.5 py-1 text-[10px] font-bold rounded-full uppercase tracking-widest ${isFull ? 'bg-rose-50 text-rose-600' : 'bg-emerald-50 text-emerald-600'
                                        }`}>
                                        {isFull ? 'Full' : 'Available'}
                                    </span>
                                    <button className="text-gray-300 hover:text-orange-500 transition-colors">
                                        <ChevronRight className="w-5 h-5" />
                                    </button>
                                </div>
                                <h3 className="text-lg font-extrabold text-gray-800 leading-tight">{(dorm as any).building || 'Gedung'}</h3>
                                <p className="text-orange-600 font-bold">Kamar {dorm.name}</p>
                            </div>
                            <div className="p-6 space-y-5">
                                <div>
                                    <div className="flex items-center justify-between mb-2">
                                        <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Kapasitas</p>
                                        <p className="text-sm font-bold text-gray-700">{dorm.current_occupancy}/{dorm.capacity} Santri</p>
                                    </div>
                                    <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                                        <div
                                            className={`h-full rounded-full transition-all duration-500 ${isFull ? 'bg-rose-500' : 'bg-emerald-500'
                                                }`}
                                            style={{ width: `${Math.min(((dorm.current_occupancy || 0) / (dorm.capacity || 1)) * 100, 100)}%` }}
                                        />
                                    </div>
                                </div>
                                <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-2xl">
                                    <div className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center font-bold text-orange-600 border border-orange-50">
                                        {dorm.supervisor?.name?.charAt(0) || '?'}
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest leading-none mb-0.5">Musyrif</p>
                                        <p className="text-sm font-bold text-gray-700 leading-tight">{dorm.supervisor?.name || 'Belum ditugaskan'}</p>
                                    </div>
                                    {isFull && (
                                        <CheckCircle2 className="w-5 h-5 text-emerald-400 ml-auto" />
                                    )}
                                </div>
                            </div>
                            <div className="px-6 py-4 bg-gray-50/50 flex items-center justify-between text-xs font-bold text-gray-400">
                                <span>Last Checked: Today</span>
                                <div className="flex items-center gap-2">
                                    <button
                                        onClick={() => handleOpenEditModal(dorm)}
                                        className="p-2 text-gray-400 hover:text-orange-600 hover:bg-white rounded-lg transition-all shadow-sm"
                                    >
                                        <Edit className="w-4 h-4" />
                                    </button>
                                    <button
                                        onClick={() => handleDeleteDorm(dorm.id)}
                                        className="p-2 text-gray-400 hover:text-rose-600 hover:bg-white rounded-lg transition-all shadow-sm"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import {
    ArrowLeft,
    ClipboardList,
    FileText,
    Download,
    Calendar,
    Filter,
    ArrowUpRight,
    PieChart,
    BarChart3,
    CheckCircle2,
    Loader2
} from 'lucide-react';
import { kesantrianService } from '@/lib/services/kesantrian';
import { dormitoriesService } from '@/lib/services/dormitories';
import { generatePDF } from '@/lib/pdf-generator';

export default function LaporanKesantrianPage() {
    const [isGenerating, setIsGenerating] = useState<string | null>(null);

    const handleDownload = async (type: string) => {
        setIsGenerating(type);
        try {
            let data: any[] = [];

            switch (type) {
                case 'monthly-violations':
                    // Fetch all violations (filtering handled in generator or here if needed)
                    // For now getting all, ideally filtered by month selected
                    const allViolations = await kesantrianService.getAllViolations();
                    // Optional: Filter for current month if needed, but report says "Laporan Bulanan"
                    // Let's assume we want all for this demo or filtered by the UI "Januari 2026" text if it was real state
                    data = allViolations;
                    break;

                case 'top-offenders':
                    data = await kesantrianService.getTopViolators();
                    break;

                case 'permits-summary':
                    // Combine pending and history if needed, or just history
                    // Reports usually want finalized data
                    const history = await kesantrianService.getPermissionHistory();
                    data = history;
                    break;

                case 'dorm-occupancy':
                    data = await dormitoriesService.getAll();
                    break;
            }

            if (data && data.length > 0) {
                generatePDF(type, data);
            } else {
                alert('Tidak ada data untuk laporan ini.');
            }

        } catch (error) {
            console.error('Error generating report:', error);
            alert('Gagal membuat laporan. Silakan coba lagi.');
        } finally {
            setIsGenerating(null);
        }
    };

    const reports = [
        {
            id: 'monthly-violations',
            title: 'Laporan Pelanggaran Bulanan',
            desc: 'Rekap seluruh pelanggaran santri per bulan beserta poin akumulasi.',
            icon: FileText,
            color: 'rose'
        },
        {
            id: 'top-offenders',
            title: 'Santri Top Poin (Bermasalah)',
            desc: 'Daftar santri dengan poin pelanggaran tertinggi untuk tindak lanjut.',
            icon: BarChart3,
            color: 'orange'
        },
        {
            id: 'permits-summary',
            title: 'Rekap Perizinan Keluar',
            desc: 'Data statistik perizinan santri, alasan terbanyak, dan keterlambatan kembali.',
            icon: PieChart,
            color: 'indigo'
        },
        {
            id: 'dorm-occupancy',
            title: 'Laporan Okupansi Asrama',
            desc: 'Status hunian gedung dan kamar per semester berjalan.',
            icon: ClipboardList,
            color: 'emerald'
        }
    ];

    return (
        <div>
            {/* Header */}
            <div className="mb-8">
                <Link
                    href="/dashboard/kesantrian"
                    className="inline-flex items-center gap-2 text-sm text-gray-400 hover:text-gray-600 mb-2 transition-colors font-medium"
                >
                    <ArrowLeft className="w-4 h-4" />
                    Kembali ke Dashboard
                </Link>
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div>
                        <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-3">
                            <ClipboardList className="w-8 h-8 text-orange-600" />
                            Pusat Laporan Kesantrian
                        </h1>
                        <p className="text-gray-500 text-sm">
                            Export data kedisiplinan dan perizinan dalam format PDF/Excel
                        </p>
                    </div>
                </div>
            </div>

            {/* Export Controls */}
            <div className="bg-white rounded-[2rem] border border-gray-100 shadow-sm p-6 mb-8 flex flex-wrap gap-4 items-center">
                <div className="flex items-center gap-3 px-4 py-2 bg-gray-50 rounded-xl border border-gray-100">
                    <Calendar className="w-4 h-4 text-gray-400" />
                    <span className="text-sm font-bold text-gray-600 tracking-wide">Januari 2026</span>
                    <Filter className="w-4 h-4 text-gray-300 ml-2" />
                </div>
                <div className="flex items-center gap-3 px-4 py-2 bg-gray-50 rounded-xl border border-gray-100">
                    <span className="text-sm font-bold text-gray-600 tracking-wide">Semua Jenjang</span>
                    <ArrowUpRight className="w-4 h-4 text-gray-300" />
                </div>
                <p className="text-xs font-bold text-gray-300 uppercase tracking-[0.2em] ml-auto mr-4 hidden lg:block">Data Sync: 10m ago</p>
            </div>

            {/* Reports Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {reports.map((report) => (
                    <div key={report.id} className="bg-white rounded-[2rem] border border-gray-100 shadow-sm p-8 group hover:border-orange-200 transition-all duration-300 relative overflow-hidden">
                        <div className={`absolute top-0 right-0 w-32 h-32 bg-${report.color}-50 rounded-full -mr-16 -mt-16 opacity-50 group-hover:scale-110 transition-transform`} />

                        <div className="relative z-10">
                            <div className={`w-14 h-14 bg-${report.color}-50 text-${report.color}-600 rounded-2xl flex items-center justify-center mb-6 shadow-sm`}>
                                <report.icon className="w-7 h-7" />
                            </div>
                            <h3 className="text-lg font-extrabold text-gray-800 mb-2 group-hover:text-orange-600 transition-colors uppercase tracking-tight">{report.title}</h3>
                            <p className="text-gray-500 text-sm leading-relaxed mb-8">{report.desc}</p>

                            <div className="flex items-center justify-between pt-6 border-t border-gray-50">
                                <div className="flex flex-col">
                                    <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Terakhir Dibuat</span>
                                    <span className="text-xs font-bold text-gray-700">31 Des 2025</span>
                                </div>
                                <button
                                    onClick={() => handleDownload(report.id)}
                                    disabled={isGenerating !== null}
                                    className="flex items-center gap-2 px-6 py-3 bg-gray-900 hover:bg-black text-white font-bold rounded-2xl text-xs transition-all active:scale-95 disabled:opacity-50"
                                >
                                    {isGenerating === report.id ? (
                                        <>
                                            <Loader2 className="w-4 h-4 animate-spin" />
                                            Memproses...
                                        </>
                                    ) : (
                                        <>
                                            <Download className="w-4 h-4" />
                                            DOWNLOAD PDF
                                        </>
                                    )}
                                </button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Quick Tips */}
            <div className="mt-12 bg-orange-50/50 rounded-[2rem] p-8 border border-orange-100 border-dashed">
                <div className="flex items-center gap-4 mb-4">
                    <div className="p-2 bg-orange-100 rounded-lg text-orange-600"><CheckCircle2 className="w-5 h-5" /></div>
                    <h4 className="font-bold text-gray-800 uppercase tracking-wider">Tips Pelaporan</h4>
                </div>
                <p className="text-sm text-gray-500 leading-relaxed max-w-2xl">
                    Pastikan seluruh data pelanggaran dan perizinan telah divalidasi oleh Musyrif Gedung masing-masing sebelum mengunduh laporan bulanan. Data santri top poin akan direset setiap pergantian tahun ajaran baru.
                </p>
            </div>
        </div>
    );
}

