'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    FileText,
    Calendar,
    TrendingUp,
    TrendingDown,
    Wallet,
    Download,
    FileSpreadsheet,
    Printer,
    Loader2,
    CheckCircle,
    Clock,
    AlertCircle,
    PieChart
} from 'lucide-react';

import { financeService } from '@/lib/services/finance';
import * as XLSX from 'xlsx';

export default function LaporanPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);

    // Set default dates to current month
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];

    const [startDate, setStartDate] = useState(firstDay);
    const [endDate, setEndDate] = useState(lastDay);
    const [isLoading, setIsLoading] = useState(true);
    const [reportData, setReportData] = useState<any>(null);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_keuangan' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchReport();
    }, [router]);

    const fetchReport = async () => {
        try {
            setIsLoading(true);
            const data = await financeService.getReport({ startDate, endDate });
            setReportData(data);
        } catch (error) {
            console.error('Error fetching report:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleExport = async () => {
        try {
            const data = await financeService.getExportData(startDate, endDate);

            // 1. Summary Sheet
            const summaryData = [
                ['Laporan Keuangan Smart Pesantren'],
                [`Periode: ${startDate} s/d ${endDate}`],
                [''],
                ['Ringkasan Pemasukan & Pengeluaran'],
                ['Total Tagihan', formatCurrency(summary.totalInvoiced)],
                ['Total Pemasukan (Terbayar)', formatCurrency(summary.totalPaid)],
                ['Total Pengeluaran', formatCurrency(summary.totalExpense)],
                ['Laba Bersih / Surplus', formatCurrency(summary.netIncome)],
                ['Total Tunggakan', formatCurrency(summary.totalUnpaid)]
            ];
            const wsSummary = XLSX.utils.aoa_to_sheet(summaryData);

            // 2. Invoices Sheet (Detailed)
            const invoiceRows = data.invoices.map((inv: any) => {
                const totalPaid = (inv.payments || []).reduce((sum: number, p: any) => sum + Number(p.amount), 0);
                const remaining = Number(inv.amount) - totalPaid;
                return {
                    'Invoice ID': inv.id,
                    'Tanggal': new Date(inv.created_at).toLocaleDateString('id-ID'),
                    'Nama Santri': inv.students?.name || 'Unknown',
                    'Kelas': inv.students?.classes?.name || '-',
                    'Jenis Tagihan': inv.invoice_type,
                    'Nominal Tagihan': Number(inv.amount),
                    'Sudah Bayar': totalPaid,
                    'Sisa Tagihan': remaining,
                    'Status': inv.status === 'paid' ? 'Lunas' : (inv.status === 'partial' ? 'Cicilan' : 'Belum Lunas'),
                    'Jatuh Tempo': new Date(inv.due_date).toLocaleDateString('id-ID')
                };
            });
            const wsInvoices = XLSX.utils.json_to_sheet(invoiceRows);

            // 3. Expenses Sheet
            const expenseRows = data.expenses.map((exp: any) => ({
                'Tanggal': new Date(exp.expense_date).toLocaleDateString('id-ID'),
                'Kategori': exp.category,
                'Deskripsi': exp.description,
                'Nominal': Number(exp.amount),
                'PIC': exp.pic || '-'
            }));
            const wsExpenses = XLSX.utils.json_to_sheet(expenseRows);

            // Create Workbook
            const wb = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(wb, wsSummary, "Ringkasan");
            XLSX.utils.book_append_sheet(wb, wsInvoices, "Data Tagihan");
            XLSX.utils.book_append_sheet(wb, wsExpenses, "Data Pengeluaran");

            // Download
            XLSX.writeFile(wb, `Laporan_Keuangan_${startDate}_${endDate}.xlsx`);
        } catch (error) {
            console.error('Export failed:', error);
            alert('Gagal mengexport data.');
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const formatCurrency = (amount: number | undefined | null) => {
        if (amount === undefined || amount === null || isNaN(amount)) return 'Rp 0';
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            minimumFractionDigits: 0
        }).format(amount);
    };

    if (!user || isLoading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-emerald-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
                    <span>Menyiapkan Laporan Keuangan...</span>
                </div>
            </div>
        );
    }

    const summary = reportData?.summary || {
        totalInvoiced: 0,
        totalPaid: 0,
        totalUnpaid: 0,
        totalExpense: 0,
        netIncome: 0,
        collectionRate: 0
    };

    const invoiceCount = reportData?.invoiceCount || {
        total: 0,
        paid: 0,
        partial: 0,
        pending: 0
    };

    const incomeByType = reportData?.incomeByType || [];
    const expenseByCategory = reportData?.expenseByCategory || [];

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Breadcrumb & Title */}
                    <div className="mb-6">
                        <Link
                            href="/dashboard/keuangan"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 mb-2"
                        >
                            <ArrowLeft className="w-4 h-4" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                            <div>
                                <h1 className="text-xl lg:text-2xl font-bold text-gray-800 flex items-center gap-3">
                                    <FileText className="w-6 lg:w-7 h-6 lg:h-7 text-emerald-600" />
                                    Laporan Keuangan
                                </h1>
                                <p className="text-gray-500 text-sm lg:text-base">
                                    Ringkasan dan export laporan keuangan
                                </p>
                            </div>
                            <div className="flex flex-wrap gap-2">
                                <button
                                    onClick={handleExport}
                                    className="flex items-center gap-2 px-3 lg:px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-sm font-medium rounded-xl transition-colors"
                                >
                                    <FileSpreadsheet className="w-4 h-4" />
                                    <span className="hidden sm:inline">Export</span> CSV
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Date Filter */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 mb-6">
                        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3">
                            <div className="flex items-center gap-2 text-gray-600">
                                <Calendar className="w-5 h-5" />
                                <span className="font-medium text-sm">Periode:</span>
                            </div>
                            <div className="flex flex-wrap items-center gap-2 w-full sm:w-auto">
                                <input
                                    type="date"
                                    value={startDate}
                                    onChange={(e) => setStartDate(e.target.value)}
                                    className="flex-1 sm:flex-none px-3 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 text-sm"
                                />
                                <span className="text-gray-400 text-sm">s/d</span>
                                <input
                                    type="date"
                                    value={endDate}
                                    onChange={(e) => setEndDate(e.target.value)}
                                    className="flex-1 sm:flex-none px-3 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 text-sm"
                                />
                                <button
                                    onClick={fetchReport}
                                    className="px-4 py-2 bg-gray-800 hover:bg-gray-900 text-white text-sm font-medium rounded-xl transition-all active:scale-95"
                                >
                                    Filter
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Summary Cards */}
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 lg:gap-6 mb-6">
                        {/* Total Terbayar */}
                        <div className="bg-gradient-to-br from-emerald-500 to-emerald-600 rounded-xl lg:rounded-2xl p-4 lg:p-6 text-white">
                            <div className="flex items-center gap-2 lg:gap-3 mb-2 lg:mb-4">
                                <div className="w-8 lg:w-12 h-8 lg:h-12 bg-white/20 rounded-lg lg:rounded-xl flex items-center justify-center">
                                    <TrendingUp className="w-4 lg:w-6 h-4 lg:h-6" />
                                </div>
                                <div>
                                    <p className="text-emerald-100 text-xs lg:text-sm">Total Terbayar</p>
                                    <p className="text-lg lg:text-2xl font-bold">{formatCurrency(summary.totalPaid)}</p>
                                </div>
                            </div>
                            <div className="text-xs lg:text-sm text-emerald-100">
                                {invoiceCount.paid} tagihan lunas
                            </div>
                        </div>

                        {/* Total Pengeluaran */}
                        <div className="bg-gradient-to-br from-red-500 to-rose-600 rounded-xl lg:rounded-2xl p-4 lg:p-6 text-white">
                            <div className="flex items-center gap-2 lg:gap-3 mb-2 lg:mb-4">
                                <div className="w-8 lg:w-12 h-8 lg:h-12 bg-white/20 rounded-lg lg:rounded-xl flex items-center justify-center">
                                    <TrendingDown className="w-4 lg:w-6 h-4 lg:h-6" />
                                </div>
                                <div>
                                    <p className="text-red-100 text-xs lg:text-sm">Total Pengeluaran</p>
                                    <p className="text-lg lg:text-2xl font-bold">{formatCurrency(summary.totalExpense)}</p>
                                </div>
                            </div>
                            <div className="text-xs lg:text-sm text-red-100">
                                {expenseByCategory.length} kategori
                            </div>
                        </div>

                        {/* Laba Bersih */}
                        <div className="bg-gradient-to-br from-violet-500 to-purple-600 rounded-xl lg:rounded-2xl p-4 lg:p-6 text-white">
                            <div className="flex items-center gap-2 lg:gap-3 mb-2 lg:mb-4">
                                <div className="w-8 lg:w-12 h-8 lg:h-12 bg-white/20 rounded-lg lg:rounded-xl flex items-center justify-center">
                                    <Wallet className="w-4 lg:w-6 h-4 lg:h-6" />
                                </div>
                                <div>
                                    <p className="text-violet-100 text-xs lg:text-sm">Laba Bersih</p>
                                    <p className="text-lg lg:text-2xl font-bold">{formatCurrency(summary.netIncome)}</p>
                                </div>
                            </div>
                            <div className="text-xs lg:text-sm text-violet-100">
                                Margin {summary.collectionRate}%
                            </div>
                        </div>

                        {/* Tunggakan */}
                        <div className="bg-gradient-to-br from-amber-500 to-orange-600 rounded-xl lg:rounded-2xl p-4 lg:p-6 text-white">
                            <div className="flex items-center gap-2 lg:gap-3 mb-2 lg:mb-4">
                                <div className="w-8 lg:w-12 h-8 lg:h-12 bg-white/20 rounded-lg lg:rounded-xl flex items-center justify-center">
                                    <AlertCircle className="w-4 lg:w-6 h-4 lg:h-6" />
                                </div>
                                <div>
                                    <p className="text-amber-100 text-xs lg:text-sm">Tunggakan</p>
                                    <p className="text-lg lg:text-2xl font-bold">{formatCurrency(summary.totalUnpaid)}</p>
                                </div>
                            </div>
                            <div className="text-xs lg:text-sm text-amber-100">
                                {invoiceCount.pending + invoiceCount.partial} tagihan
                            </div>
                        </div>
                    </div>

                    {/* Breakdown Cards */}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
                        {/* Income Breakdown */}
                        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 lg:p-6">
                            <h3 className="font-semibold text-gray-800 mb-4 flex items-center gap-2">
                                <TrendingUp className="w-5 h-5 text-emerald-600" />
                                Pemasukan per Jenis
                            </h3>
                            {incomeByType.length > 0 ? (
                                <div className="space-y-3">
                                    {incomeByType.map((item: any, idx: number) => (
                                        <div key={idx} className="flex items-center justify-between p-3 bg-gray-50 rounded-xl">
                                            <span className="text-gray-700 text-sm font-medium">{item.type || 'Lainnya'}</span>
                                            <span className="text-emerald-600 font-semibold">{formatCurrency(item.amount)}</span>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <p className="text-gray-400 italic text-center py-8">Tidak ada data pemasukan</p>
                            )}
                        </div>

                        {/* Expense Breakdown */}
                        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 lg:p-6">
                            <h3 className="font-semibold text-gray-800 mb-4 flex items-center gap-2">
                                <TrendingDown className="w-5 h-5 text-red-600" />
                                Pengeluaran per Kategori
                            </h3>
                            {expenseByCategory.length > 0 ? (
                                <div className="space-y-3">
                                    {expenseByCategory.map((item: any, idx: number) => (
                                        <div key={idx} className="flex items-center justify-between p-3 bg-gray-50 rounded-xl">
                                            <span className="text-gray-700 text-sm font-medium capitalize">{item.category || 'Lainnya'}</span>
                                            <span className="text-red-600 font-semibold">{formatCurrency(item.amount)}</span>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <p className="text-gray-400 italic text-center py-8">Tidak ada data pengeluaran</p>
                            )}
                        </div>
                    </div>

                    {/* Invoice Statistics */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 lg:p-6">
                        <h3 className="font-semibold text-gray-800 mb-4 flex items-center gap-2">
                            <PieChart className="w-5 h-5 text-blue-600" />
                            Statistik Tagihan
                        </h3>
                        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                            <div className="text-center p-4 bg-blue-50 rounded-xl">
                                <p className="text-2xl lg:text-3xl font-bold text-blue-600">{invoiceCount.total}</p>
                                <p className="text-sm text-gray-500">Total Tagihan</p>
                            </div>
                            <div className="text-center p-4 bg-emerald-50 rounded-xl">
                                <p className="text-2xl lg:text-3xl font-bold text-emerald-600">{invoiceCount.paid}</p>
                                <p className="text-sm text-gray-500">Lunas</p>
                            </div>
                            <div className="text-center p-4 bg-amber-50 rounded-xl">
                                <p className="text-2xl lg:text-3xl font-bold text-amber-600">{invoiceCount.partial}</p>
                                <p className="text-sm text-gray-500">Cicilan</p>
                            </div>
                            <div className="text-center p-4 bg-red-600 rounded-xl shadow-lg shadow-red-500/20">
                                <p className="text-2xl lg:text-3xl font-bold text-white">{invoiceCount.pending}</p>
                                <p className="text-sm text-red-100">Belum Bayar</p>
                            </div>
                        </div>

                        {/* Collection Rate Progress */}
                        <div className="mt-6">
                            <div className="flex justify-between items-center mb-2">
                                <span className="text-sm text-gray-600">Tingkat Koleksi Pembayaran</span>
                                <span className="text-sm font-semibold text-emerald-600">{summary.collectionRate}%</span>
                            </div>
                            <div className="w-full bg-gray-200 rounded-full h-3">
                                <div
                                    className="bg-gradient-to-r from-emerald-500 to-emerald-600 h-3 rounded-full transition-all duration-500"
                                    style={{ width: `${Math.min(summary.collectionRate, 100)}%` }}
                                ></div>
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import {
    ChartCard,
    CashflowChart,
    InvoiceStatusChart,
    DailyIncomeChart,
    PaymentMethodChart
} from '@/components/charts';
import {
    Wallet,
    Receipt,
    TrendingDown,
    DollarSign,
    PiggyBank,
    ArrowUpRight,
    Plus,
    Send,
    CheckCircle2,
    AlertCircle,
    X,
    Loader2
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';

// ============================================
// Types
// ============================================

interface Transaction {
    id: string;
    studentName: string;
    type: string;
    amount: number;
    date: string;
    status: 'success' | 'pending';
}

interface UnpaidStudent {
    id: string;
    name: string;
    class: string;
    type: string;
    amount: number;
    dueDate: string;
    parentPhone: string;
}

import { financeService, FinanceStats } from '@/lib/services/finance';
import { studentsService } from '@/lib/services/students';
import { classesService } from '@/lib/services/classes';

// ============================================
// Mock Data (kept for now as it's used in form and not fetched)
// ============================================

const INVOICE_TYPES = [
    { id: 'spp', name: 'SPP Bulanan', amount: 500000 },
    { id: 'gedung', name: 'Uang Gedung', amount: 2000000 },
    { id: 'makan', name: 'Uang Makan', amount: 300000 },
    { id: 'kitab', name: 'Uang Kitab', amount: 250000 },
    { id: 'seragam', name: 'Seragam', amount: 750000 },
];


export default function KeuanganDashboard() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [showInvoiceModal, setShowInvoiceModal] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [isLoading, setIsLoading] = useState(true);

    // Real Data State
    const [stats, setStats] = useState<FinanceStats>({
        incomeThisMonth: 0,
        expenseThisMonth: 0,
        unpaidCount: 0,
        balance: 0,
        paidCount: 0,
        partialCount: 0
    });
    const [transactions, setTransactions] = useState<Transaction[]>([]);
    const [unpaidStudents, setUnpaidStudents] = useState<UnpaidStudent[]>([]);
    const [cashflowData, setCashflowData] = useState<any[]>([]);
    const [invoiceStatusData, setInvoiceStatusData] = useState<any[]>([]);
    const [dailyIncomeData, setDailyIncomeData] = useState<any[]>([]);
    const [paymentMethodData, setPaymentMethodData] = useState<any[]>([]);
    const [classes, setClasses] = useState<any[]>([]);
    const [invoiceTypes, setInvoiceTypes] = useState<any[]>([]);

    // Invoice form state
    const [invoiceForm, setInvoiceForm] = useState({
        targetType: 'class', // 'class' or 'individual'
        class: '',
        studentId: '',
        invoiceType: '',
        amount: 0,
        dueDate: '',
        notes: '',
    });

    // Reminder state
    const [sendingReminder, setSendingReminder] = useState<string | null>(null);
    const [reminderSent, setReminderSent] = useState<string[]>([]);

    const [students, setStudents] = useState<any[]>([]);

    const fetchData = useCallback(async () => {
        try {
            const [
                fStats,
                recentTx,
                unpaid,
                cashflow,
                statusDist,
                methodDist,
                dailyInc,
                allClasses,
                allStudents,
                allTypes
            ] = await Promise.all([
                financeService.getStats(),
                financeService.getRecentTransactions(),
                financeService.getUnpaidInvoices(),
                financeService.getCashflow(),
                financeService.getInvoiceStatusDistribution(),
                financeService.getPaymentMethodDistribution(),
                financeService.getDailyIncome(30),
                classesService.getAll(),
                studentsService.getAll(),
                financeService.getInvoiceTypes()
            ]);

            setStats(fStats);
            setTransactions(recentTx);
            setUnpaidStudents(unpaid);
            setCashflowData(cashflow);
            setInvoiceStatusData(statusDist);
            setPaymentMethodData(methodDist);
            setDailyIncomeData(dailyInc);
            setClasses(allClasses);
            setStudents(allStudents);
            setInvoiceTypes(allTypes);

            setIsLoading(false);
        } catch (err) {
            console.error('Error fetching finance data:', err);
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_keuangan' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router, fetchData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleSendReminder = async (studentId: string) => {
        setSendingReminder(studentId);
        // In a real app, this would trigger a WhatsApp/Email API
        await new Promise(r => setTimeout(r, 1000));
        setSendingReminder(null);
        setReminderSent([...reminderSent, studentId]);
        alert('Pengingat telah dikirim ke Wali Santri via WhatsApp (Simulasi).');
    };

    const handleCreateInvoice = async () => {
        if (invoiceForm.targetType === 'class' && !invoiceForm.class) {
            alert('Harap pilih kelas!');
            return;
        }
        if (invoiceForm.targetType === 'individual' && !invoiceForm.studentId) {
            alert('Harap pilih santri!');
            return;
        }
        if (!invoiceForm.invoiceType || !invoiceForm.amount || !invoiceForm.dueDate) {
            alert('Harap isi semua kolom yang wajib.');
            return;
        }

        try {
            setIsLoading(true);
            await financeService.createInvoice({
                targetType: invoiceForm.targetType,
                studentId: invoiceForm.studentId,
                classId: invoiceForm.class,
                invoiceType: invoiceForm.invoiceType,
                amount: invoiceForm.amount,
                dueDate: invoiceForm.dueDate,
                notes: invoiceForm.notes
            });

            alert('Invoice berhasil dibuat!');
            setShowInvoiceModal(false);
            setInvoiceForm({
                targetType: 'class',
                class: '',
                studentId: '',
                invoiceType: '',
                amount: 0,
                dueDate: '',
                notes: '',
            });
            fetchData();
        } catch (err: any) {
            console.error('Error creating invoice:', err);
            alert('Gagal membuat invoice: ' + err.message);
        } finally {
            setIsLoading(false);
        }
    };

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-emerald-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
                    <span>Loading Finansial...</span>
                </div>
            </div>
        );
    }

    // Format currency
    const formatCurrency = (amount: number) => {
        if (amount === undefined || amount === null || isNaN(amount)) return 'Rp 0';
        return new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(amount);
    };


    return (
        <div className="min-h-screen bg-gray-50">
            {/* Invoice Modal */}
            {showInvoiceModal && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl max-h-[90vh] overflow-y-auto">
                        <div className="p-6 border-b border-gray-100 flex items-center justify-between sticky top-0 bg-white">
                            <div>
                                <h3 className="text-lg font-bold text-gray-800">Buat Tagihan Baru</h3>
                                <p className="text-sm text-gray-500">Buat tagihan SPP atau biaya lainnya</p>
                            </div>
                            <button onClick={() => setShowInvoiceModal(false)} className="p-2 hover:bg-gray-100 rounded-lg">
                                <X className="w-5 h-5 text-gray-400" />
                            </button>
                        </div>
                        <div className="p-6 space-y-5">
                            {/* Target Type */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Target Tagihan</label>
                                <select
                                    value={invoiceForm.targetType}
                                    onChange={(e) => setInvoiceForm({ ...invoiceForm, targetType: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                >
                                    <option value="all">Semua Santri</option>
                                    <option value="class">Per Kelas</option>
                                    <option value="individual">Per Santri</option>
                                </select>
                            </div>

                            {/* Class Selection */}
                            {invoiceForm.targetType === 'class' && (
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Pilih Kelas</label>
                                    <select
                                        value={invoiceForm.class}
                                        onChange={(e) => setInvoiceForm({ ...invoiceForm, class: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                    >
                                        <option value="">Pilih Kelas</option>
                                        {classes.map(c => (
                                            <option key={c.id} value={c.id}>{c.name}</option>
                                        ))}
                                    </select>
                                </div>
                            )}

                            {/* Student Selection */}
                            {invoiceForm.targetType === 'individual' && (
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Pilih Santri</label>
                                    <select
                                        value={invoiceForm.studentId}
                                        onChange={(e) => setInvoiceForm({ ...invoiceForm, studentId: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                    >
                                        <option value="">Pilih Santri</option>
                                        {students.map(s => (
                                            <option key={s.id} value={s.id}>{s.name} ({s.nis})</option>
                                        ))}
                                    </select>
                                </div>
                            )}

                            {/* Invoice Type */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Jenis Tagihan</label>
                                <select
                                    value={invoiceForm.invoiceType}
                                    onChange={(e) => {
                                        const type = INVOICE_TYPES.find(t => t.id === e.target.value);
                                        setInvoiceForm({
                                            ...invoiceForm,
                                            invoiceType: e.target.value,
                                            amount: type?.amount || 0
                                        });
                                    }}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500"
                                >
                                    <option value="">-- Pilih Jenis --</option>
                                    {invoiceTypes.length > 0 ? (
                                        invoiceTypes.map(type => (
                                            <option key={type.id} value={type.name}>{type.name} - {formatCurrency(type.amount)}</option>
                                        ))
                                    ) : (
                                        INVOICE_TYPES.map(type => (
                                            <option key={type.id} value={type.name}>{type.name} - {formatCurrency(type.amount)}</option>
                                        ))
                                    )}
                                </select>
                            </div>

                            {/* Amount */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Nominal</label>
                                <div className="relative">
                                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500">Rp</span>
                                    <input
                                        type="number"
                                        value={invoiceForm.amount}
                                        onChange={(e) => setInvoiceForm({ ...invoiceForm, amount: parseInt(e.target.value) || 0 })}
                                        className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500"
                                    />
                                </div>
                            </div>

                            {/* Due Date */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Jatuh Tempo</label>
                                <input
                                    type="date"
                                    value={invoiceForm.dueDate}
                                    onChange={(e) => setInvoiceForm({ ...invoiceForm, dueDate: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500"
                                />
                            </div>

                            {/* Notes */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Catatan (Opsional)</label>
                                <textarea
                                    rows={2}
                                    value={invoiceForm.notes}
                                    onChange={(e) => setInvoiceForm({ ...invoiceForm, notes: e.target.value })}
                                    placeholder="Catatan tambahan..."
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500 resize-none"
                                />
                            </div>
                        </div>
                        <div className="p-6 border-t border-gray-100 flex gap-3">
                            <button
                                onClick={() => setShowInvoiceModal(false)}
                                className="flex-1 py-3 border border-gray-200 text-gray-700 font-medium rounded-xl hover:bg-gray-50 transition-colors"
                            >
                                Batal
                            </button>
                            <button
                                onClick={handleCreateInvoice}
                                className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-medium rounded-xl transition-colors flex items-center justify-center gap-2"
                            >
                                <Receipt className="w-5 h-5" />
                                Buat Tagihan
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Welcome Banner with Action */}
                    <div className="bg-gradient-to-r from-emerald-500 to-teal-600 rounded-2xl p-6 lg:p-8 text-white mb-8">
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <div className="flex items-center gap-3 mb-2">
                                    <Wallet className="w-8 h-8" />
                                    <h2 className="text-2xl font-bold">Portal Keuangan</h2>
                                </div>
                                <p className="text-emerald-100">
                                    Kelola SPP, pembayaran, dan laporan keuangan pesantren.
                                </p>
                            </div>
                            <button
                                onClick={() => setShowInvoiceModal(true)}
                                className="flex items-center gap-2 px-5 py-3 bg-white/20 hover:bg-white/30 rounded-xl font-medium transition-colors"
                            >
                                <Plus className="w-5 h-5" />
                                Buat Tagihan Baru
                            </button>
                        </div>
                    </div>

                    {/* Financial Summary Cards */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                        <div className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm">
                            <div className="flex items-center justify-between mb-4">
                                <div className="w-12 h-12 bg-emerald-100 rounded-xl flex items-center justify-center">
                                    <DollarSign className="w-6 h-6 text-emerald-600" />
                                </div>
                                <span className="flex items-center gap-1 text-sm text-emerald-600 font-medium">
                                    <ArrowUpRight className="w-4 h-4" /> Real-time
                                </span>
                            </div>
                            <p className="text-2xl font-bold text-gray-800">{formatCurrency(stats.incomeThisMonth)}</p>
                            <p className="text-sm text-gray-500">Pemasukan Bulan Ini</p>
                        </div>

                        <div className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm">
                            <div className="flex items-center justify-between mb-4">
                                <div className="w-12 h-12 bg-red-100 rounded-xl flex items-center justify-center">
                                    <TrendingDown className="w-6 h-6 text-red-600" />
                                </div>
                            </div>
                            <p className="text-2xl font-bold text-gray-800">{formatCurrency(stats.expenseThisMonth)}</p>
                            <p className="text-sm text-gray-500">Pengeluran Terverifikasi</p>
                        </div>

                        <div className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm">
                            <div className="flex items-center justify-between mb-4">
                                <div className="w-12 h-12 bg-amber-100 rounded-xl flex items-center justify-center">
                                    <Receipt className="w-6 h-6 text-amber-600" />
                                </div>
                            </div>
                            <p className="text-2xl font-bold text-gray-800">{stats.unpaidCount}</p>
                            <p className="text-sm text-gray-500">Tagihan Belum Lunas</p>
                        </div>

                        <div className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm">
                            <div className="flex items-center justify-between mb-4">
                                <div className="w-12 h-12 bg-blue-100 rounded-xl flex items-center justify-center">
                                    <PiggyBank className="w-6 h-6 text-blue-600" />
                                </div>
                            </div>
                            <p className="text-2xl font-bold text-gray-800">{formatCurrency(stats.balance)}</p>
                            <p className="text-sm text-gray-500">Estimasi Saldo Kas</p>
                        </div>
                    </div>

                    {/* Data Visualization Charts */}
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
                        <ChartCard
                            title="Arus Kas (Cashflow)"
                            subtitle="Pemasukan vs Pengeluaran"
                            className="lg:col-span-2"
                        >
                            <CashflowChart data={cashflowData} height={300} />
                        </ChartCard>

                        <ChartCard
                            title="Status Tagihan"
                            subtitle="Perbandingan lunas & belum bayar"
                        >
                            <InvoiceStatusChart data={invoiceStatusData} height={260} />
                            <div className="flex justify-center gap-6 mt-2">
                                {invoiceStatusData.map((d, i) => (
                                    <div key={i} className="flex items-center gap-2">
                                        <div className="w-3 h-3 rounded-full" style={{ backgroundColor: d.color }} />
                                        <span className="text-sm text-gray-600">{d.name} ({d.value})</span>
                                    </div>
                                ))}
                            </div>
                        </ChartCard>
                    </div>

                    {/* Second Row of Charts */}
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
                        <ChartCard
                            title="Trend Pemasukan Harian"
                            subtitle="30 hari terakhir"
                            className="lg:col-span-2"
                        >
                            <DailyIncomeChart data={dailyIncomeData} height={280} />
                        </ChartCard>

                        <ChartCard
                            title="Metode Pembayaran"
                            subtitle="Distribusi metode pembayaran"
                        >
                            <PaymentMethodChart data={paymentMethodData} height={280} />
                        </ChartCard>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                        {/* Recent Transactions */}
                        <div className="lg:col-span-2 bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                            <div className="p-5 border-b border-gray-100 flex items-center justify-between">
                                <h3 className="font-semibold text-gray-800">Transaksi Terbaru</h3>
                                <Link
                                    href="/dashboard/keuangan/pembayaran"
                                    className="text-sm text-emerald-600 font-medium hover:underline"
                                >
                                    Lihat Semua
                                </Link>
                            </div>
                            <div className="overflow-x-auto">
                                <table className="w-full">
                                    <thead className="bg-gray-50 border-b border-gray-100">
                                        <tr>
                                            <th className="text-left p-4 text-sm font-semibold text-gray-600">Santri</th>
                                            <th className="text-left p-4 text-sm font-semibold text-gray-600">Jenis</th>
                                            <th className="text-right p-4 text-sm font-semibold text-gray-600">Nominal</th>
                                            <th className="text-center p-4 text-sm font-semibold text-gray-600">Status</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-gray-100">
                                        {transactions.map(tx => (
                                            <tr key={tx.id} className="hover:bg-gray-50">
                                                <td className="p-4">
                                                    <div className="flex items-center gap-3">
                                                        <div className="w-8 h-8 bg-emerald-50 rounded-full flex items-center justify-center">
                                                            <span className="text-sm font-medium text-emerald-600">{tx.studentName.charAt(0)}</span>
                                                        </div>
                                                        <div>
                                                            <p className="font-medium text-gray-800">{tx.studentName}</p>
                                                            <p className="text-xs text-gray-500">{new Date(tx.date).toLocaleDateString('id-ID')}</p>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td className="p-4 text-gray-600 uppercase text-xs font-bold tracking-wider">{tx.type}</td>
                                                <td className="p-4 text-right font-semibold text-gray-800">{formatCurrency(tx.amount)}</td>
                                                <td className="p-4 text-center">
                                                    <span className={`px-3 py-1 rounded-full text-xs font-medium ${tx.status === 'success'
                                                        ? 'bg-emerald-100 text-emerald-700'
                                                        : 'bg-amber-100 text-amber-700'
                                                        }`}>
                                                        {tx.status === 'success' ? 'Lunas' : 'Pending'}
                                                    </span>
                                                </td>
                                            </tr>
                                        ))}
                                        {transactions.length === 0 && (
                                            <tr>
                                                <td colSpan={4} className="p-8 text-center text-gray-400">Belum ada transaksi</td>
                                            </tr>
                                        )}
                                    </tbody>
                                </table>
                            </div>
                        </div>

                        {/* Unpaid Students */}
                        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                            <div className="p-5 border-b border-gray-100 flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                    <AlertCircle className="w-5 h-5 text-red-500" />
                                    <h3 className="font-semibold text-gray-800">Belum Bayar</h3>
                                </div>
                                <span className="px-2 py-1 bg-red-100 text-red-700 text-xs font-medium rounded-full">
                                    {unpaidStudents.length}
                                </span>
                            </div>
                            <div className="divide-y divide-gray-100 max-h-[400px] overflow-y-auto">
                                {unpaidStudents.map(student => (
                                    <div key={student.id} className="p-4">
                                        <div className="flex items-start justify-between mb-2 gap-4">
                                            <div className="min-w-0 flex-1">
                                                <p className="font-medium text-gray-800 truncate">{student.name}</p>
                                                <p className="text-sm text-gray-500">Kelas {student.class} • {student.type}</p>
                                            </div>
                                            <p className="font-semibold text-gray-800 whitespace-nowrap">{formatCurrency(student.amount)}</p>
                                        </div>
                                        <div className="flex items-center justify-between">
                                            <span className="text-xs text-red-600">Jatuh tempo: {new Date(student.dueDate).toLocaleDateString('id-ID')}</span>
                                            <button
                                                onClick={() => handleSendReminder(student.id)}
                                                disabled={sendingReminder === student.id || reminderSent.includes(student.id)}
                                                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${reminderSent.includes(student.id)
                                                    ? 'bg-emerald-100 text-emerald-700'
                                                    : 'bg-amber-100 hover:bg-amber-200 text-amber-700'
                                                    }`}
                                            >
                                                {sendingReminder === student.id ? (
                                                    <>
                                                        <Loader2 className="w-4 h-4 animate-spin" />
                                                        Mengirim...
                                                    </>
                                                ) : reminderSent.includes(student.id) ? (
                                                    <>
                                                        <CheckCircle2 className="w-4 h-4" />
                                                        Terkirim
                                                    </>
                                                ) : (
                                                    <>
                                                        <Send className="w-4 h-4" />
                                                        Ingatkan
                                                    </>
                                                )}
                                            </button>
                                        </div>
                                    </div>
                                ))}
                                {unpaidStudents.length === 0 && (
                                    <div className="p-8 text-center text-gray-400 italic text-sm">Semua tagihan lunas!</div>
                                )}
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { supabase } from '@/lib/supabase';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    CreditCard,
    Search,
    CheckCircle2,
    Loader2,
    Wallet,
    Building2,
    Smartphone,
    Clock,
    User as UserIcon,
    X
} from 'lucide-react';

import { financeService } from '@/lib/services/finance';

export default function PembayaranPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isProcessing, setIsProcessing] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [showSuccess, setShowSuccess] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterStatus, setFilterStatus] = useState<'all' | 'belum' | 'cicilan'>('all');

    // All unpaid invoices list
    const [invoices, setInvoices] = useState<any[]>([]);
    const [recentPayments, setRecentPayments] = useState<any[]>([]);

    // Payment Modal
    const [showPaymentModal, setShowPaymentModal] = useState(false);
    const [selectedInvoice, setSelectedInvoice] = useState<any>(null);
    const [paymentAmount, setPaymentAmount] = useState(0);
    const [paidSoFar, setPaidSoFar] = useState(0);
    const [paymentMethod, setPaymentMethod] = useState('tunai');
    const [paymentNotes, setPaymentNotes] = useState('');

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_keuangan' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router]);

    const fetchData = async () => {
        try {
            setIsLoading(true);
            const [allInvoices, payments] = await Promise.all([
                financeService.getAllInvoices(),
                financeService.getRecentPayments(10)
            ]);
            // Filter only unpaid invoices
            setInvoices(allInvoices.filter((i: any) => i.status !== 'lunas'));
            setRecentPayments(payments);
        } catch (error) {
            console.error('Error fetching data:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const openPaymentModal = async (invoice: any) => {
        setSelectedInvoice(invoice);
        // Fetch existing payments for this invoice
        const { data: payments } = await supabase
            .from('payments')
            .select('amount')
            .eq('invoice_id', invoice.id);
        const totalPaid = (payments || []).reduce((sum: number, p: any) => sum + Number(p.amount), 0);
        setPaidSoFar(totalPaid);
        setPaymentAmount(invoice.amount - totalPaid);
        setShowPaymentModal(true);
    };

    const handleProcessPayment = async () => {
        if (!selectedInvoice || paymentAmount <= 0) return alert('Masukkan nominal pembayaran!');
        try {
            setIsProcessing(true);
            await financeService.processPayment({
                invoice_id: selectedInvoice.id,
                amount: paymentAmount,
                payment_method: paymentMethod,
                notes: paymentNotes
            });
            setShowPaymentModal(false);
            setSelectedInvoice(null);
            setPaymentAmount(0);
            setPaidSoFar(0);
            setPaymentNotes('');
            setIsProcessing(false);
            setShowSuccess(true);
            fetchData();
            setTimeout(() => setShowSuccess(false), 3000);
        } catch (error) {
            console.error('Error processing payment:', error);
            setIsProcessing(false);
            alert('Gagal memproses pembayaran');
        }
    };

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            minimumFractionDigits: 0
        }).format(amount);
    };

    // Filter invoices
    const filteredInvoices = invoices.filter(inv => {
        const matchSearch = inv.santriName?.toLowerCase().includes(searchQuery.toLowerCase()) ||
            inv.id?.toLowerCase().includes(searchQuery.toLowerCase());
        const matchStatus = filterStatus === 'all' || inv.status === filterStatus;
        return matchSearch && matchStatus;
    });

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-emerald-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
                    <span>Loading Data Pembayaran...</span>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Success Toast */}
            {showSuccess && (
                <div className="fixed top-4 right-4 z-[60] bg-emerald-500 text-white px-6 py-4 rounded-xl shadow-lg flex items-center gap-3">
                    <CheckCircle2 className="w-6 h-6" />
                    <span className="font-medium">Pembayaran berhasil diproses!</span>
                </div>
            )}

            {/* Payment Modal dengan Cicilan */}
            {showPaymentModal && selectedInvoice && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[70] flex items-center justify-center p-4 transition-all duration-300">
                    <div className="bg-white dark:bg-neutral-900 rounded-3xl w-full max-w-md shadow-2xl border border-gray-100 dark:border-white/10 max-h-[90vh] flex flex-col transition-all scale-100">
                        <div className="p-6 border-b border-gray-100 dark:border-white/5 flex items-center justify-between shrink-0">
                            <div>
                                <h3 className="text-xl font-bold text-gray-800 dark:text-white">Proses Pembayaran</h3>
                                <p className="text-gray-500 dark:text-gray-400 text-sm mt-1">{selectedInvoice.santriName}</p>
                            </div>
                            <button onClick={() => setShowPaymentModal(false)} className="p-2 hover:bg-gray-100 dark:hover:bg-white/5 rounded-lg transition-colors">
                                <X className="w-5 h-5 text-gray-400" />
                            </button>
                        </div>
                        <div className="p-6 space-y-4 overflow-y-auto flex-1">
                            {/* Info Tagihan */}
                            <div className="bg-gray-50 dark:bg-black/20 rounded-xl p-4 space-y-2 border border-gray-100 dark:border-white/5">
                                <div className="flex justify-between text-sm">
                                    <span className="text-gray-500 dark:text-gray-400">Total Tagihan</span>
                                    <span className="font-semibold text-gray-800 dark:text-gray-200">{formatCurrency(selectedInvoice.amount)}</span>
                                </div>
                                <div className="flex justify-between text-sm">
                                    <span className="text-gray-500 dark:text-gray-400">Sudah Dibayar</span>
                                    <span className="font-semibold text-amber-600 dark:text-amber-500">{formatCurrency(paidSoFar)}</span>
                                </div>
                                <hr className="border-gray-200 dark:border-white/5" />
                                <div className="flex justify-between text-sm">
                                    <span className="text-gray-500 dark:text-gray-400">Sisa Tagihan</span>
                                    <span className="font-bold text-red-600 dark:text-red-500">{formatCurrency(selectedInvoice.amount - paidSoFar)}</span>
                                </div>
                            </div>

                            {/* Input Nominal Pembayaran */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Nominal Pembayaran</label>
                                <input
                                    type="number"
                                    value={paymentAmount}
                                    onChange={(e) => setPaymentAmount(parseInt(e.target.value) || 0)}
                                    placeholder="Masukkan nominal"
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all"
                                />
                                <div className="flex gap-2 mt-2">
                                    <button
                                        onClick={() => setPaymentAmount(selectedInvoice.amount - paidSoFar)}
                                        className="text-xs px-3 py-1 bg-emerald-100 dark:bg-emerald-500/10 text-emerald-700 dark:text-emerald-500 rounded-lg hover:bg-emerald-200 dark:hover:bg-emerald-500/20 transition-colors"
                                    >
                                        Bayar Lunas
                                    </button>
                                    <button
                                        onClick={() => setPaymentAmount(Math.floor((selectedInvoice.amount - paidSoFar) / 2))}
                                        className="text-xs px-3 py-1 bg-amber-100 dark:bg-amber-500/10 text-amber-700 dark:text-amber-500 rounded-lg hover:bg-amber-200 dark:hover:bg-amber-500/20 transition-colors"
                                    >
                                        Setengah
                                    </button>
                                </div>
                            </div>

                            {/* Payment Method */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Metode Pembayaran</label>
                                <div className="grid grid-cols-3 gap-2">
                                    {[
                                        { id: 'tunai', label: 'Tunai', icon: Wallet },
                                        { id: 'transfer', label: 'Transfer', icon: Building2 },
                                        { id: 'qris', label: 'QRIS', icon: Smartphone },
                                    ].map(method => (
                                        <button
                                            key={method.id}
                                            onClick={() => setPaymentMethod(method.id)}
                                            className={`p-3 border rounded-xl flex flex-col items-center gap-1 transition-all ${paymentMethod === method.id
                                                ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-500/10 text-emerald-700 dark:text-emerald-500'
                                                : 'border-gray-200 dark:border-white/10 bg-white dark:bg-neutral-800 text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-white/5'
                                                }`}
                                        >
                                            <method.icon className="w-5 h-5" />
                                            <span className="text-xs font-medium">{method.label}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Notes */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Catatan (Opsional)</label>
                                <input
                                    type="text"
                                    value={paymentNotes}
                                    onChange={(e) => setPaymentNotes(e.target.value)}
                                    placeholder="Catatan pembayaran..."
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all"
                                />
                            </div>

                            {paymentAmount > 0 && (
                                <div className="text-sm text-center p-3 rounded-lg bg-blue-50 dark:bg-blue-500/10 text-blue-700 dark:text-blue-400 border border-blue-100 dark:border-blue-500/20">
                                    {paymentAmount >= (selectedInvoice.amount - paidSoFar)
                                        ? '✅ Tagihan akan LUNAS'
                                        : `⏳ Sisa setelah bayar: ${formatCurrency(selectedInvoice.amount - paidSoFar - paymentAmount)}`
                                    }
                                </div>
                            )}
                        </div>
                        <div className="p-6 border-t border-gray-100 dark:border-white/5 flex gap-3 flex-shrink-0 bg-gray-50 dark:bg-neutral-900/50">
                            <button
                                onClick={() => { setShowPaymentModal(false); setPaymentAmount(0); setPaidSoFar(0); }}
                                className="flex-1 py-3 border border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-300 font-medium rounded-xl hover:bg-gray-100 dark:hover:bg-white/5 transition-all"
                            >
                                Batal
                            </button>
                            <button
                                onClick={handleProcessPayment}
                                disabled={isProcessing || paymentAmount <= 0}
                                className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl flex items-center justify-center gap-2 disabled:opacity-50 shadow-lg shadow-emerald-500/30 active:scale-95 transition-all"
                            >
                                {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : `Bayar ${formatCurrency(paymentAmount)}`}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Breadcrumb & Title */}
                    <div className="mb-6">
                        <Link
                            href="/dashboard/keuangan"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 mb-2"
                        >
                            <ArrowLeft className="w-4 h-4" />
                            Kembali ke Dashboard
                        </Link>
                        <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-3">
                            <CreditCard className="w-7 h-7 text-emerald-600" />
                            Input Pembayaran
                        </h1>
                        <p className="text-gray-500">
                            Proses pembayaran manual dari wali santri
                        </p>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                        {/* Invoices List */}
                        <div className="lg:col-span-2">
                            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm">
                                {/* Header & Filters */}
                                <div className="p-4 border-b border-gray-100">
                                    <div className="flex flex-col md:flex-row gap-3">
                                        <div className="relative flex-1">
                                            <Search className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                            <input
                                                type="text"
                                                value={searchQuery}
                                                onChange={(e) => setSearchQuery(e.target.value)}
                                                placeholder="Cari nama santri..."
                                                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                            />
                                        </div>
                                        <select
                                            value={filterStatus}
                                            onChange={(e) => setFilterStatus(e.target.value as any)}
                                            className="px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl"
                                        >
                                            <option value="all">Semua</option>
                                            <option value="belum">Belum Bayar</option>
                                            <option value="cicilan">Cicilan</option>
                                        </select>
                                    </div>
                                </div>

                                {/* Scrollable List */}
                                <div className="max-h-[60vh] overflow-y-auto">
                                    {filteredInvoices.length > 0 ? (
                                        <div className="divide-y divide-gray-100">
                                            {filteredInvoices.map(inv => (
                                                <div key={inv.id} className="p-4 hover:bg-gray-50 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                                                    <div className="flex items-center gap-3">
                                                        <div className="w-10 h-10 bg-emerald-100 rounded-full flex items-center justify-center flex-shrink-0">
                                                            <UserIcon className="w-5 h-5 text-emerald-600" />
                                                        </div>
                                                        <div>
                                                            <p className="font-semibold text-gray-800">{inv.santriName}</p>
                                                            <p className="text-xs text-gray-500">{inv.type} • {inv.class}</p>
                                                        </div>
                                                    </div>
                                                    <div className="flex items-center justify-between sm:justify-end gap-4 w-full sm:w-auto">
                                                        <div className="text-right">
                                                            <p className="font-semibold text-gray-800">{formatCurrency(inv.amount)}</p>
                                                            <span className={`text-xs px-2 py-0.5 rounded-full ${inv.status === 'cicilan'
                                                                ? 'bg-amber-100 text-amber-700'
                                                                : 'bg-red-100 text-red-700'
                                                                }`}>
                                                                {inv.status === 'cicilan' ? 'Cicilan' : 'Belum Bayar'}
                                                            </span>
                                                        </div>
                                                        <button
                                                            onClick={() => openPaymentModal(inv)}
                                                            className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-sm font-semibold rounded-lg whitespace-nowrap"
                                                        >
                                                            Bayar
                                                        </button>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    ) : (
                                        <div className="p-12 text-center text-gray-400">
                                            <Clock className="w-12 h-12 mx-auto mb-3 opacity-50" />
                                            <p>Tidak ada tagihan tertunggak</p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>

                        {/* Recent Payments */}
                        <div className="lg:col-span-1">
                            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
                                <h3 className="font-semibold text-gray-800 mb-4 flex items-center gap-2">
                                    <Clock className="w-5 h-5 text-gray-400" />
                                    Transaksi Terakhir
                                </h3>
                                <div className="space-y-3 max-h-[50vh] overflow-y-auto">
                                    {recentPayments.length > 0 ? (
                                        recentPayments.map((payment, idx) => (
                                            <div key={idx} className="p-3 bg-gray-50 rounded-xl">
                                                <div className="flex justify-between items-start">
                                                    <div>
                                                        <p className="font-medium text-gray-800 text-sm">{payment.santriName}</p>
                                                        <p className="text-xs text-gray-500">{payment.timestamp}</p>
                                                    </div>
                                                    <div className="text-right">
                                                        <p className="font-semibold text-emerald-600 text-sm">{formatCurrency(payment.amount)}</p>
                                                        <p className="text-xs text-gray-400 capitalize">{payment.method}</p>
                                                    </div>
                                                </div>
                                            </div>
                                        ))
                                    ) : (
                                        <p className="text-sm text-gray-400 italic text-center py-4">Belum ada transaksi</p>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    TrendingDown,
    Plus,
    Search,
    CheckCircle2,
    Loader2,
    X,
    Download,
    Calendar
} from 'lucide-react';

// ============================================
// Types & Data
// ============================================

interface Expense {
    id: string;
    date: string;
    category: 'Operasional' | 'Gaji' | 'Pembangunan' | 'Pendidikan' | 'Lainnya';
    description: string;
    amount: number;
    pic: string;
}

import { financeService } from '@/lib/services/finance';

// ============================================
// Types & Data
// ============================================

interface Expense {
    id: string;
    date: string;
    category: 'Operasional' | 'Gaji' | 'Pembangunan' | 'Pendidikan' | 'Lainnya';
    description: string;
    amount: number;
    pic: string;
}

const CATEGORIES_MAPPING: Record<string, string> = {
    'gaji': 'Gaji',
    'operasional': 'Operasional',
    'pemeliharaan': 'Pemeliharaan',
    'pengadaan': 'Pengadaan',
    'kegiatan': 'Kegiatan',
    'lainnya': 'Lainnya'
};

const CATEGORIES = Object.keys(CATEGORIES_MAPPING);

export default function PengeluaranPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterCategory, setFilterCategory] = useState<string>('all');
    const [showModal, setShowModal] = useState(false);
    const [isCreating, setIsCreating] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [showSuccess, setShowSuccess] = useState(false);
    const [expenses, setExpenses] = useState<Expense[]>([]);

    // Form state
    const [formData, setFormData] = useState({
        date: new Date().toISOString().split('T')[0],
        category: 'operasional',
        description: '',
        amount: 0,
        pic: '',
    });

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_keuangan' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router]);

    const fetchData = async () => {
        try {
            setIsLoading(true);
            const data = await financeService.getAllExpenses();
            setExpenses(data);
        } catch (error) {
            console.error('Error fetching expenses:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleCreate = async () => {
        try {
            setIsCreating(true);
            await financeService.createExpense({
                category: formData.category,
                description: formData.description,
                amount: formData.amount,
                expense_date: formData.date,
                pic: formData.pic
            });

            setIsCreating(false);
            setShowModal(false);
            setFormData({ date: new Date().toISOString().split('T')[0], category: 'operasional', description: '', amount: 0, pic: '' });
            setShowSuccess(true);
            fetchData();
            setTimeout(() => setShowSuccess(false), 3000);
        } catch (error) {
            console.error('Error creating expense:', error);
            setIsCreating(false);
            alert('Gagal mencatat pengeluaran');
        }
    };

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            minimumFractionDigits: 0
        }).format(amount);
    };

    if (!user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-emerald-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
                    <span>Loading Data Pengeluaran...</span>
                </div>
            </div>
        );
    }

    const filteredExpenses = expenses.filter(exp => {
        const matchSearch = exp.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
            exp.pic.toLowerCase().includes(searchQuery.toLowerCase());
        const matchCategory = filterCategory === 'all' || exp.category === filterCategory;
        return matchSearch && matchCategory;
    });

    const totalExpenses = expenses.reduce((sum, exp) => sum + exp.amount, 0);

    const categoryColors: Record<string, string> = {
        'operasional': 'bg-blue-100 text-blue-700',
        'gaji': 'bg-purple-100 text-purple-700',
        'pemeliharaan': 'bg-amber-100 text-amber-700',
        'pengadaan': 'bg-rose-100 text-rose-700',
        'kegiatan': 'bg-emerald-100 text-emerald-700',
        'lainnya': 'bg-gray-100 text-gray-700',
    };

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Success Toast */}
            {showSuccess && (
                <div className="fixed top-4 right-4 z-[60] bg-emerald-500 text-white px-6 py-4 rounded-xl shadow-lg flex items-center gap-3">
                    <CheckCircle2 className="w-6 h-6" />
                    <span className="font-medium">Pengeluaran berhasil dicatat!</span>
                </div>
            )}

            {/* Create Expense Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-50 flex items-center justify-center p-4 transition-all duration-300">
                    <div className="bg-white dark:bg-neutral-900 rounded-3xl w-full max-w-lg shadow-2xl border border-gray-100 dark:border-white/10 max-h-[90vh] flex flex-col transition-all scale-100">
                        <div className="p-6 border-b border-gray-100 dark:border-white/5 flex items-center justify-between flex-shrink-0">
                            <h3 className="text-xl font-bold text-gray-800 dark:text-white">Catat Pengeluaran</h3>
                            <button onClick={() => setShowModal(false)} className="p-2 hover:bg-gray-100 dark:hover:bg-white/5 rounded-lg transition-colors">
                                <X className="w-5 h-5 text-gray-400" />
                            </button>
                        </div>
                        <div className="p-6 space-y-4 overflow-y-auto flex-1">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Tanggal</label>
                                <input
                                    type="date"
                                    value={formData.date}
                                    onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Kategori</label>
                                <select
                                    value={formData.category}
                                    onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-neutral-800 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all appearance-none"
                                >
                                    {CATEGORIES.map(c => (
                                        <option key={c} value={c}>{CATEGORIES_MAPPING[c]}</option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Deskripsi</label>
                                <textarea
                                    value={formData.description}
                                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                    rows={2}
                                    placeholder="Jelaskan pengeluaran..."
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all min-h-[80px]"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Nominal</label>
                                <input
                                    type="number"
                                    value={formData.amount}
                                    onChange={(e) => setFormData({ ...formData, amount: parseInt(e.target.value) || 0 })}
                                    placeholder="0"
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Penanggung Jawab (PIC)</label>
                                <input
                                    type="text"
                                    value={formData.pic}
                                    onChange={(e) => setFormData({ ...formData, pic: e.target.value })}
                                    placeholder="Nama penanggung jawab"
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all"
                                />
                            </div>
                        </div>
                        <div className="p-6 border-t border-gray-100 dark:border-white/5 flex gap-3 flex-shrink-0 bg-gray-50 dark:bg-neutral-900/50">
                            <button
                                onClick={() => setShowModal(false)}
                                className="flex-1 py-3 border border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-300 font-medium rounded-xl hover:bg-gray-100 dark:hover:bg-white/5 transition-all"
                            >
                                Batal
                            </button>
                            <button
                                onClick={handleCreate}
                                disabled={isCreating || !formData.description || !formData.amount}
                                className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl flex items-center justify-center gap-2 disabled:opacity-50 shadow-lg shadow-emerald-500/20 active:scale-95 transition-all"
                            >
                                {isCreating ? (
                                    <>
                                        <Loader2 className="w-5 h-5 animate-spin" />
                                        Menyimpan...
                                    </>
                                ) : (
                                    'Simpan'
                                )}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Breadcrumb & Title */}
                    <div className="mb-6">
                        <Link
                            href="/dashboard/keuangan"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 mb-2"
                        >
                            <ArrowLeft className="w-4 h-4" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-3">
                                    <TrendingDown className="w-7 h-7 text-red-600" />
                                    Pengeluaran
                                </h1>
                                <p className="text-gray-500">
                                    Catat dan kelola semua pengeluaran pesantren
                                </p>
                            </div>
                            <button
                                onClick={() => setShowModal(true)}
                                className="flex items-center gap-2 px-5 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl transition-colors shadow-lg shadow-emerald-500/30"
                            >
                                <Plus className="w-5 h-5" />
                                Catat Pengeluaran
                            </button>
                        </div>
                    </div>

                    {/* Summary Card */}
                    <div className="bg-gradient-to-r from-red-500 to-rose-600 rounded-2xl p-6 text-white mb-6">
                        <p className="text-red-100 text-sm mb-1">Total Pengeluaran (Tefilter)</p>
                        <p className="text-3xl font-bold">{formatCurrency(totalExpenses)}</p>
                        <div className="flex items-center gap-2 mt-2 text-red-100">
                            <Calendar className="w-4 h-4" />
                            <span className="text-sm">{new Date().toLocaleDateString('id-ID', { month: 'long', year: 'numeric' })}</span>
                        </div>
                    </div>

                    {/* Filters */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 mb-6">
                        <div className="flex flex-col md:flex-row gap-4">
                            <div className="relative flex-1">
                                <Search className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                <input
                                    type="text"
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    placeholder="Cari deskripsi atau PIC..."
                                    className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                />
                            </div>
                            <select
                                value={filterCategory}
                                onChange={(e) => setFilterCategory(e.target.value)}
                                className="px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl"
                            >
                                <option value="all">Semua Kategori</option>
                                {CATEGORIES.map(c => (
                                    <option key={c} value={c}>{CATEGORIES_MAPPING[c]}</option>
                                ))}
                            </select>
                            <button className="flex items-center gap-2 px-4 py-2.5 border border-gray-200 rounded-xl text-gray-700 hover:bg-gray-50">
                                <Download className="w-4 h-4" />
                                Export
                            </button>
                        </div>
                    </div>

                    {/* Table */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-gray-50 border-b border-gray-100">
                                    <tr>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Tanggal</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Kategori</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Deskripsi</th>
                                        <th className="text-right p-4 text-sm font-semibold text-gray-600">Nominal</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">PIC</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100">
                                    {filteredExpenses.map(exp => (
                                        <tr key={exp.id} className="hover:bg-gray-50">
                                            <td className="p-4 text-gray-600 text-sm">{exp.date}</td>
                                            <td className="p-4">
                                                <span className={`px-2 py-1 rounded text-xs font-medium ${categoryColors[exp.category]}`}>
                                                    {CATEGORIES_MAPPING[exp.category] || exp.category}
                                                </span>
                                            </td>
                                            <td className="p-4 text-gray-800">{exp.description}</td>
                                            <td className="p-4 text-right font-semibold text-red-600">{formatCurrency(exp.amount)}</td>
                                            <td className="p-4 text-gray-600 text-sm">{exp.pic}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

