'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { supabase } from '@/lib/supabase';
import {
    getCurrentUser,
    clearSession,
    syncUserSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Receipt,
    Plus,
    Search,
    Filter,
    CheckCircle2,
    XCircle,
    Clock,
    Download,
    Loader2,
    X
} from 'lucide-react';

import { financeService } from '@/lib/services/finance';
import { classesService } from '@/lib/services/classes';
import { studentsService } from '@/lib/services/students';

// ============================================
// Types & Data
// ============================================

// Remove hardcoded types, used dynamic types instead

export default function TagihanPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterStatus, setFilterStatus] = useState<'all' | 'lunas' | 'belum' | 'cicilan'>('all');
    const [filterType, setFilterType] = useState<string>('all');
    const [showModal, setShowModal] = useState(false);
    const [isCreating, setIsCreating] = useState(false);
    const [showSuccess, setShowSuccess] = useState(false);

    const [invoices, setInvoices] = useState<any[]>([]);
    const [classes, setClasses] = useState<any[]>([]);
    const [students, setStudents] = useState<any[]>([]);
    const [invoiceTypes, setInvoiceTypes] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const [showPaymentModal, setShowPaymentModal] = useState(false);
    const [selectedInvoice, setSelectedInvoice] = useState<any>(null);
    const [isProcessing, setIsProcessing] = useState(false);
    const [paymentAmount, setPaymentAmount] = useState(0);
    const [paidSoFar, setPaidSoFar] = useState(0);

    // Form state
    const [formData, setFormData] = useState({
        targetType: 'class',
        classId: '',
        studentId: '',
        type: 'SPP Bulanan',
        dueDate: new Date().toISOString().split('T')[0],
        amount: 500000,
        notes: ''
    });

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_keuangan' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchInitialData();
    }, [router]);

    useEffect(() => {
        fetchInvoices();
    }, [filterStatus, filterType]);

    const fetchInitialData = async () => {
        try {
            // First, sync user session to make sure pesantrenId is up to date
            const updatedUser = await syncUserSession();
            if (updatedUser) setUser(updatedUser);

            const [clsRes, stdRes, types] = await Promise.all([
                supabase.from('classes').select('id, name').order('name'),
                supabase.from('students').select('id, name, nis').order('name'),
                financeService.getInvoiceTypes()
            ]);

            setClasses(clsRes.data || []);
            setStudents(stdRes.data || []);
            setInvoiceTypes(types);

            // Set default type if available
            if (types.length > 0) {
                setFormData(prev => ({ ...prev, type: types[0].name, amount: types[0].amount }));
            }

            fetchInvoices();
        } catch (error) {
            console.error('Error fetching initial data:', error);
            setIsLoading(false);
        }
    };

    const fetchInvoices = async () => {
        try {
            setIsLoading(true);
            const data = await financeService.getAllInvoices({
                status: filterStatus === 'lunas' ? 'paid' : (filterStatus === 'belum' ? 'pending' : (filterStatus === 'cicilan' ? 'partial' : 'all')),
                type: filterType
            });
            setInvoices(data);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching invoices:', error);
            setIsLoading(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleMarkAsPaid = async () => {
        if (!selectedInvoice || paymentAmount <= 0) return alert('Masukkan nominal pembayaran!');
        try {
            setIsProcessing(true);
            const result = await financeService.processPayment({
                invoice_id: selectedInvoice.id,
                amount: paymentAmount,
                payment_method: 'tunai',
                notes: 'Dibayar secara manual melalui admin'
            });
            setShowPaymentModal(false);
            setSelectedInvoice(null);
            setPaymentAmount(0);
            setPaidSoFar(0);
            setIsProcessing(false);
            setShowSuccess(true);
            fetchInvoices();
            setTimeout(() => setShowSuccess(false), 3000);
        } catch (error) {
            console.error('Error processing payment:', error);
            setIsProcessing(false);
            alert('Gagal memproses pembayaran');
        }
    };

    const handleCreate = async () => {
        if (formData.targetType === 'class' && !formData.classId) return alert('Pilih kelas!');
        if (formData.targetType === 'individual' && !formData.studentId) return alert('Pilih santri!');

        try {
            setIsCreating(true);
            const result = await financeService.createInvoice({
                targetType: formData.targetType,
                classId: formData.classId,
                studentId: formData.studentId,
                invoiceType: formData.type,
                amount: formData.amount,
                dueDate: formData.dueDate,
                notes: formData.notes
            });

            setIsCreating(false);
            setShowModal(false);
            setShowSuccess(true);
            fetchInvoices();
            setTimeout(() => setShowSuccess(false), 3000);

            if (result.count > 1) {
                alert(`Berhasil membuat ${result.count} tagihan!`);
            }
        } catch (error: any) {
            console.error('Error creating invoice:', error);
            setIsCreating(false);
            const errorMsg = error.message || (typeof error === 'object' ? JSON.stringify(error) : 'Gagal membuat tagihan');
            alert('Gagal: ' + errorMsg);
        }
    };


    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            minimumFractionDigits: 0
        }).format(amount);
    };

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-emerald-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
                    <span>Loading Data Tagihan...</span>
                </div>
            </div>
        );
    }

    const filteredInvoices = invoices.filter(inv => {
        const matchesSearch = inv.santriName.toLowerCase().includes(searchQuery.toLowerCase()) ||
            inv.id.toLowerCase().includes(searchQuery.toLowerCase()) ||
            inv.type.toLowerCase().includes(searchQuery.toLowerCase());
        return matchesSearch;
    });

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Success Toast */}
            {showSuccess && (
                <div className="fixed top-4 right-4 z-[60] bg-emerald-500 text-white px-6 py-4 rounded-xl shadow-lg flex items-center gap-3">
                    <CheckCircle2 className="w-6 h-6" />
                    <span className="font-medium">Tagihan berhasil dibuat!</span>
                </div>
            )}

            {/* Create Invoice Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-50 flex items-center justify-center p-4 transition-all duration-300">
                    <div className="bg-white dark:bg-neutral-900 rounded-3xl w-full max-w-lg shadow-2xl border border-gray-100 dark:border-white/10 max-h-[90vh] flex flex-col transition-all scale-100">
                        <div className="p-6 border-b border-gray-100 dark:border-white/5 flex items-center justify-between shrink-0">
                            <h3 className="text-xl font-bold text-gray-800 dark:text-white">Buat Tagihan Baru</h3>
                            <button onClick={() => setShowModal(false)} className="p-2 hover:bg-gray-100 rounded-lg">
                                <X className="w-5 h-5 text-gray-500" />
                            </button>
                        </div>
                        <div className="p-6 space-y-4 overflow-y-auto flex-1 custom-scrollbar">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Target Tagihan</label>
                                <select
                                    value={formData.targetType}
                                    onChange={(e) => setFormData({ ...formData, targetType: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all appearance-none"
                                >
                                    <option value="all">Semua Santri</option>
                                    <option value="class">Per Kelas</option>
                                    <option value="individual">Per Santri</option>
                                </select>
                            </div>
                            {formData.targetType === 'individual' && (
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Pilih Santri</label>
                                    <select
                                        value={formData.studentId}
                                        onChange={(e) => setFormData({ ...formData, studentId: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                    >
                                        <option value="">Pilih Santri</option>
                                        {students.map(s => (
                                            <option key={s.id} value={s.id}>{s.name} ({s.nis})</option>
                                        ))}
                                    </select>
                                </div>
                            )}
                            {formData.targetType === 'class' && (
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Pilih Kelas</label>
                                    <select
                                        value={formData.classId}
                                        onChange={(e) => setFormData({ ...formData, classId: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                    >
                                        <option value="">Pilih Kelas</option>
                                        {classes.map(c => (
                                            <option key={c.id} value={c.id}>Kelas {c.name}</option>
                                        ))}
                                    </select>
                                </div>
                            )}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Jenis Tagihan</label>
                                <select
                                    value={formData.type}
                                    onChange={(e) => {
                                        const type = invoiceTypes.find(t => t.name === e.target.value);
                                        setFormData({
                                            ...formData,
                                            type: e.target.value,
                                            amount: type ? type.amount : formData.amount
                                        });
                                    }}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                >
                                    {invoiceTypes.map(t => (
                                        <option key={t.id} value={t.name}>{t.name}</option>
                                    ))}
                                </select>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Jatuh Tempo</label>
                                    <input
                                        type="date"
                                        value={formData.dueDate}
                                        onChange={(e) => setFormData({ ...formData, dueDate: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Nominal</label>
                                    <input
                                        type="number"
                                        value={formData.amount}
                                        onChange={(e) => setFormData({ ...formData, amount: parseInt(e.target.value) })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Catatan (Opsional)</label>
                                <textarea
                                    value={formData.notes}
                                    onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 min-h-[80px]"
                                    placeholder="Contoh: SPP Bulan Januari"
                                />
                            </div>
                        </div>
                        <div className="p-6 border-t border-gray-100 dark:border-white/5 flex gap-3 bg-gray-50 dark:bg-neutral-900/50">
                            <button
                                onClick={() => setShowModal(false)}
                                className="flex-1 py-3 border border-gray-200 text-gray-700 font-medium rounded-xl hover:bg-gray-50"
                            >
                                Batal
                            </button>
                            <button
                                onClick={handleCreate}
                                disabled={isCreating}
                                className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-medium rounded-xl flex items-center justify-center gap-2"
                            >
                                {isCreating ? (
                                    <>
                                        <Loader2 className="w-5 h-5 animate-spin" />
                                        Membuat...
                                    </>
                                ) : (
                                    'Buat Tagihan'
                                )}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Payment Modal dengan Cicilan */}
            {showPaymentModal && selectedInvoice && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[70] flex items-center justify-center p-4 transition-all duration-300">
                    <div className="bg-white dark:bg-neutral-900 rounded-3xl w-full max-w-md shadow-2xl border border-gray-100 dark:border-white/10 transition-all scale-100">
                        <div className="p-6 border-b border-gray-100 dark:border-white/5">
                            <h3 className="text-xl font-bold text-gray-800 dark:text-white">Proses Pembayaran</h3>
                            <p className="text-gray-500 text-sm mt-1">{selectedInvoice.santriName}</p>
                        </div>
                        <div className="p-6 space-y-4">
                            {/* Info Tagihan */}
                            <div className="bg-gray-50 dark:bg-black/20 rounded-xl p-4 space-y-2 border border-gray-100 dark:border-white/5">
                                <div className="flex justify-between text-sm">
                                    <span className="text-gray-500 dark:text-gray-400">Total Tagihan</span>
                                    <span className="font-semibold text-gray-800 dark:text-gray-200">{formatCurrency(selectedInvoice.amount)}</span>
                                </div>
                                <div className="flex justify-between text-sm">
                                    <span className="text-gray-500 dark:text-gray-400">Sudah Dibayar</span>
                                    <span className="font-semibold text-amber-600 dark:text-amber-500">{formatCurrency(paidSoFar)}</span>
                                </div>
                                <hr className="border-gray-200 dark:border-white/5" />
                                <div className="flex justify-between text-sm">
                                    <span className="text-gray-500 dark:text-gray-400">Sisa Tagihan</span>
                                    <span className="font-bold text-red-600 dark:text-red-500">{formatCurrency(selectedInvoice.amount - paidSoFar)}</span>
                                </div>
                            </div>

                            {/* Input Nominal Pembayaran */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Nominal Pembayaran</label>
                                <input
                                    type="number"
                                    value={paymentAmount}
                                    onChange={(e) => setPaymentAmount(parseInt(e.target.value) || 0)}
                                    placeholder="Masukkan nominal"
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                />
                                <div className="flex gap-2 mt-2">
                                    <button
                                        onClick={() => setPaymentAmount(selectedInvoice.amount - paidSoFar)}
                                        className="text-xs px-3 py-1 bg-emerald-100 text-emerald-700 rounded-lg hover:bg-emerald-200"
                                    >
                                        Bayar Lunas
                                    </button>
                                    <button
                                        onClick={() => setPaymentAmount(Math.floor((selectedInvoice.amount - paidSoFar) / 2))}
                                        className="text-xs px-3 py-1 bg-amber-100 text-amber-700 rounded-lg hover:bg-amber-200"
                                    >
                                        Setengah
                                    </button>
                                </div>
                            </div>

                            {paymentAmount > 0 && (
                                <div className="text-sm text-center p-2 rounded-lg bg-blue-50 text-blue-700">
                                    {paymentAmount >= (selectedInvoice.amount - paidSoFar)
                                        ? '✅ Tagihan akan LUNAS'
                                        : `⏳ Sisa setelah bayar: ${formatCurrency(selectedInvoice.amount - paidSoFar - paymentAmount)}`
                                    }
                                </div>
                            )}
                        </div>
                        <div className="p-6 border-t border-gray-100 flex gap-3">
                            <button
                                onClick={() => { setShowPaymentModal(false); setPaymentAmount(0); setPaidSoFar(0); }}
                                className="flex-1 py-3 border border-gray-200 text-gray-700 font-medium rounded-xl hover:bg-gray-50"
                            >
                                Batal
                            </button>
                            <button
                                onClick={handleMarkAsPaid}
                                disabled={isProcessing || paymentAmount <= 0}
                                className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-medium rounded-xl flex items-center justify-center gap-2 disabled:opacity-50"
                            >
                                {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : `Bayar ${formatCurrency(paymentAmount)}`}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Breadcrumb & Title */}
                    <div className="mb-6">
                        <Link
                            href="/dashboard/keuangan"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 mb-2"
                        >
                            <ArrowLeft className="w-4 h-4" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-3">
                                    <Receipt className="w-7 h-7 text-emerald-600" />
                                    SPP & Tagihan
                                </h1>
                                <p className="text-gray-500">
                                    Kelola semua tagihan santri
                                </p>
                            </div>
                            <button
                                onClick={() => setShowModal(true)}
                                className="flex items-center gap-2 px-5 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl transition-colors shadow-lg shadow-emerald-500/30"
                            >
                                <Plus className="w-5 h-5" />
                                Buat Tagihan Baru
                            </button>
                        </div>
                    </div>

                    {/* Stats Cards */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                        <div className="bg-white rounded-xl p-4 border border-gray-100 shadow-sm">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-emerald-100 rounded-lg flex items-center justify-center">
                                    <CheckCircle2 className="w-5 h-5 text-emerald-600" />
                                </div>
                                <div>
                                    <p className="text-2xl font-bold text-gray-800">{invoices.filter(i => i.status === 'lunas').length}</p>
                                    <p className="text-sm text-gray-500">Lunas</p>
                                </div>
                            </div>
                        </div>
                        <div className="bg-white rounded-xl p-4 border border-gray-100 shadow-sm">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-red-100 rounded-lg flex items-center justify-center">
                                    <XCircle className="w-5 h-5 text-red-600" />
                                </div>
                                <div>
                                    <p className="text-2xl font-bold text-gray-800">{invoices.filter(i => i.status === 'belum').length}</p>
                                    <p className="text-sm text-gray-500">Belum Bayar</p>
                                </div>
                            </div>
                        </div>
                        <div className="bg-white rounded-xl p-4 border border-gray-100 shadow-sm">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-amber-100 rounded-lg flex items-center justify-center">
                                    <Clock className="w-5 h-5 text-amber-600" />
                                </div>
                                <div>
                                    <p className="text-2xl font-bold text-gray-800">{invoices.filter(i => i.status === 'cicilan').length}</p>
                                    <p className="text-sm text-gray-500">Cicilan</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Filters */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 mb-6">
                        <div className="flex flex-col md:flex-row gap-4">
                            <div className="relative flex-1">
                                <Search className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                <input
                                    type="text"
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    placeholder="Cari santri atau invoice..."
                                    className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                />
                            </div>
                            <select
                                value={filterStatus}
                                onChange={(e) => setFilterStatus(e.target.value as 'all' | 'lunas' | 'belum' | 'cicilan')}
                                className="px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl"
                            >
                                <option value="all">Semua Status</option>
                                <option value="lunas">Lunas</option>
                                <option value="belum">Belum Bayar</option>
                                <option value="cicilan">Cicilan</option>
                            </select>
                            <select
                                value={filterType}
                                onChange={(e) => setFilterType(e.target.value)}
                                className="px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl"
                            >
                                <option value="all">Semua Jenis</option>
                                {invoiceTypes.map(t => (
                                    <option key={t.id} value={t.name}>{t.name}</option>
                                ))}
                            </select>
                            <button className="flex items-center gap-2 px-4 py-2.5 border border-gray-200 rounded-xl text-gray-700 hover:bg-gray-50">
                                <Download className="w-4 h-4" />
                                Export
                            </button>
                        </div>
                    </div>

                    {/* Table */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-gray-50 border-b border-gray-100">
                                    <tr>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Invoice ID</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Santri</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Kelas</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Jenis</th>
                                        <th className="text-right p-4 text-sm font-semibold text-gray-600">Nominal</th>
                                        <th className="text-center p-4 text-sm font-semibold text-gray-600">Status</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Jatuh Tempo</th>
                                        <th className="text-center p-4 text-sm font-semibold text-gray-600">Aksi</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100">
                                    {filteredInvoices.map(inv => (
                                        <tr key={inv.id} className="hover:bg-gray-50">
                                            <td className="p-4 font-mono text-sm text-gray-800">{inv.id}</td>
                                            <td className="p-4 font-medium text-gray-800">{inv.santriName}</td>
                                            <td className="p-4 text-gray-600">{inv.class}</td>
                                            <td className="p-4">
                                                <span className="px-2 py-1 bg-gray-100 text-gray-700 rounded text-xs font-medium">
                                                    {inv.type}
                                                </span>
                                            </td>
                                            <td className="p-4 text-right font-medium text-gray-800">{formatCurrency(inv.amount)}</td>
                                            <td className="p-4 text-center">
                                                <span className={`px-3 py-1 rounded-full text-xs font-medium ${inv.status === 'lunas'
                                                    ? 'bg-emerald-100 text-emerald-700'
                                                    : inv.status === 'cicilan'
                                                        ? 'bg-amber-100 text-amber-700'
                                                        : 'bg-red-100 text-red-700'
                                                    }`}>
                                                    {inv.status === 'lunas' ? 'Lunas' : inv.status === 'cicilan' ? 'Cicilan' : 'Belum Bayar'}
                                                </span>
                                            </td>
                                            <td className="p-4 text-gray-600 text-sm">{new Date(inv.dueDate).toLocaleDateString('id-ID')}</td>
                                            <td className="p-4 text-center">
                                                {inv.status !== 'lunas' && (
                                                    <button
                                                        onClick={async () => {
                                                            setSelectedInvoice(inv);
                                                            // Fetch existing payments for this invoice
                                                            const { data: payments } = await supabase
                                                                .from('payments')
                                                                .select('amount')
                                                                .eq('invoice_id', inv.id);
                                                            const totalPaid = (payments || []).reduce((sum: number, p: any) => sum + Number(p.amount), 0);
                                                            setPaidSoFar(totalPaid);
                                                            setPaymentAmount(inv.amount - totalPaid);
                                                            setShowPaymentModal(true);
                                                        }}
                                                        className="px-3 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-semibold rounded-lg transition-colors"
                                                    >
                                                        Bayar
                                                    </button>
                                                )}
                                                {inv.status === 'lunas' && (
                                                    <span className="text-xs text-gray-400 italic">Selesai</span>
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                    {filteredInvoices.length === 0 && (
                                        <tr>
                                            <td colSpan={8} className="p-12 text-center text-gray-400 italic">
                                                Tidak ada data tagihan ditemukan.
                                            </td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    Award,
    BookOpen,
    Search,
    ChevronRight,
    CheckCircle2,
    Clock,
    Loader2,
    Calendar,
    Activity,
    Star,
    History as HistoryIcon,
    LayoutGrid
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { supabase } from '@/lib/supabase';
import { hafalanService } from '@/lib/services/hafalan';
import { studentDashboardService } from '@/lib/services/student-dashboard';

export default function ProgressHafalanPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [studentInfo, setStudentInfo] = useState<any>(null);
    const [history, setHistory] = useState<any[]>([]);
    const [summary, setSummary] = useState<any>(null);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'santri') {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData(currentUser.id);
    }, [router]);

    const fetchData = async (userId: string) => {
        try {
            setIsLoading(true);
            const { data: student, error: sError } = await supabase
                .from('students')
                .select('*')
                .eq('user_id', userId)
                .single();

            if (sError) throw sError;
            setStudentInfo(student);

            const [historyData, dashboardData] = await Promise.all([
                hafalanService.getByStudent(student.id),
                studentDashboardService.getHafalanData(student.id)
            ]);

            setHistory(historyData);
            setSummary(dashboardData);
        } catch (err) {
            console.error('Error fetching hafalan history:', err);
        } finally {
            setIsLoading(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const formatDate = (dateString: string) => {
        if (!dateString) return '-';
        return new Date(dateString).toLocaleDateString('id-ID', {
            day: 'numeric',
            month: 'short',
            year: 'numeric'
        });
    };

    const getGradeConfig = (grade: string | null) => {
        if (!grade) return { label: '-', color: 'text-neutral-500 bg-neutral-900 border-neutral-800' };
        const configs: Record<string, any> = {
            'A': { label: 'Mumtaz', color: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20' },
            'B': { label: 'Jayyid Jidda', color: 'text-blue-400 bg-blue-500/10 border-blue-500/20' },
            'C': { label: 'Jayyid', color: 'text-amber-400 bg-amber-500/10 border-amber-500/20' },
            'D': { label: 'Maqbul', color: 'text-orange-400 bg-orange-500/10 border-orange-500/20' },
            'E': { label: 'Dhaif', color: 'text-rose-400 bg-rose-500/10 border-rose-500/20' },
        };
        return configs[grade] || { label: grade, color: 'text-neutral-400 bg-neutral-900 border-neutral-800' };
    };

    if (isLoading && !studentInfo) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[#050505]">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-indigo-500 animate-spin opacity-40" />
                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Menyinkronkan Riwayat Hafalan...</p>
                </div>
            </div>
        );
    }

    if (!user) return null;

    const latestSetoran = history[0];

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-indigo-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="px-6 py-8 lg:p-10 space-y-10 max-w-[1500px] mx-auto">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-400 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Achievement Tracking
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Progress <span className="text-indigo-500">Hafalan & Tahfidz</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Lacak capaian hapalan harian dan target bulanan Anda.</p>
                        </div>

                        <div className="relative group self-start md:self-auto">
                            <div className="absolute -inset-1 bg-gradient-to-r from-indigo-600 to-violet-600 rounded-2xl blur opacity-25 group-hover:opacity-40 transition duration-1000 group-hover:duration-200 shadow-[0_0_20px_rgba(79,70,229,0.3)]"></div>
                            <div className="relative flex items-center gap-3 px-6 py-3 bg-neutral-900 text-white rounded-2xl font-bold uppercase tracking-widest text-[10px] border border-neutral-800">
                                <BookOpen className="w-4 h-4 text-indigo-500" />
                                Total: {summary?.completed || 0} {summary?.unitLabel || 'Unit'} Selesai
                            </div>
                        </div>
                    </div>

                    {/* Stats Summary */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl group relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-6 opacity-[0.03] group-hover:scale-110 transition-transform">
                                <Star className="w-24 h-24" />
                            </div>
                            <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mb-4">Target {summary?.unitLabel || 'Unit'} Aktif</p>
                            <div className="flex items-end justify-between relative z-10">
                                <h4 className="text-2xl lg:text-3xl font-black text-white tracking-tighter truncate pr-2">{summary?.programName || (summary?.unitLabel + ' ' + summary?.currentJuz) || '?'}</h4>
                                <span className="px-3 py-1 bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 rounded-lg text-[9px] font-black uppercase tracking-widest shrink-0">In Progress</span>
                            </div>
                            <div className="w-full h-1.5 bg-neutral-900 rounded-full mt-6 overflow-hidden border border-neutral-800">
                                <div
                                    className="h-full bg-indigo-500 shadow-[0_0_10px_rgba(99,102,241,0.5)] transition-all duration-1000"
                                    style={{ width: `${summary ? Math.max(5, summary.totalProgress || 0) : 0}%` }}
                                ></div>
                            </div>
                        </div>

                        <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl group relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-6 opacity-[0.03] group-hover:scale-110 transition-transform">
                                <Clock className="w-24 h-24" />
                            </div>
                            <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mb-4">Setoran Terakhir</p>
                            <h4 className="text-2xl lg:text-3xl font-black text-white tracking-tighter truncate uppercase">{latestSetoran?.program?.hafalan_type?.name || '-'}</h4>
                            <div className="mt-3 flex items-center gap-2">
                                <div className="w-2 h-2 bg-emerald-500 rounded-full shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
                                <p className="text-[10px] font-bold text-neutral-400 uppercase tracking-widest leading-none">
                                    {latestSetoran ? `${summary?.unitLabel || 'Unit'} ${latestSetoran.unit_number} • Tuntas` : 'Belum Ada Setoran'}
                                </p>
                            </div>
                        </div>

                        <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl group relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-6 opacity-[0.03] group-hover:scale-110 transition-transform">
                                <Award className="w-24 h-24" />
                            </div>
                            <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mb-4">Predikat Terakhir</p>
                            <div className="flex items-center gap-4 relative z-10">
                                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-xl font-black ${getGradeConfig(latestSetoran?.grade).color}`}>
                                    {latestSetoran?.grade || '-'}
                                </div>
                                <div>
                                    <h4 className="text-white font-black uppercase tracking-tight">{getGradeConfig(latestSetoran?.grade).label}</h4>
                                    <p className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest mt-1">Evaluasi Ustadz</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* History Table */}
                    <div className="bg-[#0a0a0a] rounded-[2.5rem] border border-neutral-800/40 shadow-2xl overflow-hidden">
                        <div className="p-8 border-b border-neutral-800/50 bg-neutral-900/20 flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <h3 className="text-sm font-black text-white uppercase tracking-widest flex items-center gap-3">
                                    <HistoryIcon className="w-5 h-5 text-indigo-500" />
                                    Log Book Setoran
                                </h3>
                                <p className="text-[10px] text-neutral-600 font-bold uppercase tracking-widest mt-0.5 ml-8">Riwayat harian evaluasi hafalan.</p>
                            </div>
                            <div className="flex items-center gap-3 px-5 py-2.5 bg-[#050505] border border-neutral-800 rounded-2xl">
                                <Clock className="w-4 h-4 text-neutral-700" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-neutral-500">Update: {formatDate(latestSetoran?.evaluated_at || latestSetoran?.created_at)}</span>
                            </div>
                        </div>
                        <div className="overflow-x-auto custom-scrollbar">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="bg-[#0e0e0e] border-b border-neutral-800/50">
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-32">Tanggal</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Program & Target</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Predikat</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Catatan</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-16"></th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-neutral-800/30">
                                    {history.length === 0 ? (
                                        <tr>
                                            <td colSpan={5} className="py-24 text-center">
                                                <div className="flex flex-col items-center gap-4 opacity-40">
                                                    <LayoutGrid className="w-12 h-12 text-neutral-700" />
                                                    <p className="text-xs font-bold text-neutral-500 uppercase tracking-widest italic">Belum ada riwayat setoran tercatat.</p>
                                                </div>
                                            </td>
                                        </tr>
                                    ) : (
                                        history.map((item) => {
                                            const cfg = getGradeConfig(item.grade);
                                            return (
                                                <tr key={item.id} className="hover:bg-neutral-900/30 transition-all group">
                                                    <td className="px-8 py-6 text-sm font-bold text-neutral-300">{formatDate(item.evaluated_at || item.created_at)}</td>
                                                    <td className="px-8 py-6">
                                                        <div className="flex items-center gap-4">
                                                            <div className="w-10 h-10 bg-indigo-500/5 border border-indigo-500/10 rounded-xl flex items-center justify-center">
                                                                <BookOpen className="w-5 h-5 text-indigo-500" />
                                                            </div>
                                                            <div>
                                                                <p className="font-black text-white text-sm uppercase tracking-tight">{item.program?.hafalan_type?.name || 'Program'}</p>
                                                                <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest mt-1">
                                                                    {item.program?.hafalan_type?.unit_name || 'Unit'} {item.unit_number} • {item.progress_percentage}% Tuntas
                                                                </p>
                                                            </div>
                                                        </div>
                                                    </td>
                                                    <td className="px-8 py-6 text-center">
                                                        <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest border ${cfg.color}`}>
                                                            {cfg.label}
                                                        </span>
                                                    </td>
                                                    <td className="px-8 py-6">
                                                        <p className="text-xs text-neutral-500 italic max-w-xs truncate">{item.notes || 'Tidak ada catatan khusus.'}</p>
                                                    </td>
                                                    <td className="px-8 py-6 text-right">
                                                        <button className="p-2.5 bg-neutral-900 text-neutral-700 rounded-xl hover:bg-neutral-800 hover:text-white transition-all border border-neutral-800">
                                                            <ChevronRight className="w-4 h-4 text-neutral-500" />
                                                        </button>
                                                    </td>
                                                </tr>
                                            );
                                        })
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </main>
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; height: 5px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #1a1a1a; border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #262626; }
            `}</style>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    CalendarDays,
    Clock,
    User as TeacherIcon,
    MapPin,
    ChevronRight,
    Loader2,
    BookOpen,
    Activity,
    Calendar,
    LayoutGrid,
    Star
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { supabase } from '@/lib/supabase';
import { studentDashboardService } from '@/lib/services/student-dashboard';

const DAYS = [
    { label: 'Senin', value: 1 },
    { label: 'Selasa', value: 2 },
    { label: 'Rabu', value: 3 },
    { label: 'Kamis', value: 4 },
    { label: 'Jumat', value: 5 },
    { label: 'Sabtu', value: 6 },
    { label: 'Minggu', value: 0 },
];

export default function JadwalPelajaranPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [activeDay, setActiveDay] = useState(1); // Monday
    const [schedule, setSchedule] = useState<any[]>([]);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'santri') {
            router.replace('/login');
            return;
        }
        setUser(currentUser);

        const today = new Date().getDay();
        setActiveDay(today);

        fetchData(currentUser.id);
    }, [router]);

    const fetchData = async (userId: string) => {
        try {
            setIsLoading(true);
            const { data: student, error: sError } = await supabase
                .from('students')
                .select('id')
                .eq('user_id', userId)
                .single();

            if (sError) throw sError;

            const scheduleData = await studentDashboardService.getWeeklySchedule(student.id);
            setSchedule(scheduleData);
        } catch (err) {
            console.error('Error fetching weekly schedule:', err);
        } finally {
            setIsLoading(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading && schedule.length === 0) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[#050505]">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-indigo-500 animate-spin opacity-40" />
                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Memuat Jadwal Santri...</p>
                </div>
            </div>
        );
    }

    if (!user) return null;

    const filteredSchedule = schedule.filter(item => item.day_of_week === activeDay);

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-indigo-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-10 max-w-[1500px] mx-auto">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-400 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Weekly Routine
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Jadwal <span className="text-indigo-500">Pelajaran Mingguan</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Manajemen waktu belajar anda sepekan untuk hasil yang maksimal.</p>
                        </div>
                    </div>

                    {/* Day Selection Tabs */}
                    <div className="no-scrollbar flex overflow-x-auto p-1.5 gap-1.5 bg-[#0a0a0a] rounded-[2rem] border border-neutral-800/40 shadow-xl">
                        {DAYS.map(day => (
                            <button
                                key={day.value}
                                onClick={() => setActiveDay(day.value)}
                                className={`flex-1 min-w-[100px] py-4 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] transition-all duration-300 ${activeDay === day.value
                                    ? 'bg-indigo-600 text-white shadow-[0_10px_20px_rgba(79,70,229,0.3)]'
                                    : 'text-neutral-600 hover:text-neutral-400 hover:bg-neutral-900/50'
                                    }`}
                            >
                                {day.label}
                            </button>
                        ))}
                    </div>

                    {/* Schedule Content Table */}
                    <div className="bg-[#0a0a0a] rounded-[2.5rem] border border-neutral-800/40 shadow-2xl overflow-hidden relative group">
                        <div className="absolute top-0 right-0 p-12 opacity-[0.01] pointer-events-none group-hover:scale-110 transition-transform duration-[2000ms]">
                            <CalendarDays className="w-64 h-64" />
                        </div>

                        <div className="overflow-x-auto custom-scrollbar">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="bg-[#0e0e0e] border-b border-neutral-800/50">
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-48">Jam / Waktu</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Mata Pelajaran</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Ustadz / Guru</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Ruangan</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-16"></th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-neutral-800/20">
                                    {filteredSchedule.length > 0 ? (
                                        filteredSchedule.map((item) => (
                                            <tr key={item.id} className="hover:bg-neutral-900/30 transition-all group">
                                                <td className="px-8 py-7">
                                                    <div className="flex items-center gap-3">
                                                        <Clock className="w-4 h-4 text-indigo-500/50" />
                                                        <span className="font-black text-white text-sm">{item.start_time.slice(0, 5)} - {item.end_time.slice(0, 5)}</span>
                                                    </div>
                                                </td>
                                                <td className="px-8 py-7">
                                                    <div className="flex items-center gap-4">
                                                        <div className="w-11 h-11 bg-indigo-500/5 border border-indigo-500/10 rounded-xl flex items-center justify-center font-black text-indigo-500 text-sm group-hover:bg-indigo-600 group-hover:text-white transition-all shadow-[0_0_15px_rgba(79,70,229,0.05)]">
                                                            {item.subjects?.name?.charAt(0) || 'K'}
                                                        </div>
                                                        <span className="font-bold text-white text-sm uppercase tracking-tight">{item.subjects?.name || 'Kegiatan Pesantren'}</span>
                                                    </div>
                                                </td>
                                                <td className="px-8 py-7">
                                                    <div className="flex items-center gap-3">
                                                        <TeacherIcon className="w-4 h-4 text-neutral-700" />
                                                        <span className="font-bold text-neutral-500 text-sm whitespace-nowrap">{item.teachers?.name || 'Ustadz / Ustadzah'}</span>
                                                    </div>
                                                </td>
                                                <td className="px-8 py-7 text-center">
                                                    <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-neutral-900 border border-neutral-800 text-neutral-600 rounded-xl text-[9px] font-black uppercase tracking-widest group-hover:text-indigo-400 group-hover:border-indigo-500/20 transition-all">
                                                        <MapPin className="w-3.5 h-3.5" />
                                                        {item.room || 'Aula Utama'}
                                                    </div>
                                                </td>
                                                <td className="px-8 py-7 text-right">
                                                    <button className="p-2.5 bg-neutral-900 text-neutral-700 rounded-xl hover:bg-neutral-800 hover:text-white transition-all border border-neutral-800">
                                                        <ChevronRight className="w-4 h-4" />
                                                    </button>
                                                </td>
                                            </tr>
                                        ))
                                    ) : (
                                        <tr>
                                            <td colSpan={5} className="py-24 text-center">
                                                <div className="flex flex-col items-center gap-4 opacity-40">
                                                    <LayoutGrid className="w-12 h-12 text-neutral-700" />
                                                    <p className="text-xs font-bold text-neutral-500 uppercase tracking-widest italic">Tidak ada agenda pengajaran di hari ini.</p>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>

                    {/* Tip Information */}
                    <div className="p-8 rounded-[2.5rem] bg-[#0c0c0c] border border-neutral-800/40 shadow-xl flex items-center gap-6 group">
                        <div className="w-14 h-14 bg-amber-500/5 border border-amber-500/10 rounded-2xl flex items-center justify-center text-amber-500 shrink-0 shadow-[0_0_20px_rgba(245,158,11,0.05)] group-hover:scale-110 transition-transform">
                            <Star className="w-6 h-6 fill-current" />
                        </div>
                        <div>
                            <h4 className="text-white font-black uppercase tracking-widest text-xs">Pesan Pagi:</h4>
                            <p className="text-neutral-500 text-sm font-medium mt-1">Disiplin adalah jembatan antara cita-cita dan pencapaian. Selamat beraktivitas!</p>
                        </div>
                    </div>
                </main>
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; height: 5px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #1a1a1a; border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #262626; }
                .no-scrollbar::-webkit-scrollbar { display: none; }
                .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    FileText,
    TrendingUp,
    Download,
    Award,
    ChevronDown,
    Loader2,
    Activity,
    Star,
    LayoutGrid,
    Calendar,
    ChevronRight,
    ArrowRight
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { supabase } from '@/lib/supabase';
import { gradesService } from '@/lib/services/grades';
import { attendanceService } from '@/lib/services/attendance';
import { studentDashboardService } from '@/lib/services/student-dashboard';

export default function RiwayatNilaiPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [studentInfo, setStudentInfo] = useState<any>(null);
    const [reports, setReports] = useState<any[]>([]);
    const [summary, setSummary] = useState({
        gpa: 0,
        trend: 0,
        totalHafalan: 0,
        attendance: 100
    });

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'santri') {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData(currentUser.id);
    }, [router]);

    const fetchData = async (userId: string) => {
        try {
            setIsLoading(true);
            const { data: student, error: sError } = await supabase
                .from('students')
                .select('*')
                .eq('user_id', userId)
                .single();

            if (sError) throw sError;
            setStudentInfo(student);

            const gradesData = await gradesService.getByStudent(student.id);

            const grouped = gradesData.reduce((acc: any, grade: any) => {
                const key = `${grade.academic_year_id || '2024'}-${grade.semester}`;
                if (!acc[key]) {
                    acc[key] = {
                        semester: `Semester ${grade.semester === 1 ? 'Ganjil' : 'Genap'} ${grade.academic_year_id || ''}`,
                        grades: []
                    };
                }
                acc[key].grades.push({
                    no: acc[key].grades.length + 1,
                    name: grade.subject?.name || 'Unknown',
                    kkm: 75,
                    score: grade.final_grade || 0,
                    letter: gradesService.getGradeLetter(grade.final_grade || 0),
                    predicate: getPredicate(grade.final_grade || 0)
                });
                return acc;
            }, {});

            const reportsArray = Object.values(grouped).map((group: any) => {
                const avg = group.grades.length > 0
                    ? group.grades.reduce((sum: number, g: any) => sum + (g.score || 0), 0) / group.grades.length
                    : 0;
                return {
                    ...group,
                    gpa: (avg / 25).toFixed(2)
                };
            });

            setReports(reportsArray);

            const [gpaH, hafalan, attPercentage] = await Promise.all([
                studentDashboardService.getGPAHistory(student.id),
                studentDashboardService.getHafalanData(student.id),
                attendanceService.getStudentAttendanceSummary(student.id)
            ]);

            const currentGPA = reportsArray.length > 0 ? Number(reportsArray[0].gpa) : 0;
            const prevGPA = gpaH.length > 1 ? gpaH[gpaH.length - 2].gpa : currentGPA;

            setSummary({
                gpa: currentGPA,
                trend: currentGPA - prevGPA,
                totalHafalan: hafalan?.completed || 0,
                attendance: attPercentage
            });
        } catch (err) {
            console.error('Error fetching grades history:', err);
        } finally {
            setIsLoading(false);
        }
    };

    const getPredicate = (score: number) => {
        if (score >= 90) return 'Sangat Baik';
        if (score >= 80) return 'Baik';
        if (score >= 70) return 'Cukup';
        return 'Kurang';
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading && reports.length === 0) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[#050505]">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-indigo-500 animate-spin opacity-40" />
                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Menyusun Lapor Akademik...</p>
                </div>
            </div>
        );
    }

    if (!user) return null;

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-indigo-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-10 max-w-[1500px] mx-auto">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-400 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Academic Transcript
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Riwayat <span className="text-indigo-500">Nilai & Rapor</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Buku laporan pencapaian akademik digital yang terdokumentasi rapi.</p>
                        </div>
                        <div className="flex gap-4">
                            <button className="px-6 py-3.5 bg-neutral-900 border border-neutral-800 rounded-2xl text-[10px] font-black text-white hover:bg-neutral-800 transition-all flex items-center gap-3 uppercase tracking-widest shadow-xl">
                                <Download className="w-4 h-4 text-indigo-500" />
                                Export Rapor PDF
                            </button>
                        </div>
                    </div>

                    {/* Stats Summary */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="bg-gradient-to-br from-indigo-600 to-indigo-900 p-8 rounded-[2.5rem] text-white shadow-2xl shadow-indigo-500/10 relative overflow-hidden group">
                            <div className="relative z-10">
                                <p className="text-indigo-100/60 text-[10px] font-black uppercase tracking-widest mb-4">IPK Terakhir</p>
                                <h4 className="text-6xl font-black tracking-tighter">{summary.gpa || '0.00'}</h4>
                                <div className={`mt-6 flex items-center gap-2 text-[10px] font-black uppercase tracking-widest bg-white/10 w-fit px-4 py-2 rounded-xl backdrop-blur-md border border-white/5`}>
                                    <TrendingUp className={`w-3.5 h-3.5 ${summary.trend >= 0 ? 'text-emerald-400' : 'text-rose-400'}`} />
                                    {summary.trend >= 0 ? 'Meningkat' : 'Menurun'} {Math.abs(summary.trend).toFixed(2)}
                                </div>
                            </div>
                            <Award className="absolute top-1/2 right-0 -translate-y-1/2 w-40 h-40 text-white/10 rotate-12 group-hover:rotate-0 transition-transform duration-1000" />
                        </div>

                        <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col justify-center relative group overflow-hidden">
                            <div className="absolute top-0 right-0 p-8 opacity-[0.02] pointer-events-none group-hover:scale-110 transition-transform">
                                <Star className="w-32 h-32" />
                            </div>
                            <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mb-4">Progres Tahfidz</p>
                            <h4 className="text-4xl font-black text-white tracking-tighter">{summary.totalHafalan} <span className="text-lg text-neutral-600 font-bold uppercase ml-1">/ 30 Juz</span></h4>
                            <div className="w-full h-1.5 bg-neutral-900 rounded-full mt-6 overflow-hidden border border-neutral-800">
                                <div className="h-full bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)] transition-all duration-1000" style={{ width: `${(summary.totalHafalan / 30) * 100}%` }}></div>
                            </div>
                        </div>

                        <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col justify-center relative group overflow-hidden">
                            <div className="absolute top-0 right-0 p-8 opacity-[0.02] pointer-events-none group-hover:scale-110 transition-transform">
                                <Activity className="w-32 h-32" />
                            </div>
                            <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mb-4">Absensi Kehadiran</p>
                            <h4 className="text-4xl font-black text-white tracking-tighter">{summary.attendance}%</h4>
                            <div className="mt-4 flex items-center gap-2">
                                <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
                                <span className="text-[10px] font-bold text-neutral-400 uppercase tracking-widest">Kualifikasi Sangat Baik</span>
                            </div>
                        </div>
                    </div>

                    {/* Reports List */}
                    <div className="space-y-10">
                        {reports.length === 0 ? (
                            <div className="bg-[#0a0a0a] p-24 rounded-[3rem] border border-neutral-800/50 text-center shadow-2xl">
                                <div className="w-20 h-20 bg-neutral-900 rounded-[2rem] flex items-center justify-center mx-auto mb-8 border border-neutral-800">
                                    <FileText className="w-10 h-10 text-neutral-800" />
                                </div>
                                <h3 className="text-2xl font-black text-white mb-2 tracking-tight">Belum Ada Transkip</h3>
                                <p className="text-neutral-500 max-w-sm mx-auto font-medium">Laporan akademik anda akan muncul di sini setelah divalidasi oleh asatidzah.</p>
                            </div>
                        ) : (
                            reports.map((report, idx) => (
                                <div key={idx} className="bg-[#0a0a0a] rounded-[2.5rem] border border-neutral-800/40 shadow-2xl overflow-hidden">
                                    <div className="p-8 border-b border-neutral-800/50 bg-neutral-900/20 flex items-center justify-between">
                                        <div>
                                            <h3 className="font-black text-white uppercase tracking-[0.2em] text-sm">{report.semester}</h3>
                                            <div className="flex items-center gap-2 mt-1">
                                                <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></div>
                                                <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">Cumulative GPA: {report.gpa}</p>
                                            </div>
                                        </div>
                                        <button className="p-2.5 bg-[#050505] text-neutral-600 hover:text-white rounded-xl border border-neutral-800 transition-all">
                                            <ChevronDown className="w-5 h-5" />
                                        </button>
                                    </div>
                                    <div className="overflow-x-auto custom-scrollbar">
                                        <table className="w-full text-left font-sans">
                                            <thead>
                                                <tr className="bg-[#0e0e0e] border-b border-neutral-800/50">
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-16 text-center">No</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Mata Pelajaran</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">KKM</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Angka</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Grd</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Predikat</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-neutral-800/20">
                                                {report.grades.map((sub: any) => (
                                                    <tr key={sub.no} className="hover:bg-neutral-900/30 transition-all group">
                                                        <td className="px-8 py-6 text-center font-bold text-neutral-700 text-xs">{sub.no}</td>
                                                        <td className="px-8 py-6">
                                                            <div className="flex items-center gap-3">
                                                                <div className="w-8 h-8 rounded-lg bg-neutral-900 border border-neutral-800 flex items-center justify-center text-[10px] font-black text-neutral-500 group-hover:text-indigo-500 group-hover:border-indigo-500/30 transition-all">
                                                                    {sub.no}
                                                                </div>
                                                                <span className="font-bold text-white text-sm uppercase tracking-tight">{sub.name}</span>
                                                            </div>
                                                        </td>
                                                        <td className="px-8 py-6 text-center font-bold text-neutral-600 text-xs">{sub.kkm}</td>
                                                        <td className="px-8 py-6 text-center font-black text-white text-lg tracking-tighter">{sub.score}</td>
                                                        <td className="px-8 py-6 text-center">
                                                            <div className={`w-10 h-10 rounded-xl mx-auto flex items-center justify-center font-black text-sm border ${sub.letter === 'A' ? 'bg-indigo-500 text-white border-indigo-600 shadow-[0_0_15px_rgba(79,70,229,0.3)]' :
                                                                sub.letter === 'B' ? 'bg-neutral-900 text-indigo-400 border-neutral-800' :
                                                                    'bg-neutral-900 text-neutral-600 border-neutral-800'
                                                                }`}>
                                                                {sub.letter}
                                                            </div>
                                                        </td>
                                                        <td className="px-8 py-6">
                                                            <span className="px-4 py-1.5 bg-neutral-900 text-neutral-500 rounded-xl text-[9px] font-black uppercase tracking-widest border border-neutral-800 group-hover:text-indigo-400 group-hover:border-indigo-500/20 transition-all">
                                                                {sub.predicate}
                                                            </span>
                                                        </td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </main>
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; height: 5px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #1a1a1a; border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #262626; }
            `}</style>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    TrendingUp,
    Calendar,
    BookOpen,
    Clock,
    User as UserIcon,
    Award,
    GraduationCap,
    Star,
    Users,
    ChevronRight,
    Activity,
    Loader2,
    MapPin
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ResponsiveContainer,
    AreaChart,
    Area,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip as RechartsTooltip,
    PieChart,
    Pie,
    Cell,
} from 'recharts';

import { studentDashboardService } from '@/lib/services/student-dashboard';
import { academicYearService } from '@/lib/services/academic';
import { supabase } from '@/lib/supabase';

const COLORS = ['#6366f1', '#1f1f1f'];

export default function SantriDashboard() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    // Real Data State
    const [studentInfo, setStudentInfo] = useState<any>(null);
    const [gpaHistory, setGPAHistory] = useState<any[]>([]);
    const [hafalanData, setHafalanData] = useState<any>(null);
    const [todaySchedule, setTodaySchedule] = useState<any[]>([]);
    const [topScore, setTopScore] = useState<any>(null);
    const [disciplinePoints, setDisciplinePoints] = useState<number>(100);
    const [recentViolations, setRecentViolations] = useState<any[]>([]);
    const [activeYear, setActiveYear] = useState<any>(null);

    const fetchData = useCallback(async (userId: string) => {
        try {
            setIsLoading(true);
            const { data: student, error: sError } = await supabase
                .from('students')
                .select('*, classes(name)')
                .eq('user_id', userId)
                .maybeSingle();

            if (sError) throw sError;

            if (!student) {
                console.warn('No student record found for this user ID:', userId);
                setStudentInfo(null);
                setIsLoading(false);
                return;
            }

            setStudentInfo(student);

            const [gpa, hafalan, schedule, top, points, recentV, year] = await Promise.all([
                studentDashboardService.getGPAHistory(student.id).catch(e => { console.error('GPA Fetch Error:', e); return []; }),
                studentDashboardService.getHafalanData(student.id).catch(e => { console.error('Hafalan Fetch Error:', e); return null; }),
                studentDashboardService.getTodaySchedule(student.id).catch(e => { console.error('Schedule Fetch Error:', e); return []; }),
                studentDashboardService.getTopScore(student.id).catch(e => { console.error('Top Score Fetch Error:', e); return null; }),
                studentDashboardService.getDisciplinePoints(student.id).catch(e => { console.error('Points Fetch Error:', e); return 100; }),
                studentDashboardService.getRecentViolations(student.id).catch(e => { console.error('Violations Fetch Error:', e); return []; }),
                academicYearService.getActive().catch(e => { console.error('Academic Year Fetch Error:', e); return null; })
            ]);

            setGPAHistory(gpa);
            setHafalanData(hafalan);
            setTodaySchedule(schedule);
            setTopScore(top);
            setDisciplinePoints(points);
            setRecentViolations(recentV);
            setActiveYear(year);
        } catch (err: unknown) {
            console.error('Error fetching student dashboard data:', err);
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'santri') {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData(currentUser.id);
    }, [router, fetchData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading && !studentInfo) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[#050505]">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-indigo-500 animate-spin opacity-40" />
                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Menyamakan Portal Santri...</p>
                </div>
            </div>
        );
    }

    if (!user) return null;

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-indigo-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="w-full px-4 sm:px-6 py-8 lg:p-10 space-y-10 max-w-[1600px] mx-auto overflow-x-hidden">
                    {/* Welcome Header */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-3 text-indigo-400 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Student Portal Integrated
                                <span className="flex h-2 w-2 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]"></span>
                                <span className="text-[9px] text-neutral-600 font-bold uppercase tracking-widest">Live Sync Alpha</span>
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Ahlan, <span className="text-indigo-500">{user.name.split(' ')[0]}!</span> 👋
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Semangat belajar! Data kamu telah tersinkronisasi dengan sistem pusat.</p>
                        </div>

                        <div className="relative group self-start md:self-auto">
                            <div className="absolute -inset-1 bg-gradient-to-r from-indigo-600 to-violet-600 rounded-2xl blur opacity-25 group-hover:opacity-40 transition duration-1000 group-hover:duration-200"></div>
                            <div className="relative flex items-center gap-3 px-6 py-3 bg-neutral-900 border border-neutral-800 text-white rounded-2xl font-bold uppercase tracking-widest text-[10px] shadow-[0_0_20px_rgba(79,70,229,0.1)]">
                                <Calendar className="w-4 h-4 text-indigo-500" />
                                {activeYear?.name || 'Tahun Ajaran'}
                            </div>
                        </div>
                    </div>

                    <div className="flex flex-col lg:grid lg:grid-cols-12 gap-6 lg:gap-8">
                        {/* LEFT COLUMN */}
                        <div className="col-span-12 lg:col-span-8 space-y-8">

                            {/* Stats Cards Row */}
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 sm:gap-4">
                                {[
                                    { label: 'Indeks Prestasi', value: gpaHistory[gpaHistory.length - 1]?.gpa || '0.0', icon: GraduationCap, color: 'text-indigo-500', bg: 'bg-indigo-500/10' },
                                    { label: 'Hafalan Aktif', value: hafalanData ? (hafalanData.unitLabel ? `${hafalanData.unitLabel} ${hafalanData.currentJuz}` : hafalanData.currentName) : 'No Data', icon: BookOpen, color: 'text-emerald-500', bg: 'bg-emerald-500/10' },
                                    { label: 'Jadwal Hari Ini', value: todaySchedule.length, icon: Clock, color: 'text-amber-500', bg: 'bg-amber-500/10' },
                                    { label: 'Poin Kedisiplinan', value: disciplinePoints.toString(), icon: Star, color: disciplinePoints > 80 ? 'text-rose-500' : 'text-amber-500', bg: 'bg-rose-500/10' },
                                ].map((s, i) => (
                                    <div key={i} className="bg-[#0a0a0a] p-4 sm:p-5 rounded-3xl border border-neutral-800/40 hover:border-indigo-500/20 transition-all group overflow-hidden">
                                        <div className={`w-10 h-10 rounded-xl ${s.bg} flex items-center justify-center ${s.color} mb-4 group-hover:scale-110 transition-transform shrink-0`}>
                                            <s.icon className="w-5 h-5" />
                                        </div>
                                        <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest mb-1 truncate">{s.label}</p>
                                        <p className="text-xl font-black text-white truncate">{s.value}</p>
                                    </div>
                                ))}
                            </div>

                            {/* GPA Chart Area */}
                            <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-2xl relative overflow-hidden group">
                                <div className="absolute top-0 right-0 p-8 opacity-[0.02] pointer-events-none group-hover:scale-110 transition-transform duration-1000">
                                    <TrendingUp className="w-48 h-48" />
                                </div>
                                <div className="mb-10 flex items-center justify-between relative z-10">
                                    <div>
                                        <h3 className="text-xl font-black text-white tracking-tight uppercase">Tren Capaian Akademik</h3>
                                        <p className="text-[10px] text-neutral-500 font-bold uppercase tracking-[0.2em] mt-1">Indeks Prestasi Kumulatif per Semester</p>
                                    </div>
                                    <div className="p-3 bg-indigo-500/10 rounded-2xl text-indigo-500">
                                        <TrendingUp className="w-5 h-5" />
                                    </div>
                                </div>
                                <div className="h-[300px] w-full relative z-10">
                                    {gpaHistory.length === 0 ? (
                                        <div className="h-full flex flex-col items-center justify-center gap-4 opacity-40">
                                            <TrendingUp className="w-12 h-12 text-neutral-700" />
                                            <p className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">Belum ada riwayat nilai.</p>
                                        </div>
                                    ) : (
                                        <ResponsiveContainer width="100%" height="100%">
                                            <AreaChart data={gpaHistory} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                                                <defs>
                                                    <linearGradient id="colorGPA" x1="0" y1="0" x2="0" y2="1">
                                                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3} />
                                                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0.0} />
                                                    </linearGradient>
                                                </defs>
                                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1a1a1a" />
                                                <XAxis
                                                    dataKey="semester"
                                                    axisLine={false}
                                                    tickLine={false}
                                                    tick={{ fontSize: 10, fill: '#525252', fontWeight: 800 }}
                                                    dy={15}
                                                />
                                                <YAxis
                                                    axisLine={false}
                                                    tickLine={false}
                                                    tick={{ fontSize: 10, fill: '#525252' }}
                                                    domain={[0, 4]}
                                                />
                                                <RechartsTooltip
                                                    contentStyle={{ backgroundColor: '#0c0c0c', borderRadius: '16px', border: '1px solid #1f1f1f', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.5)', padding: '16px' }}
                                                    itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                                                />
                                                <Area
                                                    type="monotone"
                                                    dataKey="gpa"
                                                    stroke="#6366f1"
                                                    strokeWidth={4}
                                                    fillOpacity={1}
                                                    fill="url(#colorGPA)"
                                                    dot={{ r: 5, fill: '#6366f1', strokeWidth: 2, stroke: '#050505' }}
                                                    activeDot={{ r: 7, strokeWidth: 0, fill: '#fff' }}
                                                />
                                            </AreaChart>
                                        </ResponsiveContainer>
                                    )}
                                </div>
                            </div>

                            {/* Today's Schedule */}
                            <div className="bg-[#0a0a0a] rounded-[2.5rem] border border-neutral-800/40 shadow-2xl overflow-hidden">
                                <div className="p-8 border-b border-neutral-800/50 flex items-center justify-between bg-neutral-900/40">
                                    <h3 className="text-sm font-black text-white uppercase tracking-widest flex items-center gap-3">
                                        <Calendar className="w-5 h-5 text-indigo-500" />
                                        Agenda Belajar Hari Ini
                                    </h3>
                                    <button
                                        onClick={() => router.push('/dashboard/santri/jadwal')}
                                        className="text-[10px] font-black text-indigo-500 uppercase tracking-widest hover:text-white transition-colors flex items-center gap-1 group"
                                    >
                                        Seluruh Jadwal
                                        <ChevronRight className="w-3 h-3 group-hover:translate-x-1 transition-transform" />
                                    </button>
                                </div>
                                <div className="p-4 lg:p-8">
                                    <div className="overflow-x-auto custom-scrollbar">
                                        <table className="w-full text-left">
                                            <thead>
                                                <tr className="text-neutral-600 text-[10px] font-bold uppercase tracking-[0.2em] border-b border-neutral-800/30">
                                                    <th className="pb-5 px-4 w-32">Waktu</th>
                                                    <th className="pb-5 px-4">Mata Pelajaran</th>
                                                    <th className="pb-5 px-4">Pembimbing</th>
                                                    <th className="pb-5 px-4 text-center">Status</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-neutral-800/20">
                                                {todaySchedule.length === 0 ? (
                                                    <tr>
                                                        <td colSpan={4} className="py-16 text-center text-neutral-700 font-bold uppercase text-[10px] tracking-widest italic leading-relaxed">
                                                            No learning sessions scheduled for today.<br />
                                                            Focus on your self-study and memorization.
                                                        </td>
                                                    </tr>
                                                ) : (
                                                    todaySchedule.map((item) => (
                                                        <tr key={item.id} className="group hover:bg-neutral-900/30 transition-colors">
                                                            <td className="py-6 px-4 font-bold text-neutral-300 text-sm">{item.time}</td>
                                                            <td className="py-6 px-4">
                                                                <div className="flex items-center gap-4">
                                                                    <div className="w-10 h-10 bg-indigo-500/5 border border-indigo-500/10 rounded-xl flex items-center justify-center font-black text-indigo-500 text-sm group-hover:bg-indigo-600 group-hover:text-white transition-all">
                                                                        {item.subject.charAt(0)}
                                                                    </div>
                                                                    <div>
                                                                        <p className="font-bold text-white text-sm uppercase tracking-tight">{item.subject}</p>
                                                                        <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest mt-1 flex items-center gap-1">
                                                                            <MapPin className="w-3 h-3" />
                                                                            {item.room}
                                                                        </p>
                                                                    </div>
                                                                </div>
                                                            </td>
                                                            <td className="py-6 px-4 text-neutral-500 text-sm font-medium">{item.teacher}</td>
                                                            <td className="py-6 px-4 text-center">
                                                                <span className={`px-4 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest border ${item.status === 'Selesai' ? 'bg-emerald-500/5 text-emerald-500 border-emerald-500/10' :
                                                                    item.status === 'Sedang Berlangsung' ? 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20 shadow-[0_0_15px_rgba(79,70,229,0.1)] animate-pulse' :
                                                                        'bg-neutral-900 text-neutral-600 border-neutral-800'
                                                                    }`}>
                                                                    {item.status}
                                                                </span>
                                                            </td>
                                                        </tr>
                                                    ))
                                                )}
                                            </tbody>
                                        </table>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* RIGHT COLUMN */}
                        <div className="col-span-12 lg:col-span-4 space-y-8">

                            {/* Hafalan Progress Card */}
                            <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-2xl flex flex-col group relative overflow-hidden">
                                <div className="absolute top-0 right-0 p-8 opacity-[0.02] pointer-events-none group-hover:scale-110 transition-transform">
                                    <BookOpen className="w-32 h-32" />
                                </div>
                                <div className="w-full mb-8 flex items-center justify-between relative z-10">
                                    <h3 className="text-sm font-black text-white uppercase tracking-[0.2em]">Progres Hafalan</h3>
                                    <div className="flex items-center gap-2 px-3 py-1 bg-emerald-500/10 rounded-full">
                                        <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></div>
                                        <span className="text-[9px] font-bold text-emerald-500 uppercase tracking-widest">Live Sync</span>
                                    </div>
                                </div>

                                <div className="relative z-10 space-y-6">
                                    <div className="flex items-center justify-between">
                                        <div>
                                            <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest mb-1">Capaian Saat Ini</p>
                                            <h4 className="text-3xl font-black text-white tracking-tighter">{hafalanData?.currentName || 'Belum Ada Data'}</h4>
                                            {hafalanData?.currentDetail && (
                                                <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest mt-1">{hafalanData.currentDetail}</p>
                                            )}
                                        </div>
                                        <div className="text-right">
                                            <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest mb-1">Target</p>
                                            <p className="text-xl font-black text-neutral-400">{hafalanData?.totalTarget || 30} {hafalanData?.unitLabel || 'Unit'}</p>
                                        </div>
                                    </div>

                                    {/* Premium Progress Bar */}
                                    <div className="space-y-3">
                                        <div className="flex justify-between items-end">
                                            <span className="text-[10px] font-black text-neutral-500 uppercase tracking-widest">Estimasi Selesai</span>
                                            <span className="text-sm font-black text-white">{hafalanData ? `${hafalanData.totalProgress || 0}%` : '--'}</span>
                                        </div>
                                        <div className="h-3 bg-neutral-900 rounded-full overflow-hidden border border-neutral-800/50 p-[2px]">
                                            <div
                                                className="h-full bg-gradient-to-r from-indigo-600 to-emerald-500 rounded-full transition-all duration-1000 shadow-[0_0_15px_rgba(99,102,241,0.3)]"
                                                style={{ width: `${hafalanData ? Math.max(5, hafalanData.totalProgress || 0) : 0}%`, opacity: hafalanData ? 1 : 0 }}
                                            ></div>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 gap-4 mt-8">
                                        <div className="p-4 bg-[#0c0c0c] rounded-2xl border border-neutral-800/50">
                                            <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest mb-1 text-center">Tuntas</p>
                                            <p className="text-xl font-black text-white text-center">{hafalanData ? `${hafalanData.completed} ${hafalanData.unitLabel || 'Juz'}` : '--'}</p>
                                        </div>
                                        <div className="p-4 bg-[#0c0c0c] rounded-2xl border border-neutral-800/50">
                                            <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest mb-1 text-center">Sisa</p>
                                            <p className="text-xl font-black text-indigo-500 text-center">{hafalanData ? `${hafalanData.remaining} ${hafalanData.unitLabel || 'Juz'}` : '--'}</p>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Performance Card - Best Subject */}
                            <div className="bg-gradient-to-br from-indigo-600 to-indigo-900 p-8 rounded-[2.5rem] text-white shadow-2xl shadow-indigo-500/20 group relative overflow-hidden cursor-pointer active:scale-95 transition-all">
                                <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:scale-125 transition-transform duration-1000 rotate-12">
                                    <Star className="w-32 h-32 fill-white" />
                                </div>
                                <div className="relative z-10">
                                    <div className="flex items-center justify-between mb-8">
                                        <div className="px-3 py-1 bg-white/20 backdrop-blur-md rounded-full text-[9px] font-black uppercase tracking-widest border border-white/10">
                                            Top Performance
                                        </div>
                                        <Award className="w-5 h-5 text-indigo-200" />
                                    </div>
                                    <p className="text-[10px] font-bold text-indigo-100/60 uppercase tracking-widest mb-1">Mata Pelajaran Terbaik</p>
                                    <h4 className="text-2xl font-black tracking-tight mb-4 uppercase">{topScore?.subjects?.name || 'Belum Ada Penilaian'}</h4>
                                    <div className="flex items-end gap-3">
                                        <span className="text-5xl font-black tracking-tighter">{topScore?.score || '--'}</span>
                                        <span className="text-[10px] font-bold text-indigo-200 uppercase tracking-widest mb-2 opacity-60">Final Grade</span>
                                    </div>
                                </div>
                            </div>

                            {/* Class Info Box */}
                            <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-2xl relative group overflow-hidden">
                                <div className="absolute -right-4 -bottom-4 bg-indigo-500/5 w-24 h-24 rounded-full blur-3xl group-hover:bg-indigo-500/10 transition-all"></div>
                                <div className="flex items-center gap-5 relative z-10">
                                    <div className="w-14 h-14 bg-indigo-500/10 rounded-2xl flex items-center justify-center text-indigo-500 shrink-0">
                                        <Users className="w-6 h-6" />
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest mb-1">Status Keanggotaan</p>
                                        <h4 className="text-lg font-black text-white tracking-tight uppercase">{studentInfo?.classes?.name || 'Belum Ada Kelas'}</h4>
                                        <div className="flex items-center gap-2 mt-1">
                                            <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
                                            <span className="text-[10px] font-bold text-neutral-400 uppercase tracking-widest">Terdaftar Aktif</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </main>
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar { width: 4px; height: 4px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #1a1a1a; border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #262626; }
            `}</style>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, cacheUser, updateProfile, User } from '@/lib/auth';
import {
    User as UserIcon,
    Camera,
    Calendar,
    MapPin,
    Phone,
    IdCard,
    Users,
    Shield,
    Loader2,
    Save,
    Edit2,
    X,
    Activity,
    ShieldCheck,
    Contact,
    Smartphone,
    Mail,
    Globe,
    ChevronRight,
    ArrowRight
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { studentsService } from '@/lib/services/students';
import { supabase } from '@/lib/supabase';

export default function ProfilSayaPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [studentData, setStudentData] = useState<any>(null);
    const [isEditing, setIsEditing] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [editForm, setEditForm] = useState({
        name: '',
        phone: '',
        address: '',
        birth_place: '',
        birth_date: '',
        parent_name: ''
    });

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'santri') {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData(currentUser.id);
    }, [router]);

    const fetchData = async (userId: string) => {
        try {
            setIsLoading(true);
            const { data: student, error } = await supabase
                .from('students')
                .select(`
                    *,
                    class:classes(name),
                    dormitory:dormitories(name)
                `)
                .eq('user_id', userId)
                .single();

            if (error) throw error;
            setStudentData(student);
            setEditForm({
                name: student.name || '',
                phone: student.parent_phone || '',
                address: student.address || '',
                birth_place: student.birth_place || '',
                birth_date: student.birth_date || '',
                parent_name: student.parent_name || ''
            });
        } catch (err) {
            console.error('Error fetching profile:', err);
        } finally {
            setIsLoading(false);
        }
    };

    const handleSave = async () => {
        if (!studentData) return;
        setIsSaving(true);
        try {
            // 1. Update students table
            await studentsService.update(studentData.id, {
                name: editForm.name,
                parent_phone: editForm.phone,
                address: editForm.address,
                birth_place: editForm.birth_place,
                birth_date: editForm.birth_date || null, // Convert empty string to null for DB compatibility
                parent_name: editForm.parent_name
            });

            // Refresh local state
            setStudentData({
                ...studentData,
                name: editForm.name,
                parent_phone: editForm.phone,
                address: editForm.address,
                birth_place: editForm.birth_place,
                birth_date: editForm.birth_date,
                parent_name: editForm.parent_name
            });

            // 2. Sync with Profiles table if student has a linked user account
            if (studentData.user_id) {
                await updateProfile(studentData.user_id, {
                    name: editForm.name,
                    phone: editForm.phone
                });

                // 3. Update local storage cache to reflect new name in sidebar/header
                const currentUser = getCurrentUser();
                if (currentUser && currentUser.id === studentData.user_id) {
                    cacheUser({
                        ...currentUser,
                        name: editForm.name,
                        phone: editForm.phone
                    });
                }
            }

            setIsEditing(false);
            // Optional: Add a success message notification here if a toast system exists
        } catch (err) {
            console.error('Error updating profile:', err);
            alert('Gagal menyimpan perubahan. Silakan coba lagi.');
        } finally {
            setIsSaving(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading && !studentData) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[#050505]">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-indigo-500 animate-spin opacity-40" />
                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Memuat Portofolio Santri...</p>
                </div>
            </div>
        );
    }

    if (!user || !studentData) return null;

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-indigo-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-10 max-w-[1200px] mx-auto">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-400 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <ShieldCheck className="w-4 h-4" />
                                Student Profile Identity
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Profil & <span className="text-indigo-500">Biodata Santri</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Informasi pribadi dan data akademik yang terdaftar di sistem pusat.</p>
                        </div>

                        <button
                            onClick={() => isEditing ? handleSave() : setIsEditing(true)}
                            disabled={isSaving}
                            className={`px-8 py-4 rounded-[2rem] font-black uppercase tracking-widest text-[10px] flex items-center justify-center gap-3 shadow-2xl transition-all active:scale-95 ${isEditing
                                ? 'bg-indigo-600 text-white shadow-[0_0_20px_rgba(79,70,229,0.3)] hover:bg-indigo-700'
                                : 'bg-neutral-900 text-neutral-400 border border-neutral-800 hover:text-white hover:bg-neutral-800'
                                }`}
                        >
                            {isSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : isEditing ? <Save className="w-4 h-4" /> : <Edit2 className="w-4 h-4 text-indigo-500" />}
                            {isEditing ? 'Simpan Perubahan' : 'Update Informasi'}
                        </button>
                    </div>

                    <div className="space-y-10">
                        {/* Profile Hero Card */}
                        <div className="bg-[#0a0a0a] rounded-[3rem] border border-neutral-800/40 shadow-2xl overflow-hidden relative group">
                            <div className="h-48 bg-gradient-to-br from-indigo-600 via-indigo-950 to-black relative overflow-hidden">
                                <div className="absolute inset-0 opacity-20 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] animate-pulse"></div>
                                <div className="absolute top-0 right-0 p-12 opacity-[0.05] pointer-events-none group-hover:scale-110 transition-transform duration-[2000ms]">
                                    <IdCard className="w-64 h-64 text-white" />
                                </div>
                                {isEditing && (
                                    <button
                                        onClick={() => setIsEditing(false)}
                                        className="absolute top-6 right-6 p-3 bg-white/10 hover:bg-white/20 rounded-2xl text-white transition-all backdrop-blur-md border border-white/10 group/exit"
                                    >
                                        <X className="w-5 h-5 group-hover/exit:rotate-90 transition-transform font-black" />
                                    </button>
                                )}
                            </div>

                            <div className="px-8 md:px-16 pb-16 relative">
                                <div className="flex flex-col md:flex-row items-center md:items-end gap-6 md:gap-10 -mt-20">
                                    <div className="relative group/photo">
                                        <div className="w-40 h-40 md:w-48 md:h-48 rounded-[3.5rem] border-[10px] border-[#0a0a0a] bg-[#050505] overflow-hidden shadow-2xl relative">
                                            <img
                                                src={studentData.photo_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(studentData.name)}&background=1a1a1a&color=6366f1&size=512&bold=true&font-size=0.35`}
                                                alt={studentData.name}
                                                className="w-full h-full object-cover grayscale-[0.2] group-hover/photo:grayscale-0 transition-all duration-500 scale-105 group-hover/photo:scale-110"
                                            />
                                        </div>
                                        {isEditing && (
