                    )}

                    {/* Quick Access Info */}
                    <div className={`grid grid-cols-1 lg:grid-cols-2 gap-8 pb-10 ${children.length === 1 ? 'lg:max-w-7xl' : children.length === 2 ? 'max-w-6xl' : ''}`}>
