'use client';

import { useState } from 'react';
import { supabase } from '@/lib/supabase';
import { CheckCircle, XCircle, Loader2, UserPlus } from 'lucide-react';

const DEMO_USERS = [
    { email: 'admin@pesantren.com', password: 'admin123', name: 'Super Admin', role: 'super_admin' },
    { email: 'keuangan@pesantren.com', password: 'keuangan123', name: 'Admin Keuangan', role: 'admin_keuangan' },
    { email: 'akademik@pesantren.com', password: 'akademik123', name: 'Admin Akademik', role: 'admin_akademik' },
    { email: 'kesantrian@pesantren.com', password: 'kesantrian123', name: 'Staff Kesantrian', role: 'kesantrian' },
    { email: 'ustadz@pesantren.com', password: 'ustadz123', name: 'Ustadz Ahmad', role: 'ustadz' },
    { email: 'walikelas@pesantren.com', password: 'walikelas123', name: 'Wali Kelas 7A', role: 'wali_kelas' },
    { email: 'wali@pesantren.com', password: 'wali123', name: 'Bpk. Ahmad', role: 'wali_santri' },
    { email: 'santri@pesantren.com', password: 'santri123', name: 'Muhammad Rizki', role: 'santri' },
];

interface UserStatus {
    email: string;
    status: 'pending' | 'success' | 'error' | 'exists';
    message: string;
}

export default function SeederPage() {
    const [statuses, setStatuses] = useState<UserStatus[]>([]);
    const [isRunning, setIsRunning] = useState(false);

    const createUsers = async () => {
        setIsRunning(true);
        setStatuses([]);

        for (const user of DEMO_USERS) {
            // Update status to pending
            setStatuses(prev => [...prev, {
                email: user.email,
                status: 'pending',
                message: 'Membuat user...'
            }]);

            try {
                // Try to sign up the user
                const { data, error } = await supabase.auth.signUp({
                    email: user.email,
                    password: user.password,
                    options: {
                        data: {
                            name: user.name,
                            role: user.role,
                        },
                    },
                });

                if (error) {
                    if (error.message.includes('already registered')) {
                        setStatuses(prev =>
                            prev.map(s => s.email === user.email
                                ? { ...s, status: 'exists', message: 'User sudah terdaftar' }
                                : s
                            )
                        );
                    } else {
                        setStatuses(prev =>
                            prev.map(s => s.email === user.email
                                ? { ...s, status: 'error', message: error.message }
                                : s
                            )
                        );
                    }
                } else if (data.user) {
                    // User created, now update profile role
                    const { error: profileError } = await supabase
                        .from('profiles')
                        .upsert({
                            id: data.user.id,
                            email: user.email,
                            name: user.name,
                            role: user.role,
                        });

                    if (profileError) {
                        setStatuses(prev =>
                            prev.map(s => s.email === user.email
                                ? { ...s, status: 'error', message: `Profile error: ${profileError.message}` }
                                : s
                            )
                        );
                    } else {
                        setStatuses(prev =>
                            prev.map(s => s.email === user.email
                                ? { ...s, status: 'success', message: 'Berhasil dibuat!' }
                                : s
                            )
                        );
                    }
                }
            } catch (err: any) {
                setStatuses(prev =>
                    prev.map(s => s.email === user.email
                        ? { ...s, status: 'error', message: err.message }
                        : s
                    )
                );
            }

            // Small delay between users
            await new Promise(r => setTimeout(r, 500));
        }

        setIsRunning(false);
    };

    const getStatusIcon = (status: UserStatus['status']) => {
        switch (status) {
            case 'success': return <CheckCircle className="w-5 h-5 text-green-600" />;
            case 'error': return <XCircle className="w-5 h-5 text-red-600" />;
            case 'exists': return <CheckCircle className="w-5 h-5 text-yellow-600" />;
            default: return <Loader2 className="w-5 h-5 text-gray-400 animate-spin" />;
        }
    };

    const getStatusColor = (status: UserStatus['status']) => {
        switch (status) {
            case 'success': return 'bg-green-50 border-green-200';
            case 'error': return 'bg-red-50 border-red-200';
            case 'exists': return 'bg-yellow-50 border-yellow-200';
            default: return 'bg-gray-50 border-gray-200';
        }
    };

    return (
        <div className="min-h-screen bg-gradient-to-br from-emerald-50 via-white to-amber-50 p-8">
            <div className="max-w-2xl mx-auto">
                <div className="bg-white rounded-2xl shadow-lg p-8">
                    <div className="flex items-center gap-3 mb-6">
                        <UserPlus className="w-8 h-8 text-emerald-600" />
                        <h1 className="text-2xl font-bold text-gray-800">
                            Buat User Demo
                        </h1>
                    </div>

                    <div className="mb-6 p-4 bg-blue-50 border border-blue-200 rounded-lg">
                        <p className="text-sm text-blue-800">
                            <strong>ℹ️ Info:</strong> Halaman ini membuat 8 user demo untuk testing.
                            User akan dibuat via Supabase Auth API (bukan SQL langsung).
                        </p>
                    </div>

                    {statuses.length > 0 && (
                        <div className="space-y-3 mb-6">
                            {statuses.map((status, index) => (
                                <div
                                    key={index}
                                    className={`flex items-center gap-3 p-3 rounded-lg border ${getStatusColor(status.status)}`}
                                >
                                    {getStatusIcon(status.status)}
                                    <div className="flex-1">
                                        <p className="font-medium text-gray-800">{status.email}</p>
                                        <p className="text-sm text-gray-600">{status.message}</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}

                    <button
                        onClick={createUsers}
                        disabled={isRunning}
                        className="flex items-center gap-2 px-6 py-3 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors font-medium"
                    >
                        {isRunning ? (
                            <>
                                <Loader2 className="w-5 h-5 animate-spin" />
                                Membuat User...
                            </>
                        ) : (
                            <>
                                <UserPlus className="w-5 h-5" />
                                Buat 8 User Demo
                            </>
                        )}
                    </button>

                    <div className="mt-8 border-t pt-6">
                        <h3 className="font-semibold text-gray-700 mb-3">Daftar Akun Demo:</h3>
                        <div className="grid grid-cols-2 gap-2 text-sm">
                            {DEMO_USERS.map((user, i) => (
                                <div key={i} className="text-gray-600">
                                    <span className="font-medium">{user.role}:</span> {user.email}
                                </div>
                            ))}
                        </div>
                        <p className="mt-3 text-xs text-gray-500">
                            Password masing-masing: nama role + 123 (contoh: admin123)
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { supabase, isSupabaseConfigured } from '@/lib/supabase';
import { CheckCircle, XCircle, Loader2, Database, Shield, RefreshCw } from 'lucide-react';

interface TestResult {
    name: string;
    status: 'pending' | 'success' | 'error';
    message: string;
}

export default function TestConnectionPage() {
    const [results, setResults] = useState<TestResult[]>([]);
    const [isRunning, setIsRunning] = useState(false);

    const runTests = async () => {
        setIsRunning(true);
        setResults([]);

        const testResults: TestResult[] = [];

        // Test 1: Environment Variables
        testResults.push({
            name: 'Environment Variables',
            status: isSupabaseConfigured() ? 'success' : 'error',
            message: isSupabaseConfigured()
                ? 'SUPABASE_URL dan ANON_KEY terkonfigurasi'
                : 'Environment variables belum diset di .env.local'
        });
        setResults([...testResults]);

        if (!isSupabaseConfigured()) {
            setIsRunning(false);
            return;
        }

        // Test 2: Auth Connection
        try {
            const { data: session, error } = await supabase.auth.getSession();
            testResults.push({
                name: 'Auth Service',
                status: error ? 'error' : 'success',
                message: error
                    ? `Error: ${error.message}`
                    : `Terkoneksi (Session: ${session?.session ? 'Aktif' : 'Tidak ada'})`
            });
        } catch (err: any) {
            testResults.push({
                name: 'Auth Service',
                status: 'error',
                message: `Exception: ${err.message}`
            });
        }
        setResults([...testResults]);

        // Test 3: Database Query (tabel test)
        try {
            const { data, error } = await supabase.from('test').select('*').limit(5);

            if (error) {
                if (error.code === '42P01') {
                    testResults.push({
                        name: 'Query Tabel "test"',
                        status: 'error',
                        message: 'Tabel "test" belum ada. Buat di SQL Editor.'
                    });
                } else {
                    testResults.push({
                        name: 'Query Tabel "test"',
                        status: 'error',
                        message: `Error: ${error.message}`
                    });
                }
            } else {
                testResults.push({
                    name: 'Query Tabel "test"',
                    status: 'success',
                    message: `Berhasil! Ditemukan ${data?.length || 0} row(s)`
                });
            }
        } catch (err: any) {
            testResults.push({
                name: 'Query Tabel "test"',
                status: 'error',
                message: `Exception: ${err.message}`
            });
        }
        setResults([...testResults]);

        // Test 4: Database Query (tabel profiles - dari schema)
        try {
            const { data, error } = await supabase.from('profiles').select('id, email, role').limit(5);

            if (error) {
                if (error.code === '42P01') {
                    testResults.push({
                        name: 'Query Tabel "profiles"',
                        status: 'error',
                        message: 'Tabel belum ada. Deploy schema.sql terlebih dahulu.'
                    });
                } else {
                    testResults.push({
                        name: 'Query Tabel "profiles"',
                        status: 'error',
                        message: `Error: ${error.message}`
                    });
                }
            } else {
                testResults.push({
                    name: 'Query Tabel "profiles"',
                    status: 'success',
                    message: `Berhasil! Ditemukan ${data?.length || 0} user(s)`
                });
            }
        } catch (err: any) {
            testResults.push({
                name: 'Query Tabel "profiles"',
                status: 'error',
                message: `Exception: ${err.message}`
            });
        }
        setResults([...testResults]);

        setIsRunning(false);
    };

    useEffect(() => {
        runTests();
    }, []);

    return (
        <div className="min-h-screen bg-gradient-to-br from-emerald-50 via-white to-amber-50 p-8">
            <div className="max-w-2xl mx-auto">
                <div className="bg-white rounded-2xl shadow-lg p-8">
                    <div className="flex items-center gap-3 mb-6">
                        <Database className="w-8 h-8 text-emerald-600" />
                        <h1 className="text-2xl font-bold text-gray-800">
                            Test Koneksi Supabase
                        </h1>
                    </div>

                    <div className="mb-6 p-4 bg-gray-50 rounded-lg">
                        <p className="text-sm text-gray-600 mb-2">
                            <strong>Project URL:</strong>
                        </p>
                        <code className="text-xs bg-gray-200 px-2 py-1 rounded">
                            {process.env.NEXT_PUBLIC_SUPABASE_URL || 'Tidak dikonfigurasi'}
                        </code>
                    </div>

                    <div className="space-y-4 mb-6">
                        {results.map((result, index) => (
                            <div
                                key={index}
                                className={`flex items-start gap-3 p-4 rounded-lg border ${result.status === 'success'
                                        ? 'bg-green-50 border-green-200'
                                        : result.status === 'error'
                                            ? 'bg-red-50 border-red-200'
                                            : 'bg-gray-50 border-gray-200'
                                    }`}
                            >
                                {result.status === 'success' && (
                                    <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0 mt-0.5" />
                                )}
                                {result.status === 'error' && (
                                    <XCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
                                )}
                                {result.status === 'pending' && (
                                    <Loader2 className="w-5 h-5 text-gray-400 animate-spin flex-shrink-0 mt-0.5" />
                                )}
                                <div>
                                    <p className="font-medium text-gray-800">{result.name}</p>
                                    <p className="text-sm text-gray-600">{result.message}</p>
                                </div>
                            </div>
                        ))}

                        {isRunning && results.length < 4 && (
                            <div className="flex items-center gap-3 p-4 rounded-lg bg-gray-50 border border-gray-200">
                                <Loader2 className="w-5 h-5 text-emerald-600 animate-spin" />
                                <p className="text-gray-600">Menjalankan test...</p>
                            </div>
                        )}
                    </div>

                    <button
                        onClick={runTests}
                        disabled={isRunning}
                        className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                    >
                        <RefreshCw className={`w-4 h-4 ${isRunning ? 'animate-spin' : ''}`} />
                        {isRunning ? 'Testing...' : 'Jalankan Ulang Test'}
                    </button>

                    <div className="mt-8 p-4 bg-amber-50 border border-amber-200 rounded-lg">
                        <p className="text-sm text-amber-800">
                            <strong>💡 Tips:</strong> Jika test gagal, pastikan:
                        </p>
                        <ul className="text-sm text-amber-700 mt-2 list-disc list-inside space-y-1">
                            <li>File <code>.env.local</code> sudah dibuat dengan kredensial yang benar</li>
                            <li>Restart dev server setelah membuat <code>.env.local</code></li>
                            <li>Schema database sudah di-deploy ke Supabase</li>
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import {
    X,
    Loader2,
    UserPlus,
    Mail,
    Key,
    Phone,
    User,
    ChevronDown,
    Eye,
    EyeOff,
    AlertCircle
} from 'lucide-react';
import { ROLE_NAMES, ROLE_COLORS, UserRole, getCurrentUser } from '@/lib/auth';
import { pesantrenService, Pesantren } from '@/lib/services/pesantren';
import { useEffect } from 'react';

// ============================================
// Types
// ============================================

export interface NewUserData {
    name: string;
    email: string;
    password: string;
    role: UserRole | '';
    phone: string;
    pesantrenId: string;
}

interface AddUserModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (userData: NewUserData) => Promise<void>;
}

// ============================================
// Role Options for Dropdown
// ============================================

const ROLE_OPTIONS: { value: UserRole; label: string; description: string }[] = [
    { value: 'admin_keuangan', label: 'Admin Keuangan', description: 'Kelola SPP, pembayaran, keuangan' },
    { value: 'admin_akademik', label: 'Admin Akademik', description: 'Kelola kurikulum dan jadwal' },
    { value: 'kesantrian', label: 'Bagian Kesantrian', description: 'Kelola disiplin dan asrama' },
    { value: 'admin_absensi', label: 'Admin Absensi', description: 'Petugas piket absensi' },
    { value: 'wali_kelas', label: 'Wali Kelas', description: 'Supervisor kelas' },
    { value: 'ustadz', label: 'Ustadz/Guru', description: 'Input nilai dan hafalan' },
    { value: 'wali_santri', label: 'Wali Santri', description: 'Orang tua/wali murid' },
    { value: 'santri', label: 'Santri', description: 'Siswa pesantren' },
];

// ============================================
// Component
// ============================================

export default function AddUserModal({ isOpen, onClose, onSubmit }: AddUserModalProps) {
    const [formData, setFormData] = useState<NewUserData>({
        name: '',
        email: '',
        password: '',
        role: '',
        phone: '',
        pesantrenId: '',
    });

    const [pesantrenList, setPesantrenList] = useState<Pesantren[]>([]);
    const currentUser = getCurrentUser();

    useEffect(() => {
        if (isOpen && currentUser?.role === 'super_admin') {
            pesantrenService.getAll().then(setPesantrenList);
        }
    }, [isOpen, currentUser]);

    const [showPassword, setShowPassword] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [errors, setErrors] = useState<Record<string, string>>({});

    // Validate form
    const validateForm = (): boolean => {
        const newErrors: Record<string, string> = {};

        if (!formData.name.trim()) {
            newErrors.name = 'Nama lengkap wajib diisi';
        } else if (formData.name.trim().length < 3) {
            newErrors.name = 'Nama minimal 3 karakter';
        }

        if (!formData.email.trim()) {
            newErrors.email = 'Email wajib diisi';
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
            newErrors.email = 'Format email tidak valid';
        }

        if (!formData.password) {
            newErrors.password = 'Password wajib diisi';
        } else if (formData.password.length < 6) {
            newErrors.password = 'Password minimal 6 karakter';
        }

        if (!formData.role) {
            newErrors.role = 'Role wajib dipilih';
        }

        if (currentUser?.role === 'super_admin' && !formData.pesantrenId) {
            newErrors.pesantrenId = 'Pesantren wajib dipilih';
        }

        if (formData.phone && !/^[0-9+\-\s()]+$/.test(formData.phone)) {
            newErrors.phone = 'Format nomor telepon tidak valid';
        }

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    // Handle submit
    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!validateForm()) return;

        setIsSubmitting(true);
        try {
            await onSubmit(formData);
            // Reset form on success
            setFormData({ name: '', email: '', password: '', role: '', phone: '', pesantrenId: '' });
            setErrors({});
        } finally {
            setIsSubmitting(false);
        }
    };

    // Handle close
    const handleClose = () => {
        if (!isSubmitting) {
            setFormData({ name: '', email: '', password: '', role: '', phone: '', pesantrenId: '' });
            setErrors({});
            onClose();
        }
    };

    // Generate random password
    const generatePassword = () => {
        const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%';
        let password = '';
        for (let i = 0; i < 12; i++) {
            password += chars.charAt(Math.floor(Math.random() * chars.length));
        }
        setFormData({ ...formData, password });
        setShowPassword(true);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-50 flex items-center justify-center p-4">
            <div className="bg-white dark:bg-neutral-900 rounded-2xl w-full max-w-lg shadow-2xl border border-gray-100 dark:border-white/10 max-h-[90vh] overflow-hidden flex flex-col">
                {/* Header */}
                <div className="p-6 border-b border-gray-100 dark:border-white/5 flex items-center justify-between shrink-0">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-emerald-100 rounded-xl flex items-center justify-center">
                            <UserPlus className="w-5 h-5 text-emerald-600" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-gray-800">Tambah User Baru</h3>
                            <p className="text-sm text-gray-500">Buat akun untuk staff atau santri</p>
                        </div>
                    </div>
                    <button
                        onClick={handleClose}
                        disabled={isSubmitting}
                        className="p-2 hover:bg-gray-100 dark:hover:bg-white/5 rounded-lg disabled:opacity-50 transition-colors"
                    >
                        <X className="w-5 h-5 text-gray-400" />
                    </button>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto">
                    <div className="p-6 space-y-5">
                        {/* Full Name */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">
                                Nama Lengkap <span className="text-red-500">*</span>
                            </label>
                            <div className="relative">
                                <User className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                <input
                                    type="text"
                                    value={formData.name}
                                    onChange={(e) => {
                                        setFormData({ ...formData, name: e.target.value });
                                        if (errors.name) setErrors({ ...errors, name: '' });
                                    }}
                                    placeholder="Masukkan nama lengkap"
                                    disabled={isSubmitting}
                                    className={`w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-black/20 border rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500 transition-all disabled:opacity-50 ${errors.name ? 'border-red-300 bg-red-50 dark:bg-red-500/10' : 'border-gray-200 dark:border-white/10'
                                        }`}
                                />
                            </div>
                            {errors.name && (
                                <p className="mt-1.5 text-sm text-red-600 flex items-center gap-1">
                                    <AlertCircle className="w-4 h-4" />
                                    {errors.name}
                                </p>
                            )}
                        </div>

                        {/* Email */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">
                                Email <span className="text-red-500">*</span>
                            </label>
                            <div className="relative">
                                <Mail className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                <input
                                    type="email"
                                    value={formData.email}
                                    onChange={(e) => {
                                        setFormData({ ...formData, email: e.target.value });
                                        if (errors.email) setErrors({ ...errors, email: '' });
                                    }}
                                    placeholder="email@pesantren.com"
                                    disabled={isSubmitting}
                                    className={`w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-black/20 border rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500 transition-all disabled:opacity-50 ${errors.email ? 'border-red-300 bg-red-50 dark:bg-red-500/10' : 'border-gray-200 dark:border-white/10'
                                        }`}
                                />
                            </div>
                            {errors.email && (
                                <p className="mt-1.5 text-sm text-red-600 flex items-center gap-1">
                                    <AlertCircle className="w-4 h-4" />
                                    {errors.email}
                                </p>
                            )}
                        </div>

                        {/* Password */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">
                                Password <span className="text-red-500">*</span>
                            </label>
                            <div className="relative">
                                <Key className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                <input
                                    type={showPassword ? 'text' : 'password'}
                                    value={formData.password}
                                    onChange={(e) => {
                                        setFormData({ ...formData, password: e.target.value });
                                        if (errors.password) setErrors({ ...errors, password: '' });
                                    }}
                                    placeholder="Minimal 6 karakter"
                                    disabled={isSubmitting}
                                    className={`w-full pl-10 pr-20 py-3 bg-gray-50 dark:bg-black/20 border rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500 transition-all disabled:opacity-50 ${errors.password ? 'border-red-300 bg-red-50 dark:bg-red-500/10' : 'border-gray-200 dark:border-white/10'
                                        }`}
                                />
                                <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1">
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        className="p-1.5 hover:bg-gray-200 rounded-lg text-gray-400"
                                    >
                                        {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                    </button>
                                </div>
                            </div>
                            <div className="flex items-center justify-between mt-1.5">
                                {errors.password ? (
                                    <p className="text-sm text-red-600 flex items-center gap-1">
                                        <AlertCircle className="w-4 h-4" />
                                        {errors.password}
                                    </p>
                                ) : (
                                    <span />
                                )}
                                <button
                                    type="button"
                                    onClick={generatePassword}
                                    disabled={isSubmitting}
                                    className="text-sm text-emerald-600 hover:text-emerald-700 font-medium disabled:opacity-50"
                                >
                                    Generate Password
                                </button>
                            </div>
                        </div>

                        {/* Role Selection */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">
                                Role <span className="text-red-500">*</span>
                            </label>
                            <div className="relative">
                                <select
                                    value={formData.role}
                                    onChange={(e) => {
                                        setFormData({ ...formData, role: e.target.value as UserRole });
                                        if (errors.role) setErrors({ ...errors, role: '' });
                                    }}
                                    disabled={isSubmitting}
                                    className={`w-full px-4 py-3 bg-gray-50 dark:bg-neutral-800 border rounded-xl appearance-none focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500 transition-all dark:text-white disabled:opacity-50 ${errors.role ? 'border-red-300 bg-red-50 dark:bg-red-500/10' : 'border-gray-200 dark:border-white/10'
                                        }`}
                                >
                                    <option value="">-- Pilih Role --</option>
                                    {ROLE_OPTIONS.map(role => (
                                        <option key={role.value} value={role.value}>
                                            {role.label}
                                        </option>
                                    ))}
                                </select>
                                <ChevronDown className="w-5 h-5 text-gray-400 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />
                            </div>
                            {errors.role && (
                                <p className="mt-1.5 text-sm text-red-600 flex items-center gap-1">
                                    <AlertCircle className="w-4 h-4" />
                                    {errors.role}
                                </p>
                            )}
                            {formData.role && (
                                <div className="mt-2 p-3 bg-gray-50 dark:bg-white/5 rounded-lg border border-gray-200 dark:border-white/10">
                                    <p className="text-sm text-gray-600 dark:text-gray-400">
                                        {ROLE_OPTIONS.find(r => r.value === formData.role)?.description}
                                    </p>
                                </div>
                            )}
                        </div>

                        {/* Pesantren Selection (For Super Admin only) */}
                        {currentUser?.role === 'super_admin' && (
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                                    Unit Pesantren <span className="text-red-500">*</span>
                                </label>
                                <div className="relative">
                                    <select
                                        value={formData.pesantrenId}
                                        onChange={(e) => {
                                            setFormData({ ...formData, pesantrenId: e.target.value });
                                            if (errors.pesantrenId) setErrors({ ...errors, pesantrenId: '' });
                                        }}
                                        disabled={isSubmitting}
                                        className={`w-full px-4 py-3 bg-gray-50 dark:bg-neutral-800 border rounded-xl appearance-none focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500 transition-all dark:text-white disabled:opacity-50 ${errors.pesantrenId ? 'border-red-300 bg-red-50 dark:bg-red-500/10' : 'border-gray-200 dark:border-white/10'
                                            }`}
                                    >
                                        <option value="">-- Pilih Pesantren --</option>
                                        {pesantrenList.map(p => (
                                            <option key={p.id} value={p.id}>
                                                {p.name}
                                            </option>
                                        ))}
                                    </select>
                                    <ChevronDown className="w-5 h-5 text-gray-400 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />
                                </div>
                                {errors.pesantrenId && (
                                    <p className="mt-1.5 text-sm text-red-600 flex items-center gap-1">
                                        <AlertCircle className="w-4 h-4" />
                                        {errors.pesantrenId}
                                    </p>
                                )}
                            </div>
                        )}

                        {/* Phone (Optional) */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">
                                Nomor Telepon <span className="text-gray-400">(Opsional)</span>
                            </label>
                            <div className="relative">
                                <Phone className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                <input
                                    type="tel"
                                    value={formData.phone}
                                    onChange={(e) => {
                                        setFormData({ ...formData, phone: e.target.value });
                                        if (errors.phone) setErrors({ ...errors, phone: '' });
                                    }}
                                    placeholder="08xxxxxxxxxx"
                                    disabled={isSubmitting}
                                    className={`w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-black/20 border rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500 transition-all disabled:opacity-50 ${errors.phone ? 'border-red-300 bg-red-50 dark:bg-red-500/10' : 'border-gray-200 dark:border-white/10'
                                        }`}
                                />
                            </div>
                            {errors.phone && (
                                <p className="mt-1.5 text-sm text-red-600 flex items-center gap-1">
                                    <AlertCircle className="w-4 h-4" />
                                    {errors.phone}
                                </p>
                            )}
                        </div>
                    </div>

                    {/* Footer */}
                    <div className="p-6 border-t border-gray-100 dark:border-white/5 flex gap-3 shrink-0 bg-gray-50 dark:bg-neutral-900/50">
                        <button
                            type="button"
                            onClick={handleClose}
                            disabled={isSubmitting}
                            className="flex-1 py-3 border border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-300 font-medium rounded-xl hover:bg-gray-100 dark:hover:bg-white/5 transition-all disabled:opacity-50"
                        >
                            Batal
                        </button>
                        <button
                            type="submit"
                            disabled={isSubmitting}
                            className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl transition-colors flex items-center justify-center gap-2 disabled:opacity-70 shadow-lg shadow-emerald-500/30"
                        >
                            {isSubmitting ? (
                                <>
                                    <Loader2 className="w-5 h-5 animate-spin" />
                                    Membuat Akun...
                                </>
                            ) : (
                                <>
                                    <UserPlus className="w-5 h-5" />
                                    Buat Akun
                                </>
                            )}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { X, Save, School, Loader2, Users } from 'lucide-react';
import { academicYearService } from '@/lib/services';
import type { ClassInsert, ClassUpdate } from '@/types/database.types';

interface ClassModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: ClassInsert | ClassUpdate) => Promise<void>;
    classData?: any; // If editing
}

export default function ClassModal({ isOpen, onClose, onSubmit, classData }: ClassModalProps) {
    const [formData, setFormData] = useState({
        name: '',
        grade_level: 7,
        homeroom_teacher_id: '',
        academic_year_id: '',
        capacity: 40,
    });

    const [teachers, setTeachers] = useState<any[]>([]);
    const [academicYears, setAcademicYears] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);

    useEffect(() => {
        if (isOpen) {
            loadOptions();
            if (classData) {
                setFormData({
                    name: classData.name || '',
                    grade_level: classData.grade_level || 7,
                    homeroom_teacher_id: classData.homeroom_teacher_id || '',
                    academic_year_id: classData.academic_year_id || '',
                    capacity: classData.capacity || 40,
                });
            } else {
                setFormData({
                    name: '',
                    grade_level: 7,
                    homeroom_teacher_id: '',
                    academic_year_id: '',
                    capacity: 40,
                });
            }
        }
    }, [isOpen, classData]);

    const loadOptions = async () => {
        try {
            setIsLoading(true);
            const { teachersService } = await import('@/lib/services');
            const [fetchedTeachers, fetchedYears] = await Promise.all([
                teachersService.getAll({ isActive: true }),
                academicYearService.getAll()
            ]);

            // Use teachers from teachers table (correct IDs)
            setTeachers(fetchedTeachers);
            setAcademicYears(fetchedYears);

            // Default academic year if creating new
            if (!classData && fetchedYears.length > 0) {
                const activeYear = fetchedYears.find(y => y.is_active);
                if (activeYear) {
                    setFormData(prev => ({ ...prev, academic_year_id: activeYear.id }));
                }
            }
        } catch (error) {
            console.error('Error loading modal options:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);
        try {
            // Prepare data - only include non-empty values for optional fields
            const dataToSend: any = {
                name: formData.name,
                grade_level: formData.grade_level,
                capacity: formData.capacity || 40,
            };

            // Only add optional fields if they have values
            if (formData.homeroom_teacher_id) {
                dataToSend.homeroom_teacher_id = formData.homeroom_teacher_id;
            }
            if (formData.academic_year_id) {
                dataToSend.academic_year_id = formData.academic_year_id;
            }

            console.log('Submitting class data:', dataToSend);

            await onSubmit(dataToSend);
            onClose();
        } catch (error: any) {
            console.error('Error submitting class:', error);
            const msg = error?.message || error?.details || 'Unknown error';
            alert(`Gagal menyimpan data kelas: ${msg}`);
        } finally {
            setIsSubmitting(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
                {/* Header */}
                <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-gray-50/50">
                    <div className="flex items-center gap-3">
                        <div className="p-2.5 bg-blue-600 rounded-xl">
                            <School className="w-5 h-5 text-white" />
                        </div>
                        <div>
                            <h2 className="text-xl font-bold text-gray-800">{classData ? 'Edit Kelas' : 'Tambah Kelas Baru'}</h2>
                            <p className="text-xs text-gray-500 font-medium">Lengkapi informasi rombongan belajar</p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 hover:bg-white hover:shadow-md rounded-xl text-gray-400 hover:text-gray-600 transition-all"
                    >
                        <X className="w-6 h-6" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-5">
                    <div className="grid grid-cols-2 gap-4">
                        <div className="col-span-1">
                            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Nama Kelas</label>
                            <input
                                required
                                type="text"
                                placeholder="Misal: 7A, 10-IPA"
                                value={formData.name}
                                onChange={e => setFormData({ ...formData, name: e.target.value })}
                                className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold"
                            />
                        </div>
                        <div className="col-span-1">
                            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Jenjang (Grade)</label>
                            <select
                                required
                                value={formData.grade_level}
                                onChange={e => setFormData({ ...formData, grade_level: parseInt(e.target.value) })}
                                className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold"
                            >
                                {[7, 8, 9, 10, 11, 12].map(lvl => (
                                    <option key={lvl} value={lvl}>Kelas {lvl}</option>
                                ))}
                            </select>
                        </div>
                    </div>

                    <div>
                        <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Wali Kelas</label>
                        <select
                            required
                            value={formData.homeroom_teacher_id}
                            onChange={e => setFormData({ ...formData, homeroom_teacher_id: e.target.value })}
                            className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold"
                        >
                            <option value="">-- Pilih Wali Kelas --</option>
                            {teachers.map(t => (
                                <option key={t.id} value={t.id}>{t.name}</option>
                            ))}
                        </select>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Tahun Ajaran</label>
                            <select
                                required
                                value={formData.academic_year_id}
                                onChange={e => setFormData({ ...formData, academic_year_id: e.target.value })}
                                className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold"
                            >
                                <option value="">-- Pilih T.A --</option>
                                {academicYears.map(y => (
                                    <option key={y.id} value={y.id}>{y.name}</option>
                                ))}
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Kapasitas Santri</label>
                            <div className="relative">
                                <Users className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                                <input
                                    required
                                    type="number"
                                    min="1"
                                    value={formData.capacity}
                                    onChange={e => setFormData({ ...formData, capacity: parseInt(e.target.value) })}
                                    className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold"
                                />
                            </div>
                        </div>
                    </div>

                    <div className="pt-4 flex gap-3">
                        <button
                            type="button"
                            onClick={onClose}
                            className="flex-1 py-3.5 bg-gray-100 text-gray-600 font-bold rounded-2xl hover:bg-gray-200 transition-all uppercase tracking-widest text-xs"
                        >
                            Batal
                        </button>
                        <button
                            type="submit"
                            disabled={isSubmitting || isLoading}
                            className="flex-[2] py-3.5 bg-blue-600 text-white font-bold rounded-2xl hover:bg-blue-700 shadow-lg shadow-blue-500/30 transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? (
                                <Loader2 className="w-4 h-4 animate-spin" />
                            ) : (
                                <Save className="w-4 h-4" />
                            )}
                            {classData ? 'Simpan Perubahan' : 'Tambah Kelas'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { X, Save, Home, Loader2, Users, Building2, User as UserIcon } from 'lucide-react';
import { dormitoriesService, usersService } from '@/lib/services';

interface DormModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => Promise<void>;
    dormData?: any; // If editing
}

export default function DormModal({ isOpen, onClose, onSubmit, dormData }: DormModalProps) {
    const [formData, setFormData] = useState({
        name: '',
        building: '',
        capacity: 10,
        supervisor_id: '',
    });

    const [supervisors, setSupervisors] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);

    useEffect(() => {
        if (isOpen) {
            loadOptions();
            if (dormData) {
                setFormData({
                    name: dormData.name || '',
                    building: (dormData as any).building || '',
                    capacity: dormData.capacity || 10,
                    supervisor_id: dormData.supervisor_id || '',
                });
            } else {
                setFormData({
                    name: '',
                    building: '',
                    capacity: 10,
                    supervisor_id: '',
                });
            }
        }
    }, [isOpen, dormData]);

    const loadOptions = async () => {
        try {
            setIsLoading(true);
            // Fetch potential supervisors (role = 'musyrif' or 'ustadz' or 'kesantrian')
            const filteredSupervisors = await usersService.getPotentialSupervisors();
            setSupervisors(filteredSupervisors);
        } catch (error) {
            console.error('Error loading supervisors:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);
        try {
            await onSubmit(formData);
            onClose();
        } catch (error) {
            console.error('Error submitting dorm:', error);
            alert('Gagal menyimpan data asrama.');
        } finally {
            setIsSubmitting(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
