                            disabled={isSubmitting || isLoading}
                            className="flex-[2] py-3.5 bg-orange-600 text-white font-bold rounded-2xl hover:bg-orange-700 shadow-lg shadow-orange-500/30 transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? (
                                <Loader2 className="w-4 h-4 animate-spin" />
                            ) : (
                                <Save className="w-4 h-4" />
                            )}
                            {dormData ? 'Simpan Perubahan' : 'Tambah Kamar'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import {
    X,
    Loader2,
    Edit,
    Mail,
    Phone,
    User,
    ChevronDown,
    AlertCircle,
    Save
} from 'lucide-react';
import { ROLE_NAMES, UserRole } from '@/lib/auth';

interface EditUserModalProps {
    isOpen: boolean;
    user: any;
    onClose: () => void;
    onSubmit: (userId: string, data: { name: string; role: UserRole; phone: string }) => Promise<void>;
}

const ROLE_OPTIONS: { value: UserRole; label: string; description: string }[] = [
    { value: 'admin_keuangan', label: 'Admin Keuangan', description: 'Kelola SPP, pembayaran, keuangan' },
    { value: 'admin_akademik', label: 'Admin Akademik', description: 'Kelola kurikulum dan jadwal' },
    { value: 'kesantrian', label: 'Bagian Kesantrian', description: 'Kelola disiplin dan asrama' },
    { value: 'admin_absensi', label: 'Admin Absensi', description: 'Petugas piket absensi' },
    { value: 'wali_kelas', label: 'Wali Kelas', description: 'Supervisor kelas' },
    { value: 'ustadz', label: 'Ustadz/Guru', description: 'Input nilai dan hafalan' },
    { value: 'wali_santri', label: 'Wali Santri', description: 'Orang tua/wali murid' },
    { value: 'santri', label: 'Santri', description: 'Siswa pesantren' },
];

export default function EditUserModal({ isOpen, user, onClose, onSubmit }: EditUserModalProps) {
    const [formData, setFormData] = useState({
        name: '',
        role: '' as UserRole,
        phone: '',
    });

    const [isSubmitting, setIsSubmitting] = useState(false);
    const [errors, setErrors] = useState<Record<string, string>>({});

    useEffect(() => {
        if (user) {
            setFormData({
                name: user.name || '',
                role: user.role as UserRole || 'santri',
                phone: user.phone || '',
            });
        }
    }, [user]);

    const validateForm = (): boolean => {
        const newErrors: Record<string, string> = {};
        if (!formData.name.trim()) newErrors.name = 'Nama lengkap wajib diisi';
        if (!formData.role) newErrors.role = 'Role wajib dipilih';
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!validateForm()) return;

        setIsSubmitting(true);
        try {
            await onSubmit(user.id, formData);
            onClose();
        } finally {
            setIsSubmitting(false);
        }
    };

    if (!isOpen || !user) return null;

    return (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-50 flex items-center justify-center p-4">
            <div className="bg-white dark:bg-neutral-900 rounded-2xl w-full max-w-lg shadow-2xl border border-gray-100 dark:border-white/10 max-h-[90vh] overflow-hidden flex flex-col">
                <div className="p-6 border-b border-gray-100 dark:border-white/5 flex items-center justify-between shrink-0">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-purple-100 dark:bg-purple-500/10 rounded-xl flex items-center justify-center">
                            <Edit className="w-5 h-5 text-purple-600" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-gray-800 dark:text-white">Edit User</h3>
                            <p className="text-sm text-gray-500 dark:text-gray-400">{user.email}</p>
                        </div>
                    </div>
                    <button onClick={onClose} disabled={isSubmitting} className="p-2 hover:bg-gray-100 dark:hover:bg-white/5 rounded-lg transition-colors">
                        <X className="w-5 h-5 text-gray-400" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto">
                    <div className="p-6 space-y-5">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Nama Lengkap</label>
                            <div className="relative">
                                <User className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                <input
                                    type="text"
                                    value={formData.name}
                                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                    className={`w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-black/20 border rounded-xl focus:ring-2 focus:ring-purple-500/30 dark:text-white transition-all ${errors.name ? 'border-red-300 dark:border-red-500/50' : 'border-gray-200 dark:border-white/10'}`}
                                />
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Role System</label>
                            <div className="relative">
                                <select
                                    value={formData.role}
                                    onChange={(e) => setFormData({ ...formData, role: e.target.value as UserRole })}
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-neutral-800 border border-gray-200 dark:border-white/10 rounded-xl appearance-none focus:ring-2 focus:ring-purple-500/30 dark:text-white"
                                >
                                    {ROLE_OPTIONS.map(role => (
                                        <option key={role.value} value={role.value}>{role.label}</option>
                                    ))}
                                </select>
                                <ChevronDown className="w-5 h-5 text-gray-400 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />
                            </div>
                            <p className="mt-2 text-xs text-gray-500 dark:text-gray-400 p-2 bg-gray-50 dark:bg-white/5 rounded border border-gray-100 dark:border-white/10">
                                {ROLE_OPTIONS.find(r => r.value === formData.role)?.description}
                            </p>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Nomor Telepon</label>
                            <div className="relative">
                                <Phone className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                <input
                                    type="tel"
                                    value={formData.phone}
                                    onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                                    placeholder="08xxxxxxxxxx"
                                    className="w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:ring-2 focus:ring-purple-500/30 dark:text-white"
                                />
                            </div>
                        </div>
                    </div>

                    <div className="p-6 border-t border-gray-100 dark:border-white/5 flex gap-3 bg-gray-50 dark:bg-neutral-900/50">
                        <button
                            type="button"
                            onClick={onClose}
                            disabled={isSubmitting}
                            className="flex-1 py-3 border border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-300 font-medium rounded-xl hover:bg-gray-100 dark:hover:bg-white/5 transition-all"
                        >
                            Batal
                        </button>
                        <button
                            type="submit"
                            disabled={isSubmitting}
                            className="flex-1 py-3 bg-purple-600 hover:bg-purple-700 text-white font-semibold rounded-xl flex items-center justify-center gap-2 shadow-lg shadow-purple-500/30 transition-all active:scale-95"
                        >
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin" /> : <Save className="w-5 h-5" />}
                            Simpan Perubahan
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { X, Save, ShieldCheck, Loader2, User as UserIcon, Calendar, FileText, Info } from 'lucide-react';
import { studentsService } from '@/lib/services';

interface PermissionModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => Promise<void>;
}

export default function PermissionModal({ isOpen, onClose, onSubmit }: PermissionModalProps) {
    const [formData, setFormData] = useState({
        student_id: '',
        permission_type: 'pulang' as 'pulang' | 'keluar' | 'sakit' | 'kegiatan',
        start_date: new Date().toISOString().slice(0, 16), // datetime-local format
        end_date: '',
        reason: '',
        is_independent: false,
        picker_name: '',
    });

    const [students, setStudents] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);

    useEffect(() => {
        if (isOpen) {
            loadOptions();
            // Reset form
            const now = new Date();
            const tomorrow = new Date(now);
            tomorrow.setDate(tomorrow.getDate() + 1);

            setFormData({
                student_id: '',
                permission_type: 'pulang',
                start_date: now.toISOString().slice(0, 16),
                end_date: tomorrow.toISOString().slice(0, 16),
                reason: '',
                is_independent: false,
                picker_name: '',
            });
        }
    }, [isOpen]);

    const loadOptions = async () => {
        try {
            setIsLoading(true);
            const fetchedStudents = await studentsService.getAll({ status: 'active' });
            setStudents(fetchedStudents);
        } catch (error) {
            console.error('Error loading students:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);
        try {
            // Logic to append picker info or [MANDIRI] to reason
            let finalReason = formData.reason;
            if (formData.is_independent) {
                finalReason = `[MANDIRI] ${finalReason}`;
            } else if (formData.picker_name) {
                finalReason = `[Dijemput: ${formData.picker_name}] ${finalReason}`;
            }

            await onSubmit({
                student_id: formData.student_id,
                permission_type: formData.permission_type,
                start_date: new Date(formData.start_date).toISOString(),
                end_date: new Date(formData.end_date).toISOString(),
                reason: finalReason
            });
            onClose();
        } catch (error) {
            console.error('Error submitting permission:', error);
            alert('Gagal mencatat izin.');
        } finally {
            setIsSubmitting(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
                {/* Header */}
                <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-indigo-50/50">
                    <div className="flex items-center gap-3">
                        <div className="p-2.5 bg-indigo-600 rounded-xl">
                            <ShieldCheck className="w-5 h-5 text-white" />
                        </div>
                        <div>
                            <h2 className="text-xl font-bold text-gray-800">Catat Izin Manual</h2>
                            <p className="text-xs text-gray-500 font-medium">Input izin walk-in / mendadak</p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 hover:bg-white hover:shadow-md rounded-xl text-gray-400 hover:text-gray-600 transition-all"
                    >
                        <X className="w-6 h-6" />
                    </button>
                </div>

                <div className="p-6 space-y-5 overflow-y-auto max-h-[80vh]">
                    <form onSubmit={handleSubmit} className="space-y-4">
                        {/* Student Selection */}
                        <div>
                            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Nama Santri</label>
                            <div className="relative">
                                <UserIcon className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                                <select
                                    required
                                    value={formData.student_id}
                                    onChange={e => setFormData({ ...formData, student_id: e.target.value })}
                                    className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 text-gray-900 font-bold appearance-none"
                                >
                                    <option value="">Pilih Santri</option>
                                    {students.map(s => (
                                        <option key={s.id} value={s.id}>{s.name} ({s.class?.name || '-'})</option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        {/* Permission Type */}
                        <div>
                            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Jenis Izin</label>
                            <div className="flex gap-2 p-1.5 bg-gray-50 rounded-xl border border-gray-200">
                                {['pulang', 'keluar', 'sakit', 'kegiatan'].map((type) => (
                                    <button
                                        key={type}
                                        type="button"
                                        onClick={() => setFormData({ ...formData, permission_type: type as any })}
                                        className={`flex-1 py-2 rounded-lg text-xs font-bold capitalize transition-all flex items-center justify-center gap-1 ${formData.permission_type === type
                                            ? 'bg-indigo-600 text-white shadow-md ring-1 ring-indigo-600'
                                            : 'bg-white text-gray-400 hover:text-gray-600 border border-gray-200'
                                            }`}
                                    >
                                        {formData.permission_type === type && <ShieldCheck className="w-3 h-3" />}
                                        {type}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Dates */}
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Mulai</label>
                                <input
                                    required
                                    type="datetime-local"
                                    value={formData.start_date}
                                    onChange={e => setFormData({ ...formData, start_date: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 text-gray-900 font-bold text-xs"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Selesai</label>
                                <input
                                    required
                                    type="datetime-local"
                                    value={formData.end_date}
                                    onChange={e => setFormData({ ...formData, end_date: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 text-gray-900 font-bold text-xs"
                                />
                            </div>
                        </div>

                        {/* Pickup Info */}
                        <div className="bg-orange-50 p-4 rounded-2xl border border-orange-100">
                            <div className="flex items-center gap-2 mb-3">
                                <Info className="w-4 h-4 text-orange-500" />
                                <span className="text-xs font-bold text-orange-700">Informasi Penjemputan</span>
                            </div>
                            <label className="flex items-center gap-3 mb-3 cursor-pointer">
                                <div className={`w-5 h-5 rounded-md border flex items-center justify-center transition-colors ${formData.is_independent ? 'bg-orange-500 border-orange-500' : 'bg-white border-gray-300'}`}>
                                    {formData.is_independent && <div className="w-2.5 h-2.5 bg-white rounded-sm" />}
                                </div>
                                <input
                                    type="checkbox"
                                    className="hidden"
                                    checked={formData.is_independent}
                                    onChange={e => setFormData({ ...formData, is_independent: e.target.checked })}
                                />
                                <span className="text-sm font-medium text-gray-700">Pulang Sendiri / Mandiri</span>
                            </label>

                            {!formData.is_independent && (
                                <input
                                    type="text"
                                    placeholder="Nama Penjemput (cth: Pak Budi - Om)"
                                    value={formData.picker_name}
                                    onChange={e => setFormData({ ...formData, picker_name: e.target.value })}
                                    className="w-full px-4 py-2 bg-white border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500/20 text-sm"
                                />
                            )}
                        </div>

                        {/* Reason */}
                        <div>
                            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Alasan</label>
                            <textarea
                                required
                                placeholder="Jelaskan alasan izin..."
                                value={formData.reason}
                                onChange={e => setFormData({ ...formData, reason: e.target.value })}
                                className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 text-gray-900 font-medium h-24 text-sm"
                            />
                        </div>

                        {/* Actions */}
                        <div className="pt-2 flex gap-3">
                            <button
                                type="button"
                                onClick={onClose}
                                className="flex-1 py-3.5 bg-gray-100 text-gray-600 font-bold rounded-2xl hover:bg-gray-200 transition-all uppercase tracking-widest text-xs"
                            >
                                Batal
                            </button>
                            <button
                                type="submit"
                                disabled={isSubmitting || isLoading}
                                className="flex-[2] py-3.5 bg-indigo-600 text-white font-bold rounded-2xl hover:bg-indigo-700 shadow-lg shadow-indigo-500/30 transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-2"
                            >
                                {isSubmitting ? (
                                    <Loader2 className="w-4 h-4 animate-spin" />
                                ) : (
                                    <Save className="w-4 h-4" />
                                )}
                                Simpan Izin
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import { KeyRound, Loader2, X, Eye, EyeOff, CheckCircle2 } from 'lucide-react';

interface ResetPasswordModalProps {
    isOpen: boolean;
    user: { id: string; name: string; email: string } | null;
    onClose: () => void;
    onSuccess: () => void;
    adminId: string;
}

export default function ResetPasswordModal({
    isOpen,
    user,
    onClose,
    onSuccess,
    adminId
}: ResetPasswordModalProps) {
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    if (!isOpen || !user) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        // Validations
        if (newPassword.length < 6) {
            setError('Password harus minimal 6 karakter');
            return;
        }

        if (newPassword !== confirmPassword) {
            setError('Password dan konfirmasi tidak cocok');
            return;
        }

        setIsLoading(true);

        try {
            const response = await fetch('/api/admin/reset-password', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    userId: user.id,
                    newPassword,
                    adminId
                })
            });

            const result = await response.json();

            if (!result.success) {
                setError(result.error || 'Gagal mereset password');
                setIsLoading(false);
                return;
            }

            // Success
            setNewPassword('');
            setConfirmPassword('');
            onSuccess();
            onClose();

        } catch (err: any) {
            setError(err.message || 'Terjadi kesalahan');
        } finally {
            setIsLoading(false);
        }
    };

    const handleQuickSet = (password: string) => {
        setNewPassword(password);
        setConfirmPassword(password);
    };

    return (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-50 flex items-center justify-center p-4 overflow-y-auto transition-all duration-300">
            <div className="bg-white dark:bg-neutral-900 rounded-3xl w-full max-w-md shadow-2xl border border-gray-100 dark:border-white/10 overflow-hidden max-h-[90vh] overflow-y-auto my-4 transition-all scale-100">
                {/* Header */}
                <div className="p-6 border-b border-gray-100 dark:border-white/5 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="w-12 h-12 bg-amber-100 dark:bg-amber-500/10 rounded-xl flex items-center justify-center">
                            <KeyRound className="w-6 h-6 text-amber-600 dark:text-amber-500" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-gray-800 dark:text-white">Reset Password</h3>
                            <p className="text-sm text-gray-500 dark:text-gray-400">{user.name}</p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 hover:bg-gray-100 dark:hover:bg-white/5 rounded-lg transition-colors"
                    >
                        <X className="w-5 h-5 text-gray-400" />
                    </button>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    <div className="bg-gray-50 dark:bg-black/20 p-4 rounded-xl border border-gray-100 dark:border-white/5">
                        <p className="text-sm text-gray-600 dark:text-gray-400">
                            <strong className="text-gray-800 dark:text-gray-200">Email:</strong> {user.email}
                        </p>
                    </div>

                    {/* Quick Set Buttons */}
                    <div>
                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-2">
                            Password Cepat
                        </label>
                        <div className="flex flex-wrap gap-2">
                            {['guru123', 'password123', 'santri123', 'admin123'].map(pwd => (
                                <button
                                    key={pwd}
                                    type="button"
                                    onClick={() => handleQuickSet(pwd)}
                                    className="px-3 py-1.5 bg-gray-100 dark:bg-neutral-800 hover:bg-purple-100 dark:hover:bg-purple-500/20 text-gray-700 dark:text-gray-300 hover:text-purple-700 dark:hover:text-purple-400 text-sm font-medium rounded-lg transition-colors border border-transparent dark:border-white/5"
                                >
                                    {pwd}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* New Password */}
                    <div>
                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-2">
                            Password Baru
                        </label>
                        <div className="relative">
                            <input
                                type={showPassword ? 'text' : 'password'}
                                value={newPassword}
                                onChange={(e) => setNewPassword(e.target.value)}
                                placeholder="Minimal 6 karakter"
                                className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 focus:border-purple-500 pr-12 dark:text-white transition-all"
                                required
                            />
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-gray-400 hover:text-gray-600"
                            >
                                {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                            </button>
                        </div>
                    </div>

                    {/* Confirm Password */}
                    <div>
                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-2">
                            Konfirmasi Password
                        </label>
                        <input
                            type={showPassword ? 'text' : 'password'}
                            value={confirmPassword}
                            onChange={(e) => setConfirmPassword(e.target.value)}
                            placeholder="Ulangi password"
                            className={`w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 dark:text-white transition-all ${confirmPassword && confirmPassword !== newPassword
                                ? 'border-red-300 dark:border-red-500/50 focus:border-red-500'
                                : 'border-gray-200 dark:border-white/10 focus:border-purple-500'
                                }`}
                            required
                        />
                        {confirmPassword && confirmPassword === newPassword && (
                            <p className="mt-1 text-xs text-emerald-600 flex items-center gap-1">
                                <CheckCircle2 className="w-3 h-3" /> Password cocok
                            </p>
                        )}
                    </div>

                    {/* Error */}
                    {error && (
                        <div className="p-3 bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-xl text-sm text-red-600 dark:text-red-400">
                            {error}
                        </div>
                    )}

                    {/* Actions */}
                    <div className="flex gap-3 pt-2">
                        <button
                            type="button"
                            onClick={onClose}
                            className="flex-1 py-3 border border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-300 font-medium rounded-xl hover:bg-gray-100 dark:hover:bg-white/5 transition-all"
                        >
                            Batal
                        </button>
                        <button
                            type="submit"
                            disabled={isLoading || !newPassword || !confirmPassword}
                            className="flex-1 py-3 bg-purple-600 hover:bg-purple-700 text-white font-semibold rounded-xl transition-all flex items-center justify-center gap-2 disabled:opacity-50 shadow-lg shadow-purple-500/20 active:scale-95"
                        >
                            {isLoading ? (
                                <>
                                    <Loader2 className="w-5 h-5 animate-spin" />
                                    Mereset...
                                </>
                            ) : (
                                <>
                                    <KeyRound className="w-5 h-5" />
                                    Reset Password
                                </>
                            )}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { X, Save, Users, Loader2, User as UserIcon, Mail, Phone, MapPin, Calendar } from 'lucide-react';
import { classesService } from '@/lib/services/classes';

interface SantriModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => Promise<void>;
    santriData?: any;
}

export default function SantriModal({ isOpen, onClose, onSubmit, santriData }: SantriModalProps) {
    const [formData, setFormData] = useState({
        name: '',
        nis: '',
        gender: 'L' as 'L' | 'P',
        class_id: '',
        birth_place: '',
        birth_date: '',
        address: '',
        parent_name: '',
        parent_phone: '',
        status: 'active',
        email: '', // Email for student account
    });

    const [classes, setClasses] = useState<any[]>([]);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isLoadingClasses, setIsLoadingClasses] = useState(false);
    const [existingEmail, setExistingEmail] = useState(''); // Track existing email for edit mode

    useEffect(() => {
        if (isOpen) {
            fetchClasses();
            if (santriData) {
                // Load existing email from profiles if available
                loadExistingEmail(santriData.user_id || santriData.id);

                setFormData({
                    name: santriData.name || '',
                    nis: santriData.nis || '',
                    gender: santriData.gender || 'L',
                    class_id: santriData.class_id || '',
                    birth_place: santriData.birth_place || '',
                    birth_date: santriData.birth_date || '',
                    address: santriData.address || '',
                    parent_name: santriData.parent_name || '',
                    parent_phone: santriData.parent_phone || '',
                    status: santriData.status || 'active',
                    email: santriData.email || '',
                });
            } else {
                setExistingEmail('');
                setFormData({
                    name: '',
                    nis: '',
                    gender: 'L',
                    class_id: '',
                    birth_place: '',
                    birth_date: '',
                    address: '',
                    parent_name: '',
                    parent_phone: '',
                    status: 'active',
                    email: '',
                });
            }
        }
    }, [isOpen, santriData]);

    // Load email from profiles table for existing student
    const loadExistingEmail = async (userId: string) => {
        if (!userId) return;
        try {
            const { supabase } = await import('@/lib/supabase');
            const { data } = await supabase
                .from('profiles')
                .select('email')
                .eq('id', userId)
                .single();

            if (data?.email) {
                setExistingEmail(data.email);
                setFormData(prev => ({ ...prev, email: data.email }));
            }
        } catch (e) {
            console.warn('Could not load existing email:', e);
        }
    };

    const fetchClasses = async () => {
        setIsLoadingClasses(true);
        try {
            const data = await classesService.getAll();
            setClasses(data);
        } catch (error) {
            console.error('Error fetching classes:', error);
        } finally {
            setIsLoadingClasses(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);
        try {
            const submitData = { ...formData };

            // Only auto-generate email for NEW students (not editing)
            if (!santriData) {
                // New student - auto-generate if empty
                submitData.email = formData.email || `${formData.nis.toLowerCase().replace(/[^a-z0-9]/g, '')}@santri.pesantren.id`;
            } else {
                // Editing existing student
                if (!formData.email && existingEmail) {
                    // If form is empty but there's existing email, keep the existing one
                    submitData.email = existingEmail;
                }
                // If form has value, use that value (user intentionally changed it)
            }

            await onSubmit(submitData);
            onClose();
        } catch (error) {
            console.error('Error submitting santri:', error);
            alert('Gagal menyimpan data santri.');
        } finally {
            setIsSubmitting(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white w-full max-w-3xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
                {/* Header */}
                <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-gray-50/50">
                    <div className="flex items-center gap-3">
                        <div className="p-2.5 bg-blue-600 rounded-xl">
                            <Users className="w-5 h-5 text-white" />
                        </div>
                        <div>
                            <h2 className="text-xl font-bold text-gray-800">{santriData ? 'Edit Data Santri' : 'Tambah Santri Baru'}</h2>
                            <p className="text-xs text-gray-500 font-medium">Informasi akademik dan data wali santri</p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 hover:bg-white hover:shadow-md rounded-xl text-gray-400 hover:text-gray-600 transition-all"
                    >
                        <X className="w-6 h-6" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-6 max-h-[80vh] overflow-y-auto custom-scrollbar">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {/* Section 1: Data Santri */}
                        <div className="space-y-4">
                            <h3 className="text-sm font-bold text-blue-600 uppercase tracking-wider border-b border-blue-100 pb-2">Informasi Santri</h3>
                            <div>
                                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Nama Lengkap</label>
                                <div className="relative">
                                    <UserIcon className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                                    <input
                                        required
                                        type="text"
                                        placeholder="Nama sesuai ijazah"
                                        value={formData.name}
                                        onChange={e => setFormData({ ...formData, name: e.target.value })}
                                        className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold"
                                    />
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">NIS</label>
                                    <input
                                        required
                                        type="text"
                                        placeholder="Induk"
                                        value={formData.nis}
                                        onChange={e => setFormData({ ...formData, nis: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold font-mono"
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Kelas</label>
                                    <select
                                        required
                                        value={formData.class_id}
                                        onChange={e => setFormData({ ...formData, class_id: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold appearance-none"
                                    >
                                        <option value="">Pilih...</option>
                                        {classes.map(c => (
                                            <option key={c.id} value={c.id}>{c.name}</option>
                                        ))}
                                    </select>
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">
                                    Email Santri
                                    {santriData ? (
                                        <span className="text-blue-500 normal-case font-normal">(akun login)</span>
                                    ) : (
                                        <span className="text-emerald-500 normal-case font-normal">(auto dari NIS)</span>
                                    )}
                                </label>
                                <div className="relative">
                                    <Mail className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                                    <input
                                        type="email"
                                        placeholder={santriData ? 'Email akun santri' : (formData.nis ? `${formData.nis.toLowerCase().replace(/[^a-z0-9]/g, '')}@santri.pesantren.id` : 'Auto: nis@santri.pesantren.id')}
                                        value={formData.email}
                                        onChange={e => setFormData({ ...formData, email: e.target.value })}
                                        className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold placeholder:text-gray-400 placeholder:font-normal"
                                        readOnly={!!santriData && !!existingEmail} // Readonly if editing with existing email
                                    />
                                </div>
                                {santriData ? (
                                    existingEmail ? (
                                        <p className="text-xs text-blue-500 mt-1">✓ Email sudah terdaftar di sistem</p>
                                    ) : (
                                        <p className="text-xs text-amber-500 mt-1">⚠ Santri belum memiliki akun</p>
                                    )
                                ) : (
                                    <p className="text-xs text-gray-400 mt-1">Kosongkan untuk generate otomatis</p>
                                )}
                            </div>
                            <div>
                                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Jenis Kelamin</label>
                                <div className="flex gap-4">
                                    <button
                                        type="button"
                                        onClick={() => setFormData({ ...formData, gender: 'L' })}
                                        className={`flex-1 flex items-center justify-center gap-2 p-3 border-2 rounded-2xl cursor-pointer transition-all font-bold ${formData.gender === 'L'
                                                ? 'border-blue-600 bg-blue-50 text-blue-600'
                                                : 'border-gray-100 bg-gray-50 text-gray-400 hover:border-gray-200'
                                            }`}
                                    >
                                        LAKI-LAKI
                                    </button>
                                    <button
                                        type="button"
                                        onClick={() => setFormData({ ...formData, gender: 'P' })}
                                        className={`flex-1 flex items-center justify-center gap-2 p-3 border-2 rounded-2xl cursor-pointer transition-all font-bold ${formData.gender === 'P'
                                                ? 'border-pink-600 bg-pink-50 text-pink-600'
                                                : 'border-gray-100 bg-gray-50 text-gray-400 hover:border-gray-200'
                                            }`}
                                    >
                                        PEREMPUAN
                                    </button>
                                </div>
                            </div>
                        </div>

                        {/* Section 2: Data Wali */}
                        <div className="space-y-4">
                            <h3 className="text-sm font-bold text-emerald-600 uppercase tracking-wider border-b border-emerald-100 pb-2">Informasi Wali Santri</h3>
                            <div>
                                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Nama Ayah / Wali</label>
                                <div className="relative">
                                    <UserIcon className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                                    <input
                                        required
                                        type="text"
                                        placeholder="Nama lengkap wali"
                                        value={formData.parent_name}
                                        onChange={e => setFormData({ ...formData, parent_name: e.target.value })}
                                        className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-emerald-500/20 text-gray-900 font-bold"
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">WhatsApp Wali <span className="text-gray-300 normal-case font-normal">(opsional)</span></label>
                                <div className="relative">
                                    <Phone className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                                    <input
                                        type="text"
                                        placeholder="081234..."
                                        value={formData.parent_phone}
                                        onChange={e => setFormData({ ...formData, parent_phone: e.target.value })}
                                        className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-emerald-500/20 text-gray-900 font-bold"
                                    />
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Tempat Lahir <span className="text-gray-300 normal-case font-normal">(opsional)</span></label>
                                    <input
                                        type="text"
                                        placeholder="Kota"
                                        value={formData.birth_place}
                                        onChange={e => setFormData({ ...formData, birth_place: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold"
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Tgl Lahir <span className="text-gray-300 normal-case font-normal">(opsional)</span></label>
                                    <div className="relative">
                                        <Calendar className="w-4 h-4 text-gray-400 absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none" />
                                        <input
                                            type="date"
                                            value={formData.birth_date}
                                            onChange={e => setFormData({ ...formData, birth_date: e.target.value })}
                                            className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold"
                                        />
                                    </div>
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Alamat Lengkap <span className="text-gray-300 normal-case font-normal">(opsional)</span></label>
                                <div className="relative">
                                    <MapPin className="w-5 h-5 text-gray-400 absolute left-4 top-4" />
                                    <textarea
                                        placeholder="Alamat domisili"
                                        rows={2}
                                        value={formData.address}
                                        onChange={e => setFormData({ ...formData, address: e.target.value })}
                                        className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold resize-none"
                                    />
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="pt-6 border-t border-gray-100 flex gap-3">
                        <button
                            type="button"
                            onClick={onClose}
                            className="flex-1 py-4 bg-gray-100 text-gray-600 font-bold rounded-2xl hover:bg-gray-200 transition-all uppercase tracking-widest text-xs"
                        >
                            Batal
                        </button>
                        <button
                            type="submit"
                            disabled={isSubmitting}
                            className="flex-[2] py-4 bg-blue-600 text-white font-bold rounded-2xl hover:bg-blue-700 shadow-xl shadow-blue-500/30 transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? (
                                <Loader2 className="w-5 h-5 animate-spin" />
                            ) : (
                                <Save className="w-5 h-5" />
                            )}
                            {santriData ? 'Simpan Perubahan' : 'Tambah Santri & Auto-Akun Wali'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { X, Save, CalendarDays, Loader2, Clock, BookOpen, User as UserIcon, School } from 'lucide-react';
import { subjectsService, teachersService, classesService, schedulesService } from '@/lib/services';
import type { ScheduleInsert, ScheduleUpdate } from '@/types/database.types';

interface ScheduleModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: ScheduleInsert | ScheduleUpdate) => Promise<void>;
    scheduleData?: any; // If editing
    defaultClassId?: string;
}

const DAYS = [
    { label: 'Senin', value: 1 },
    { label: 'Selasa', value: 2 },
    { label: 'Rabu', value: 3 },
    { label: 'Kamis', value: 4 },
    { label: 'Jumat', value: 5 },
    { label: 'Sabtu', value: 6 },
    { label: 'Minggu', value: 0 },
];

export default function ScheduleModal({ isOpen, onClose, onSubmit, scheduleData, defaultClassId }: ScheduleModalProps) {
    const [formData, setFormData] = useState({
        class_id: '',
        subject_id: '',
        teacher_id: '',
        day_of_week: 1,
        start_time: '07:30',
        end_time: '09:00',
        room: '',
    });

    const [classes, setClasses] = useState<any[]>([]);
    const [subjects, setSubjects] = useState<any[]>([]);
    const [teachers, setTeachers] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);

    useEffect(() => {
        if (isOpen) {
            loadOptions();
            if (scheduleData) {
                setFormData({
                    class_id: scheduleData.class_id || '',
                    subject_id: scheduleData.subject_id || '',
                    teacher_id: scheduleData.teacher_id || '',
                    day_of_week: scheduleData.day_of_week ?? 1,
                    start_time: scheduleData.start_time?.substring(0, 5) || '07:30',
                    end_time: scheduleData.end_time?.substring(0, 5) || '09:00',
                    room: scheduleData.room || '',
                });
            } else {
                setFormData({
                    class_id: defaultClassId || '',
                    subject_id: '',
                    teacher_id: '',
                    day_of_week: 1,
                    start_time: '07:30',
                    end_time: '09:00',
                    room: '',
                });
            }
        }
    }, [isOpen, scheduleData, defaultClassId]);

    const loadOptions = async () => {
        try {
            setIsLoading(true);
            const [fetchedClasses, fetchedSubjects, fetchedTeachers] = await Promise.all([
                classesService.getAll(),
                subjectsService.getAll(true),
                teachersService.getAll({ isActive: true })
            ]);
            setClasses(fetchedClasses);
            setSubjects(fetchedSubjects);
            setTeachers(fetchedTeachers);
        } catch (error) {
            console.error('Error loading schedule options:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);
        try {
            await onSubmit(formData);
            onClose();
        } catch (error) {
            console.error('Error submitting schedule:', error);
            alert('Gagal menyimpan jadwal. Pastikan tidak ada bentrok waktu.');
        } finally {
            setIsSubmitting(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white w-full max-w-xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
                {/* Header */}
                <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-gray-50/50">
                    <div className="flex items-center gap-3">
                        <div className="p-2.5 bg-blue-600 rounded-xl">
                            <CalendarDays className="w-5 h-5 text-white" />
                        </div>
                        <div>
                            <h2 className="text-xl font-bold text-gray-800">{scheduleData ? 'Edit Jadwal' : 'Tambah Jadwal Baru'}</h2>
                            <p className="text-xs text-gray-500 font-medium">Atur waktu belajar mengajar santri</p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 hover:bg-white hover:shadow-md rounded-xl text-gray-400 hover:text-gray-600 transition-all"
                    >
                        <X className="w-6 h-6" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-5">
                    <div className="grid grid-cols-2 gap-4">
                        <div className="col-span-1">
                            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Kelas</label>
                            <div className="relative">
                                <School className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                                <select
                                    required
                                    value={formData.class_id}
                                    onChange={e => setFormData({ ...formData, class_id: e.target.value })}
                                    className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold appearance-none"
                                >
                                    <option value="">Pilih Kelas</option>
                                    {classes.map(c => (
                                        <option key={c.id} value={c.id}>{c.name}</option>
                                    ))}
                                </select>
                            </div>
                        </div>
                        <div className="col-span-1">
                            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Hari</label>
                            <div className="relative">
                                <CalendarDays className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                                <select
                                    required
                                    value={formData.day_of_week}
                                    onChange={e => setFormData({ ...formData, day_of_week: parseInt(e.target.value) })}
                                    className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold appearance-none"
                                >
                                    {DAYS.map(d => (
                                        <option key={d.value} value={d.value}>{d.label}</option>
                                    ))}
                                </select>
                            </div>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Jam Mulai</label>
                            <div className="relative">
                                <Clock className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                                <input
                                    required
                                    type="time"
                                    value={formData.start_time}
                                    onChange={e => setFormData({ ...formData, start_time: e.target.value })}
                                    className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-gray-900 font-bold"
