    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white w-full max-w-xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
                {/* Header */}
                <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-rose-50/50">
                    <div className="flex items-center gap-3">
                        <div className="p-2.5 bg-rose-600 rounded-xl">
                            <AlertTriangle className="w-5 h-5 text-white" />
                        </div>
                        <div>
                            <h2 className="text-xl font-bold text-gray-800">{violationData ? 'Edit Catatan Pelanggaran' : 'Catat Pelanggaran Baru'}</h2>
                            <p className="text-xs text-gray-500 font-medium">Buku Hitam Digital - Kedisiplinan Santri</p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 hover:bg-white hover:shadow-md rounded-xl text-gray-400 hover:text-gray-600 transition-all"
                    >
                        <X className="w-6 h-6" />
                    </button>
                </div>

                <div className="p-6 space-y-5 overflow-y-auto max-h-[80vh]">
                    <form onSubmit={handleSubmit} className="space-y-5">
                        <div className="grid grid-cols-2 gap-4">
                            <div className="col-span-2">
                                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Nama Santri</label>
                                <div className="relative">
                                    <UserIcon className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                                    <select
                                        required
                                        value={formData.student_id}
                                        onChange={e => setFormData({ ...formData, student_id: e.target.value })}
                                        className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-rose-500/20 text-gray-900 font-bold appearance-none"
                                    >
                                        <option value="">Pilih Santri</option>
                                        {students.map(s => (
                                            <option key={s.id} value={s.id}>{s.name} ({s.class?.name || '-'})</option>
                                        ))}
                                    </select>
                                </div>
                            </div>

                            <div>
                                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Tingkat Pelanggaran</label>
                                <select
                                    required
                                    value={formData.type}
                                    onChange={e => handleTypeChange(e.target.value as any)}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-rose-500/20 text-gray-900 font-bold"
                                >
                                    <option value="ringan">Ringan</option>
                                    <option value="sedang">Sedang</option>
                                    <option value="berat">Berat</option>
                                </select>
                            </div>

                            <div>
                                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Poin Pengurang</label>
                                <input
                                    required
                                    type="number"
                                    value={formData.points}
                                    onChange={e => setFormData({ ...formData, points: parseInt(e.target.value) })}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-rose-500/20 text-gray-900 font-bold text-red-600"
                                />
                            </div>

                            <div className="col-span-1">
                                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Tanggal Kejadian</label>
                                <div className="relative">
                                    <Calendar className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                                    <input
                                        required
                                        type="date"
                                        value={formData.date}
                                        onChange={e => setFormData({ ...formData, date: e.target.value })}
                                        className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-rose-500/20 text-gray-900 font-bold"
                                    />
                                </div>
                            </div>

                            <div className="col-span-1">
                                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Status Takzir</label>
                                <select
                                    required
                                    value={formData.status}
                                    onChange={e => setFormData({ ...formData, status: e.target.value as any })}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-rose-500/20 text-gray-900 font-bold"
                                >
                                    <option value="pending">Belum Diproses</option>
                                    <option value="completed">Sudah Dijalankan</option>
                                    <option value="cancelled">Dibatalkan</option>
                                </select>
                            </div>
                        </div>

                        <div>
                            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Deskripsi Pelanggaran</label>
                            <textarea
                                required
                                placeholder="Jelaskan detail pelanggaran..."
                                value={formData.description}
                                onChange={e => setFormData({ ...formData, description: e.target.value })}
                                className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-rose-500/20 text-gray-900 font-medium h-24"
                            />
                        </div>

                        <div>
                            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Hukuman (Takzir)</label>
                            <div className="relative">
                                <ClipboardList className="w-5 h-5 text-gray-400 absolute left-4 top-4" />
                                <textarea
                                    placeholder="Tindakan yang diberikan (takzir)..."
                                    value={formData.punishment}
                                    onChange={e => setFormData({ ...formData, punishment: e.target.value })}
                                    className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-rose-500/20 text-gray-900 font-medium h-20"
                                />
                            </div>
                        </div>

                        <div className="pt-4 flex gap-3">
                            <button
                                type="button"
                                onClick={onClose}
                                className="flex-1 py-3.5 bg-gray-100 text-gray-600 font-bold rounded-2xl hover:bg-gray-200 transition-all uppercase tracking-widest text-xs"
                            >
                                Batal
                            </button>
                            <button
                                type="submit"
                                disabled={isSubmitting || isLoading}
                                className="flex-[2] py-3.5 bg-rose-600 text-white font-bold rounded-2xl hover:bg-rose-700 shadow-lg shadow-rose-500/30 transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-2"
                            >
                                {isSubmitting ? (
                                    <Loader2 className="w-4 h-4 animate-spin" />
                                ) : (
                                    <Save className="w-4 h-4" />
                                )}
                                {violationData ? 'Simpan Perubahan' : 'Catat Pelanggaran'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import { X, Plus, Loader2, BookOpen } from 'lucide-react';
import { hafalanTypesService, HafalanType } from '@/lib/services/hafalan-types';
import { hafalanService } from '@/lib/services/hafalan';
import { useEffect } from 'react';

interface AssignProgramModalProps {
    isOpen: boolean;
    onClose: () => void;
    onAssign: (hafalanTypeId: string, notes?: string) => Promise<void>;
    studentName: string;
}

export default function AssignProgramModal({ isOpen, onClose, onAssign, studentName }: AssignProgramModalProps) {
    const [hafalanTypes, setHafalanTypes] = useState<HafalanType[]>([]);
    const [selectedTypeId, setSelectedTypeId] = useState('');
    const [notes, setNotes] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        if (isOpen) {
            fetchHafalanTypes();
            setSelectedTypeId('');
            setNotes('');
            setError('');
        }
    }, [isOpen]);

    const fetchHafalanTypes = async () => {
        try {
            setIsLoading(true);
            const types = await hafalanTypesService.getAll();
            setHafalanTypes(types);
        } catch (error) {
            console.error('Error fetching hafalan types:', error);
            setError('Gagal memuat daftar hafalan types');
        } finally {
            setIsLoading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!selectedTypeId) {
            setError('Pilih jenis hafalan terlebih dahulu');
            return;
        }

        try {
            setIsSaving(true);
            setError('');
            await onAssign(selectedTypeId, notes);
            onClose();
        } catch (err: any) {
            setError(err.message || 'Gagal menugaskan program hafalan');
        } finally {
            setIsSaving(false);
        }
    };

    if (!isOpen) return null;

    const selectedType = hafalanTypes.find(t => t.id === selectedTypeId);

    return (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl">
                {/* Header */}
                <div className="p-6 border-b border-gray-100 flex items-center justify-between">
                    <div>
                        <h3 className="text-xl font-bold text-gray-800">Tugaskan Program Hafalan</h3>
                        <p className="text-sm text-gray-500 mt-1">Untuk: <span className="font-semibold text-indigo-600">{studentName}</span></p>
                    </div>
                    <button
                        onClick={onClose}
                        className="text-gray-400 hover:text-gray-600 transition-colors"
                    >
                        <X className="w-6 h-6" />
                    </button>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="p-6">
                    {error && (
                        <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-xl text-red-700 text-sm">
                            {error}
                        </div>
                    )}

                    {isLoading ? (
                        <div className="py-8 text-center">
                            <Loader2 className="w-8 h-8 text-indigo-600 animate-spin mx-auto mb-3" />
                            <p className="text-gray-500">Memuat daftar hafalan...</p>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {/* Pilih Hafalan Type */}
                            <div>
                                <label className="block text-sm font-semibold text-gray-700 mb-2">
                                    Jenis Hafalan <span className="text-red-500">*</span>
                                </label>
                                <select
                                    value={selectedTypeId}
                                    onChange={(e) => setSelectedTypeId(e.target.value)}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 text-gray-900"
                                    required
                                >
                                    <option value="">-- Pilih Jenis Hafalan --</option>
                                    {hafalanTypes.map(type => (
                                        <option key={type.id} value={type.id}>
                                            {type.name} ({type.total_units} {type.unit_name})
                                        </option>
                                    ))}
                                </select>
                            </div>

                            {/* Detail Hafalan Type */}
                            {selectedType && (
                                <div className="p-4 bg-indigo-50 border border-indigo-200 rounded-xl">
                                    <div className="flex items-start gap-3">
                                        <BookOpen className="w-5 h-5 text-indigo-600 mt-0.5" />
                                        <div className="flex-1">
                                            <p className="font-semibold text-indigo-900">{selectedType.name}</p>
                                            <p className="text-sm text-indigo-700 mt-1">{selectedType.description}</p>
                                            <div className="flex items-center gap-4 mt-2 text-xs text-indigo-600">
                                                <span className="px-2 py-1 bg-indigo-100 rounded-full font-medium">
                                                    {selectedType.total_units} {selectedType.unit_name}
                                                </span>
                                                <span className="px-2 py-1 bg-indigo-100 rounded-full font-medium capitalize">
                                                    {selectedType.category}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}

                            {/* Catatan */}
                            <div>
                                <label className="block text-sm font-semibold text-gray-700 mb-2">
                                    Catatan (Opsional)
                                </label>
                                <textarea
                                    value={notes}
                                    onChange={(e) => setNotes(e.target.value)}
                                    placeholder="Tambahkan catatan khusus untuk santri ini..."
                                    rows={3}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 text-gray-900 resize-none"
                                />
                            </div>
                        </div>
                    )}
                </form>

                {/* Footer */}
                <div className="p-6 border-t border-gray-100 flex items-center justify-end gap-3">
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-6 py-3 border border-gray-200 text-gray-700 font-medium rounded-xl hover:bg-gray-50 transition-colors"
                        disabled={isSaving}
                    >
                        Batal
                    </button>
                    <button
                        onClick={handleSubmit}
                        disabled={isSaving || isLoading || !selectedTypeId}
                        className="px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-semibold rounded-xl transition-colors flex items-center gap-2 disabled:opacity-50"
                    >
                        {isSaving ? (
                            <>
                                <Loader2 className="w-5 h-5 animate-spin" />
                                Menugaskan...
                            </>
                        ) : (
                            <>
                                <Plus className="w-5 h-5" />
                                Tugaskan Program
                            </>
                        )}
                    </button>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { X, Save, Loader2 } from 'lucide-react';
import { HafalanType } from '@/lib/services/hafalan-types';

interface HafalanTypeModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSave: (data: Omit<HafalanType, 'id' | 'created_at' | 'updated_at'>) => Promise<void>;
    editData?: HafalanType | null;
}

const CATEGORIES = [
    { value: 'quran', label: 'Al-Qur\'an', color: 'blue' },
    { value: 'doa', label: 'Doa', color: 'green' },
    { value: 'mufrodat', label: 'Mufrodat (Kosakata)', color: 'purple' },
    { value: 'hadits', label: 'Hadits', color: 'amber' },
    { value: 'nadhom', label: 'Nadhom (Syair)', color: 'pink' },
    { value: 'other', label: 'Lainnya', color: 'gray' }
];

export default function HafalanTypeModal({ isOpen, onClose, onSave, editData }: HafalanTypeModalProps) {
    const [formData, setFormData] = useState({
        name: '',
        description: '',
        category: 'quran' as HafalanType['category'],
        total_units: 1,
        unit_name: '',
        is_active: true
    });
    const [isSaving, setIsSaving] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        if (editData) {
            setFormData({
                name: editData.name,
                description: editData.description,
                category: editData.category,
                total_units: editData.total_units,
                unit_name: editData.unit_name,
                is_active: editData.is_active
            });
        } else {
            setFormData({
                name: '',
                description: '',
                category: 'quran',
                total_units: 1,
                unit_name: '',
                is_active: true
            });
        }
        setError('');
    }, [editData, isOpen]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        // Validation
        if (!formData.name.trim()) {
            setError('Nama hafalan harus diisi');
            return;
        }
        if (!formData.unit_name.trim()) {
            setError('Nama unit harus diisi');
            return;
        }
        if (formData.total_units < 1) {
            setError('Jumlah unit minimal 1');
            return;
        }

        try {
            setIsSaving(true);
            await onSave(formData);
            onClose();
        } catch (err: any) {
            setError(err.message || 'Gagal menyimpan data');
        } finally {
            setIsSaving(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl w-full max-w-2xl shadow-2xl max-h-[90vh] overflow-hidden">
                {/* Header */}
                <div className="p-6 border-b border-gray-100 flex items-center justify-between">
                    <h3 className="text-xl font-bold text-gray-800">
                        {editData ? 'Edit Hafalan Type' : 'Tambah Hafalan Type Baru'}
                    </h3>
                    <button
                        onClick={onClose}
                        className="text-gray-400 hover:text-gray-600 transition-colors"
                    >
                        <X className="w-6 h-6" />
                    </button>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="p-6 overflow-y-auto max-h-[calc(90vh-140px)]">
                    {error && (
                        <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-xl text-red-700 text-sm">
                            {error}
                        </div>
                    )}

                    <div className="space-y-4">
                        {/* Nama Hafalan */}
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                Nama Hafalan <span className="text-red-500">*</span>
                            </label>
                            <input
                                type="text"
                                value={formData.name}
                                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                placeholder="Contoh: Al-Qur'an 30 Juz"
                                className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 text-gray-900"
                                required
                            />
                        </div>

                        {/* Kategori */}
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                Kategori <span className="text-red-500">*</span>
                            </label>
                            <select
                                value={formData.category}
                                onChange={(e) => setFormData({ ...formData, category: e.target.value as HafalanType['category'] })}
                                className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 text-gray-900"
                                required
                            >
                                {CATEGORIES.map(cat => (
                                    <option key={cat.value} value={cat.value}>
                                        {cat.label}
                                    </option>
                                ))}
                            </select>
                        </div>

                        {/* Deskripsi */}
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                Deskripsi
                            </label>
                            <textarea
                                value={formData.description}
                                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                placeholder="Deskripsi singkat tentang hafalan ini..."
                                rows={3}
                                className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 text-gray-900 resize-none"
                            />
                        </div>

                        {/* Jumlah Unit & Nama Unit */}
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-semibold text-gray-700 mb-2">
                                    Jumlah Unit <span className="text-red-500">*</span>
                                </label>
                                <input
                                    type="number"
                                    min="1"
                                    value={formData.total_units}
                                    onChange={(e) => setFormData({ ...formData, total_units: parseInt(e.target.value) || 1 })}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 text-gray-900"
                                    required
                                />
                                <p className="text-xs text-gray-500 mt-1">Contoh: 30 untuk 30 Juz</p>
                            </div>

                            <div>
                                <label className="block text-sm font-semibold text-gray-700 mb-2">
                                    Nama Unit <span className="text-red-500">*</span>
                                </label>
                                <input
                                    type="text"
                                    value={formData.unit_name}
                                    onChange={(e) => setFormData({ ...formData, unit_name: e.target.value })}
                                    placeholder="Contoh: Juz, Surah, Bab"
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 text-gray-900"
                                    required
                                />
                                <p className="text-xs text-gray-500 mt-1">Satuan unit hafalan</p>
                            </div>
                        </div>

                        {/* Status */}
                        <div>
                            <label className="flex items-center gap-3 cursor-pointer">
                                <input
                                    type="checkbox"
                                    checked={formData.is_active}
                                    onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                                    className="w-5 h-5 text-indigo-600 bg-gray-50 border-gray-300 rounded focus:ring-2 focus:ring-indigo-500"
                                />
                                <span className="text-sm font-medium text-gray-700">
                                    Aktif (dapat digunakan untuk program hafalan)
                                </span>
                            </label>
                        </div>
                    </div>
                </form>

                {/* Footer */}
                <div className="p-6 border-t border-gray-100 flex items-center justify-end gap-3">
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-6 py-3 border border-gray-200 text-gray-700 font-medium rounded-xl hover:bg-gray-50 transition-colors"
                        disabled={isSaving}
                    >
                        Batal
                    </button>
                    <button
                        onClick={handleSubmit}
                        disabled={isSaving}
                        className="px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-semibold rounded-xl transition-colors flex items-center gap-2 disabled:opacity-50"
                    >
                        {isSaving ? (
                            <>
                                <Loader2 className="w-5 h-5 animate-spin" />
                                Menyimpan...
                            </>
                        ) : (
                            <>
                                <Save className="w-5 h-5" />
                                Simpan
                            </>
                        )}
                    </button>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import { usePathname } from 'next/navigation';
import Link from 'next/link';
import { LogOut, Menu, Bell, RefreshCw, ChevronDown, Sparkles } from 'lucide-react';
import {
    User,
    ROLE_NAMES,
    UserRole,
    getAvailableRoles,
    getEffectiveRole,
    switchRole,
    getRoleDisplayText
} from '@/lib/auth';
import {
    getNavigationForRole,
    isNavItemActive,
    getAccentClasses,
    NavItem,
    RoleNavigation
} from '@/lib/navigation';

// ============================================
// Types
// ============================================

interface SidebarProps {
    user: User;
    isOpen: boolean;
    onClose: () => void;
    onLogout: () => void;
}

// ============================================
// Sidebar Component
// ============================================

export default function Sidebar({ user, isOpen, onClose, onLogout }: SidebarProps) {
    const pathname = usePathname();
    const [showRoleSwitcher, setShowRoleSwitcher] = useState(false);

    if (!user) return null;

    // Get effective role (active or primary)
    const effectiveRole = getEffectiveRole(user) || user.role;
    const availableRoles = getAvailableRoles(user);
    const hasMultipleRoles = availableRoles.length > 1;

    const navigation = getNavigationForRole(effectiveRole);
    const accentClasses = getAccentClasses(navigation.accentColor);

    const handleSwitchRole = (role: UserRole) => {
        setShowRoleSwitcher(false);
        switchRole(role);
    };

    return (
        <>
