                                className={`group w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all duration-300 relative overflow-hidden ${isActive
                                    ? `bg-[#0a0a0a] border border-neutral-800 shadow-[0_10px_20px_rgba(0,0,0,0.2)]`
