'use client';

import { useRef, useMemo, useState, useEffect } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Float, MeshDistortMaterial, Sphere, GradientTexture, Stars, Torus } from '@react-three/drei';
import * as THREE from 'three';
import MobileFallbackBackground from './MobileFallbackBackground';

function AnimatedSphere() {
    const meshRef = useRef<THREE.Mesh>(null);

    useFrame((state) => {
        if (meshRef.current) {
            meshRef.current.rotation.x = state.clock.getElapsedTime() * 0.2;
            meshRef.current.rotation.y = state.clock.getElapsedTime() * 0.3;
        }
    });

    return (
        /* @ts-ignore */
        <Float speed={2} rotationIntensity={1} floatIntensity={2}>
            /* @ts-ignore */
            <Sphere ref={meshRef} args={[1.5, 64, 64]} scale={1.2}>
                /* @ts-ignore */
                <MeshDistortMaterial
                    distort={0.4}
                    speed={4}
                    roughness={0.2}
                    metalness={0.8}
                    color="#f97316"
                >
                    /* @ts-ignore */
                    <GradientTexture
                        stops={[0, 1]}
                        colors={['#f97316', '#7c2d12']}
                    />
                /* @ts-ignore */
                </MeshDistortMaterial>
            /* @ts-ignore */
            </Sphere>
        /* @ts-ignore */
        </Float>
    );
}

function Rings() {
    return (
        <group>
            {[...Array(3)].map((_, i) => (
                /* @ts-ignore */
                <Float key={i} speed={1} rotationIntensity={0.5} floatIntensity={0.5}>
                    /* @ts-ignore */
                    <Torus args={[3 + i * 1, 0.02, 16, 100]} rotation={[Math.random() * Math.PI, Math.random() * Math.PI, 0]}>
                        /* @ts-ignore */
                        <meshBasicMaterial color="#f97316" transparent opacity={0.1 - i * 0.02} />
                    /* @ts-ignore */
                    </Torus>
                </Float>
            ))}
        </group>
    );
}

function Particles({ count = 2000 }) {
    const points = useMemo(() => {
        const p = new Float32Array(count * 3);
        for (let i = 0; i < count; i++) {
            p[i * 3] = (Math.random() - 0.5) * 15;
            p[i * 3 + 1] = (Math.random() - 0.5) * 15;
            p[i * 3 + 2] = (Math.random() - 0.5) * 15;
        }
        return p;
    }, [count]);

    return (
        /* @ts-ignore */
        <points>
            {/* @ts-ignore */}
            <bufferGeometry>
                {/* @ts-ignore */}
                <bufferAttribute
                    attach="attributes-position"
                    args={[points, 3]}
                />
                {/* @ts-ignore */}
            </bufferGeometry>
            {/* @ts-ignore */}
            <pointsMaterial size={0.03} color="#f97316" transparent opacity={0.4} sizeAttenuation />
            {/* @ts-ignore */}
        </points>
    );
}

export default function LoginHero3D() {
    const [isMobile, setIsMobile] = useState(false);
    const [isClient, setIsClient] = useState(false);

    useEffect(() => {
        setIsClient(true);
        // Detect mobile devices or Capacitor environment
        const checkMobile = () => {
            const userAgent = navigator.userAgent || navigator.vendor;
            const isMobileDevice = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(userAgent);
            const isSmallScreen = window.innerWidth < 900; // Lower threshold to catch "Desktop Mode" (usually 980px)
            const isCapacitor = typeof (window as any).Capacitor !== 'undefined';

            // If it's a mobile device but has a LARGE screen (Desktop Mode), don't treat as mobile
            if (isMobileDevice && !isSmallScreen) return false;

            return isMobileDevice || isSmallScreen || isCapacitor;
        };
        setIsMobile(checkMobile());

        const handleResize = () => setIsMobile(checkMobile());
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Server-side render nothing, client will hydrate
    if (!isClient) {
        return <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none bg-[#050505]" />;
    }

    // Use lightweight CSS fallback for mobile devices
    if (isMobile) {
        return <MobileFallbackBackground />;
    }

    return (
        <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none">
            {/* @ts-ignore */}
            <Canvas camera={{ position: [0, 0, 8], fov: 75 }}>
                {/* @ts-ignore */}
                <ambientLight intensity={0.5} />
                {/* @ts-ignore */}
                <pointLight position={[10, 10, 10]} intensity={1.5} color="#f97316" />
                {/* @ts-ignore */}
                <pointLight position={[-10, -10, -10]} intensity={0.5} color="#7c2d12" />
                {/* @ts-ignore */}
                <Stars radius={100} depth={50} count={3000} factor={4} saturation={0} fade speed={1} />
                {/* @ts-ignore */}
                <AnimatedSphere />
                {/* @ts-ignore */}
                <Rings />
                {/* @ts-ignore */}
                <Particles count={1500} />
                {/* @ts-ignore */}
                <fog attach="fog" args={['#050505', 5, 20]} />
            </Canvas>
        </div>
    );
}

'use client';

/**
 * Mobile Fallback Background
 * A lightweight CSS-only animated background for mobile devices
 * to replace the heavy 3D WebGL animation
 */
export default function MobileFallbackBackground() {
    return (
        <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none bg-transparent">
            {/* Animated Gradient Orbs */}
            <div className="absolute top-1/4 left-1/4 w-64 h-64 bg-orange-600/20 rounded-full blur-[100px] animate-pulse" />
            <div className="absolute bottom-1/4 right-1/4 w-48 h-48 bg-amber-500/15 rounded-full blur-[80px] animate-pulse" style={{ animationDelay: '1s' }} />
            <div className="absolute top-1/2 right-1/3 w-32 h-32 bg-orange-400/10 rounded-full blur-[60px] animate-pulse" style={{ animationDelay: '2s' }} />

            {/* Floating Particles */}
            {[...Array(15)].map((_, i) => (
                <div
                    key={i}
                    className="absolute w-1 h-1 bg-orange-500/30 rounded-full animate-float"
                    style={{
                        top: `${Math.random() * 100}%`,
                        left: `${Math.random() * 100}%`,
                        animationDelay: `${Math.random() * 5}s`,
                        animationDuration: `${4 + Math.random() * 4}s`
                    }}
                />
            ))}

            {/* Orbital Ring Effect */}
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2">
                <div className="w-48 h-48 border border-orange-500/10 rounded-full animate-spin-slow" />
                <div className="absolute inset-4 border border-orange-500/5 rounded-full animate-spin-reverse" />
            </div>

            {/* Grid Pattern Overlay */}
            <div
                className="absolute inset-0 opacity-[0.02]"
                style={{
                    backgroundImage: `
                        linear-gradient(rgba(249,115,22,0.1) 1px, transparent 1px),
                        linear-gradient(90deg, rgba(249,115,22,0.1) 1px, transparent 1px)
                    `,
                    backgroundSize: '50px 50px'
                }}
            />
        </div>
    );
}

'use client';

import { forwardRef } from 'react';
import { convertGrade } from '@/lib/gradeConverter';
import { RaporConfig, StudentRaporData, getSemesterName } from '@/lib/raporConfig';

// ============================================
// Props Interface
// ============================================

interface RaporSheetProps {
    settings: RaporConfig;
    student: StudentRaporData;
    semester: 1 | 2;
}

// ============================================
// Component - F4 Paper (215mm x 330mm)
// Layout sesuai referensi user
// ============================================

const RaporSheet = forwardRef<HTMLDivElement, RaporSheetProps>(
    ({ settings, student, semester }, ref) => {
        // Use real grades from student data
        const mapelAgama = student.grades
            .filter(g => g.category === 'agama')
            .map(g => ({ subject: g.subject, score: g.score }));

        const mapelUmum = student.grades
            .filter(g => g.category === 'umum')
            .map(g => ({ subject: g.subject, score: g.score }));

        // Apply grade conversion
        const agamaWithConversion = mapelAgama.map(g => ({
            ...g,
            conversion: convertGrade(g.score),
        }));

        const umumWithConversion = mapelUmum.map(g => ({
            ...g,
            conversion: convertGrade(g.score),
        }));

        const allGrades = [...agamaWithConversion, ...umumWithConversion];

        // Calculate total and average
        const totalScore = allGrades.reduce((sum, g) => sum + g.score, 0);
        const average = Math.round(totalScore / allGrades.length);
        const averageConversion = convertGrade(average);

        // Format current date
        const formatDate = () => {
            const now = new Date();
            return now.toLocaleDateString('id-ID', {
                day: 'numeric',
                month: 'long',
                year: 'numeric'
            });
        };

        // Semester 2 logic
        const isSemester2 = semester === 2;
        const isPromoted = student.promotion?.isPromoted ?? true;
        const nextClass = student.promotion?.nextClass || (parseInt(student.class) + 1).toString();

        // Placeholder data
        const kepribadian = { Kelakuan: 'Baik', Kerajinan: 'Baik', Kerapihan: 'Baik' };
        const ranking = 3;
        const catatan = 'Pertahankan prestasi dan tingkatkan hafalan Al-Quran. Terus semangat dalam belajar.';

        // Convert to Arabic digits
        const toArabicDigits = (num: number): string => {
            const arabicDigits = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
            return num.toString().split('').map(d => arabicDigits[parseInt(d)] || d).join('');
        };

        return (
            <>
                {/* Print Styles - F4 Paper */}
                <style jsx global>{`
                    @import url('https://fonts.googleapis.com/css2?family=Amiri:wght@400;700&display=swap');
                    
                    @media print {
                        @page {
                            size: 215mm 330mm;
                            margin: 0;
                        }
                        html, body {
                            margin: 0 !important;
                            padding: 0 !important;
                            -webkit-print-color-adjust: exact !important;
                            print-color-adjust: exact !important;
                        }
                        .no-print { display: none !important; }
                        .rapor-page {
                            width: 215mm !important;
                            height: 330mm !important;
                            overflow: hidden !important;
                            page-break-after: always;
                        }
                    }
                    .font-arabic {
                        font-family: 'Amiri', 'Traditional Arabic', serif;
                    }
                `}</style>

                {/* RAPOR CONTAINER */}
                <div
                    ref={ref}
                    className="rapor-page bg-white mx-auto"
                    style={{
                        width: '215mm',
                        height: '330mm',
                        padding: '10mm 12mm',
                        fontFamily: "'Times New Roman', Times, serif",
                        color: '#000',
                        display: 'flex',
                        flexDirection: 'column',
                        boxSizing: 'border-box',
                    }}
                >
                    {/* ============================================ */}
                    {/* HEADER / KOP SURAT */}
                    {/* ============================================ */}
                    <div style={{ marginBottom: '8px' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
