export interface ScheduleWithRelations extends Schedule {
    class?: { id: string; name: string } | null;
    subject?: { id: string; name: string; code: string } | null;
    teacher?: { id: string; name: string } | null;
}

const DAY_NAMES = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

export const schedulesService = {
    async getAll(): Promise<ScheduleWithRelations[]> {
        const { data, error } = await supabase
            .from('schedules')
            .select(`
                *,
                class:classes(id, name),
                subject:subjects(id, name, code),
                teacher:teachers(id, name)
            `)
            .order('day_of_week')
            .order('start_time');

        if (error) throw error;
        return data || [];
    },

    async getByClass(classId: string): Promise<ScheduleWithRelations[]> {
        const { data, error } = await supabase
            .from('schedules')
            .select(`
                *,
                subject:subjects(id, name, code),
                teacher:teachers(id, name)
            `)
            .eq('class_id', classId)
            .order('day_of_week')
            .order('start_time');

        if (error) throw error;
        return data || [];
    },

    async getByTeacher(teacherId: string): Promise<ScheduleWithRelations[]> {
        const { data, error } = await supabase
            .from('schedules')
            .select(`
                *,
                class:classes(id, name),
                subject:subjects(id, name, code)
            `)
            .eq('teacher_id', teacherId)
            .order('day_of_week')
            .order('start_time');

        if (error) throw error;
        return data || [];
    },

    async getByDay(dayOfWeek: number, classId?: string): Promise<ScheduleWithRelations[]> {
        let query = supabase
            .from('schedules')
            .select(`
                *,
                class:classes(id, name),
                subject:subjects(id, name, code),
                teacher:teachers(id, name)
            `)
            .eq('day_of_week', dayOfWeek)
            .order('start_time');

        if (classId) query = query.eq('class_id', classId);

        const { data, error } = await query;
        if (error) throw error;
        return data || [];
    },

    async create(schedule: ScheduleInsert): Promise<Schedule> {
        const { data, error } = await supabase
            .from('schedules')
            .insert(schedule)
            .select()
            .single();
        if (error) throw error;
        return data;
    },

    async update(id: string, updates: ScheduleUpdate): Promise<Schedule> {
        const { data, error } = await supabase
            .from('schedules')
            .update(updates)
            .eq('id', id)
            .select()
            .single();
        if (error) throw error;
        return data;
    },

    async delete(id: string): Promise<void> {
        const { error } = await supabase
            .from('schedules')
            .delete()
            .eq('id', id);
        if (error) throw error;
    },

    async checkConflict(classId: string, dayOfWeek: number, startTime: string, endTime: string, excludeId?: string): Promise<boolean> {
        let query = supabase
            .from('schedules')
            .select('id')
            .eq('class_id', classId)
            .eq('day_of_week', dayOfWeek)
            .or(`and(start_time.lt.${endTime},end_time.gt.${startTime})`);

        if (excludeId) query = query.neq('id', excludeId);

        const { data, error } = await query;
        if (error) throw error;
        return (data?.length || 0) > 0;
    },

    getDayName(dayOfWeek: number): string {
        return DAY_NAMES[dayOfWeek] || 'Unknown';
    },

    getDayNames(): string[] {
        return DAY_NAMES;
    },
};

