    async getStudents(classId: string) {
        console.log('Fetching students for classId:', classId);
        const { data, error } = await supabase
            .from('students')
            .select('id, name, nis, gender, birth_place, birth_date, status')
            .eq('class_id', classId)
            .order('name', { ascending: true });

        if (error) {
