            // Don't throw, just return empty to prevent crash
            return [];
        }
        console.log('Fetched students count:', data?.length);
        return data || [];
    },

    async getAttendanceSummary(classId: string) {
        const today = new Date().toISOString().split('T')[0];

        // Join with students to filter by class
        const { data, error } = await supabase
            .from('attendance')
            .select(`
                status,
                students!inner(class_id)
            `)
            .eq('date', today)
            .eq('students.class_id', classId);

        if (error) throw error;

        const summary = {
            'Hadir': 0,
            'Sakit': 0,
            'Izin': 0,
            'Alpha': 0,
        };

        const colors: Record<string, string> = {
            'Hadir': '#10b981',
            'Sakit': '#f59e0b',
            'Izin': '#3b82f6',
            'Alpha': '#ef4444',
        };

        data?.forEach((a: any) => {
            const status = (a.status.charAt(0).toUpperCase() + a.status.slice(1)) as keyof typeof summary;
            if (summary[status] !== undefined) summary[status]++;
        });

        return Object.entries(summary).map(([name, value]) => ({
            name,
            value,
            color: colors[name]
        }));
    },

    async getGradeSummary(classId: string) {
        const { data, error } = await supabase
            .from('grades')
            .select(`
                score,
                subjects(name),
                students!inner(class_id)
            `)
            .eq('students.class_id', classId);

        if (error) throw error;

        const subjectSums: Record<string, { total: number, count: number }> = {};
        data?.forEach((g: any) => {
            const name = g.subjects?.name || 'Unknown';
            if (!subjectSums[name]) subjectSums[name] = { total: 0, count: 0 };
            subjectSums[name].total += Number(g.score);
            subjectSums[name].count += 1;
        });

        return Object.entries(subjectSums).map(([subject, stats]) => ({
            subject,
            score: Math.round(stats.total / stats.count)
        })).sort((a, b) => b.score - a.score).slice(0, 5);
    },

    async getTopViolations(classId: string) {
        const { data, error } = await supabase
            .from('violations')
            .select(`
                points,
                students!inner(name, class_id)
            `)
            .eq('students.class_id', classId);

        if (error) throw error;

        const studentPoints: Record<string, number> = {};
        data?.forEach((v: any) => {
            const name = v.students?.name || 'Unknown';
            studentPoints[name] = (studentPoints[name] || 0) + v.points;
        });

        const colors = ['bg-red-500', 'bg-orange-500', 'bg-amber-500', 'bg-yellow-500', 'bg-rose-500'];

        return Object.entries(studentPoints)
            .map(([name, points], i) => ({
                name,
                points,
                color: colors[i % colors.length]
            }))
            .sort((a, b) => b.points - a.points)
            .slice(0, 5);
    }
};

