            if (!teacherId) return [];

            const { data, error } = await supabase
                .from('schedules')
                .select(`
                    subject_id,
                    subjects (id, name)
                `)
                .eq('teacher_id', teacherId);

            if (error) throw error;

            const uniqueSubjects = Array.from(new Set(data.map(d => d.subject_id)))
                .map(id => {
