    async getMyStudents(userId: string) {
        try {
            const teacherId = await this.getTeacherId(userId);
            if (!teacherId) return [];

            const { data: classData } = await supabase
                .from('schedules')
                .select('class_id')
                .eq('teacher_id', teacherId);

            const classIds = Array.from(new Set(classData?.map(d => d.class_id) || []));
            if (classIds.length === 0) return [];

            const { data: students, error: studentError } = await supabase
                .from('students')
                .select(`
                    id, name, nis, class_id, 
                    classes (id, name)
                `)
                .in('class_id', classIds)
                .eq('status', 'active')
                .order('name');

            if (studentError || !students) throw studentError || new Error('No students found');

            const studentIds = students.map(s => s.id);
            const { data: progressData } = await supabase
                .from('hafalan_progress')
                .select('student_id, unit_number, grade')
                .in('student_id', studentIds)
                .order('created_at', { ascending: true });

            return students.map(s => {
                const studentProgress = progressData?.filter(p => p.student_id === s.id) || [];
                // Sort locally to get latest by creation
                const latest = studentProgress.length > 0 ? studentProgress[studentProgress.length - 1] : null;

                return {
                    id: s.id,
                    name: s.name,
                    class: (s.classes as any)?.name || '-',
                    lastJuz: latest ? latest.unit_number : '-',
                    totalJuz: studentProgress.length,
                    status: latest && (latest.grade === 'A' || latest.grade === 'B') ? 'Lancar' : studentProgress.length > 0 ? 'Perlu Muraja\'ah' : 'Baru'
                };
            });
        } catch (err) {
            console.error('Error in getMyStudents:', err);
            return [];
        }
    },

    async getDashboardStats(userId: string) {
        try {
            const teacherId = await this.getTeacherId(userId);
            if (!teacherId) return { totalStudents: 0, totalSubjects: 0, activeSchedules: 0, totalHafalan: 0 };

            const [students, subjects, schedules, hafalan] = await Promise.all([
                supabase.from('schedules').select('class_id').eq('teacher_id', teacherId),
                supabase.from('schedules').select('subject_id').eq('teacher_id', teacherId),
                supabase.from('schedules').select('id').eq('teacher_id', teacherId),
                supabase.from('hafalan_progress').select('id').eq('evaluated_by', userId)
            ]);

            // Approximate student count by classes taught
            const classIds = Array.from(new Set((students.data || []).map(s => s.class_id)));
            const { count: studentCount } = await supabase
                .from('students')
                .select('id', { count: 'exact', head: true })
                .in('class_id', classIds);

            return {
                totalStudents: studentCount || 0,
                totalSubjects: new Set((subjects.data || []).map(s => s.subject_id)).size,
                activeSchedules: (schedules.data || []).length,
                totalHafalan: (hafalan.data || []).length
            };
        } catch (err) {
            console.error('Error in getDashboardStats:', err);
            return { totalStudents: 0, totalSubjects: 0, activeSchedules: 0, totalHafalan: 0 };
        }
    }
};

import { supabase } from '../supabase';

export interface Violation {
    id: string;
    student_id: string;
    category: 'ringan' | 'sedang' | 'berat';
    description?: string;
    points: number;
    reported_by?: string;
    violation_date: string;
    status: 'pending' | 'completed' | 'cancelled';
    punishment?: string;
    created_at: string;
}

export interface ViolationWithRelations extends Violation {
    students?: {
        id: string;
        name: string;
        classes?: {
            id: string;
            name: string;
        } | null;
    } | null;
}

export const violationsService = {
    async getAll(): Promise<ViolationWithRelations[]> {
        const { data, error } = await supabase
            .from('violations')
            .select(`
                *,
                students (
                    id,
                    name,
                    classes (
                        id,
                        name
                    )
                )
            `)
            .order('violation_date', { ascending: false });

        if (error) throw error;
        return (data || []) as unknown as ViolationWithRelations[];
    },

    async getById(id: string): Promise<ViolationWithRelations | null> {
        const { data, error } = await supabase
            .from('violations')
            .select(`
                *,
                students (
                    id,
                    name,
                    classes (
                        id,
                        name
                    )
                )
            `)
            .eq('id', id)
            .single();

        if (error) {
            if (error.code === 'PGRST116') return null;
            throw error;
        }
        return data as unknown as ViolationWithRelations;
    },

    async create(violation: any): Promise<Violation> {
        const { requirePesantrenId } = await import('./helpers');
        const pesantrenId = await requirePesantrenId(violation.pesantren_id);

        const { data, error } = await supabase
            .from('violations')
            .insert({
                student_id: violation.student_id,
                category: violation.type || violation.category,
                description: violation.description || null,
                points: violation.points || 0,
                reported_by: violation.recorded_by || violation.reported_by || null,
                violation_date: violation.date || violation.violation_date || new Date().toISOString().split('T')[0],
                status: violation.status || 'pending',
                // punishment: violation.punishment || null, // punishment column might not exist in new schema? let's omit if not in schema-additional or create script
                pesantren_id: pesantrenId
            })
            .select()
            .single();

        if (error) throw error;
        return data as unknown as Violation;
    },

    async update(id: string, updates: any): Promise<Violation> {
        // Map updates to DB columns
        const dbUpdates: any = { ...updates };
        if (updates.type) dbUpdates.category = updates.type;
        if (updates.date) dbUpdates.violation_date = updates.date;
        if (updates.recorded_by) dbUpdates.reported_by = updates.recorded_by;

        delete dbUpdates.type;
        delete dbUpdates.date;
        delete dbUpdates.recorded_by;

        const { data, error } = await supabase
            .from('violations')
            .update(dbUpdates)
            .eq('id', id)
            .select()
            .single();

        if (error) throw error;
        return data as unknown as Violation;
    },

    async delete(id: string): Promise<void> {
        const { error } = await supabase
            .from('violations')
            .delete()
            .eq('id', id);

        if (error) throw error;
    }
};

